def moving_average(data, window_size):
    if len(data) < window_size:
        return sum(data) / len(data) if data else 0
    return sum(data[-window_size:]) / window_size

def log_data(temperature, humidity, adc0, adc1):
    try:
        with open(CSV_FILE, "a", newline="") as csvfile:
            writer = csv.writer(csvfile)
            timestamp = datetime.datetime.now().isoformat()
            writer.writerow([timestamp, temperature, humidity, adc0, adc1])
    except Exception as e:
        log_error(f"CSV write error: {e}")

def signal_handler(sig, frame):
    global running
    print(f"Received signal {sig}, shutting down...")
    running = False

def cleanup():
    global spi, dht_device
    if spi:
        try:
            spi.close()
        except Exception:
            pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    GPIO.cleanup()
    print("Resources released.")

def main():
    global spi, dht_device, running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.IN)
    except Exception as e:
        log_error(f"GPIO setup error: {e}")
        sys.exit(1)

    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
    except Exception as e:
        log_error(f"SPI init error: {e}")
        GPIO.cleanup()
        sys.exit(1)

    try:
        dht_device = adafruit_dht.DHT22(board.D4)
    except Exception as e:
        log_error(f"DHT22 init error: {e}")
        GPIO.cleanup()
        spi.close()
        sys.exit(1)

    print("Calibrating sensors for 60 seconds...")
    calib_start = time.time()
    while time.time() - calib_start < CALIBRATION_DURATION and running:
        temp, hum = read_dht22()
        if temp is not None and hum is not None:
            sensor_readings["temperature"].append(temp)
            sensor_readings["humidity"].append(hum)
        adc0 = read_mcp3008(0)
        if adc0 is not None:
            sensor_readings["adc_channel_0"].append(adc0)
        adc1 = read_mcp3008(1)
        if adc1 is not None:
            sensor_readings["adc_channel_1"].append(adc1)
        time.sleep(1)

    if not running:
        cleanup()
        sys.exit(0)

    print("Calibration complete. Starting logging...")
    while running:
        temp, hum = read_dht22()
        if temp is not None and hum is not None:
            temp_avg = moving_average(sensor_readings["temperature"], MOVING_AVERAGE_WINDOW)
            hum_avg = moving_average(sensor_readings["humidity"], MOVING_AVERAGE_WINDOW)
            sensor_readings["temperature"].append(temp)
            sensor_readings["humidity"].append(hum)
            if temp_avg is not None and hum_avg is not None:
                if -20 <= temp_avg <= 50 and 0 <= hum_avg <= 100:
                    log_data(temp_avg, hum_avg, None, None)
                else:
                    log_error(f"Invalid sensor data: temp={temp_avg}, hum={hum_avg}")
            else:
                log_error("Invalid sensor data: no valid readings available")
        adc0 = read_mcp3008(0)
        if adc0 is not None:
            adc0_avg = moving_average(sensor_readings["adc_channel_0"], MOVING_AVERAGE_WINDOW)
            sensor_readings["adc_channel_0"].append(adc0)
            if adc0_avg is not None:
                log_data(None, None, adc0_avg, None)
            else:
                log_error("Invalid ADC0 data")
        adc1 = read_mcp3008(1)
        if adc1 is not None:
            adc1_avg = moving_average(sensor_readings["adc_channel_1"], MOVING_AVERAGE_WINDOW)
            sensor_readings["adc_channel_1"].append(adc1)
            if adc1_avg is not None:
                log_data(None, None, None, adc1_avg)
            else:
                log_error("Invalid ADC1 data")
        time.sleep(LOG_INTERVAL)

    cleanup()

if __name__ == "__main__":
    main()

