SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000
ADC_CHANNEL = 0
READINGS = 5
DELAY_SECONDS = 2


def read_mcp3008(spi, channel):
    """Read a single-ended channel from the MCP3008 and return a 0-100 percentage."""
    if not 0 <= channel <= 7:
        raise ValueError(f"Invalid MCP3008 channel {channel}; must be 0-7.")
    adc = spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
    data = ((adc[1] & 0x03) << 8) | adc[2]
    return round((data / 1023.0) * 100, 2)


def main():
    spi = None
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED_HZ
        print(f"SPI connection established on bus {SPI_BUS}, CE{SPI_DEVICE} at {SPI_SPEED_HZ} Hz.")

        for i in range(READINGS):
            try:
                moisture = read_mcp3008(spi, ADC_CHANNEL)
                print(f"Soil moisture level: {moisture}%")
            except Exception as e:
                print(f"Error reading MCP3008 channel {ADC_CHANNEL}: {e}", file=sys.stderr)
                sys.exit(1)
            if i < READINGS - 1:
                time.sleep(DELAY_SECONDS)

        print("Soil moisture reading sequence completed.")

