import spidev
import RPi.GPIO as GPIO
import time
import logging
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SmartGardenController:
    """Controls a retail green-wall display irrigation system via MCP3008 ADC and relay."""

    def __init__(self, moisture_channel=0, pump_pin=18):
        self.moisture_channel = moisture_channel
        self.pump_pin = pump_pin
        self.spi = None
        self._setup_gpio()
        self._setup_spi()

    def _setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.info("GPIO setup complete on pin %d", self.pump_pin)
        except Exception as e:
            logging.error("GPIO setup failed: %s", e)
            raise

    def _setup_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)  # bus 0, CE0
            self.spi.max_speed_hz = 1350000
            self.spi.mode = 0
            logging.info("SPI setup complete (bus 0, CE0, 1.35 MHz)")
        except Exception as e:
            logging.error("SPI setup failed: %s", e)
            self.close()
            raise

    def read_moisture(self):
        """Read soil moisture from MCP3008 channel 0 (single-ended). Returns 10-bit value (0-1023)."""
        if self.spi is None:
            raise RuntimeError("SPI not initialized")
        try:
            # MCP3008 command: start bit (1), single-ended mode (1), channel select (3 bits)
            # For channel 0: command byte = 0b00011000 = 0x18
            # Then send 0 bytes to clock out 10 bits
            command = [1, (8 + self.moisture_channel) << 4, 0]
            response = self.spi.xfer2(command)
            # Response: byte1 has 2 LSBs of data, byte2 has 8 bits
            raw_value = ((response[1] & 0x03) << 8) | response[2]
            return raw_value
        except Exception as e:
            logging.error("SPI read error on channel %d: %s", self.moisture_channel, e)
            raise

    def run_pump(self, seconds):
        """Activate the watering pump relay for a given duration."""
        if self.spi is None:
            raise RuntimeError("SPI not initialized")
        try:
            GPIO.output(self.pump_pin, GPIO.HIGH)
            time.sleep(seconds)
            GPIO.output(self.pump_pin, GPIO.LOW)
            logging.info("Pump on for %d seconds", seconds)
        except Exception as e:
            logging.error("Pump control error: %s", e)
            raise

    def irrigation_cycle(self):
        """Run one irrigation cycle: read moisture, log, water if dry."""
        try:
            moisture_value = self.read_moisture()
            logging.info("Moisture reading: %d", moisture_value)
            if moisture_value > 450:
                logging.info("Soil too dry, watering for 2 seconds")
                self.run_pump(2)
                return True
            else:
                logging.info("Moisture adequate, no watering")
                return False
        except Exception as e:
            logging.error("Irrigation cycle failed: %s", e)
            raise

    def close(self):
        """Release SPI and GPIO resources."""
        if self.spi is not None:
            try:
                self.spi.close()
                logging.info("SPI closed")
            except Exception as e:
                logging.error("SPI close error: %s", e)
            finally:
                self.spi = None
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up")
        except Exception as e:
            logging.error("GPIO cleanup error: %s", e)

def schedule_cycles(controller, cycle_count, interval_seconds):
    """Run a fixed number of irrigation cycles with a fixed interval."""
    for cycle_index in range(cycle_count):
        logging.info("Starting irrigation cycle %d/%d", cycle_index + 1, cycle_count)
        controller.irrigation_cycle()
        if cycle_index < cycle_count - 1:
            time.sleep(interval_seconds)

if __name__ == "__main__":
    controller = None
    try:
        controller = SmartGardenController(moisture_channel=0, pump_pin=18)
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as e:
        logging.error("Fatal error: %s", e)
        sys.exit(1)
    finally:
        if controller is not None:
            controller.close()
        logging.info("Cleanup complete")

