#!/usr/bin/env python3
"""
Greenhouse Controller for Raspberry Pi
Reads DHT22 sensor, controls pumps, fans, and lights via relays,
and monitors a soil moisture sensor via MCP3008 ADC.
"""

import time
import datetime
import logging
import os
import signal
import sys
import spidev
import board
import adafruit_dht
from gpiozero import OutputDevice

# Configuration
DHT_PIN = 4
PUMP_PIN = 17
FAN_PIN = 27
LIGHT_PIN = 22
LED_PIN = 25
SPI_BUS = 0
SPI_DEVICE = 0
SPI_CHANNEL = 0
SPI_SPEED_HZ = 1000000
SENSOR_INTERVAL = 300
WATCHDOG_TIMEOUT = 600
DHT_RETRIES = 3
DHT_RETRY_DELAY = 2

# Logging setup
logging.basicConfig(
    filename='greenhouse.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global state
running = True
last_activity = time.time()
spi = None
dht_device = None
pump = None
fan = None
light = None
led = None

def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False

def setup_gpio():
    global pump, fan, light, led
    try:
        pump = OutputDevice(PUMP_PIN, initial_value=False)
        fan = OutputDevice(FAN_PIN, initial_value=False)
        light = OutputDevice(LIGHT_PIN, initial_value=False)
        led = OutputDevice(LED_PIN, initial_value=False)
        logging.info("GPIO setup complete.")
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        sys.exit(1)

def setup_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED_HZ
        spi.mode = 0
        logging.info("SPI setup complete.")
    except Exception as e:
        logging.error(f"SPI setup failed: {e}")
        sys.exit(1)

def setup_dht22():
    global dht_device
    try:
        dht_device = adafruit_dht.DHT22(board.D4, use_pulseio=False)
        logging.info("DHT22 setup complete.")
    except Exception as e:
        logging.error(f"DHT22 setup failed: {e}")
        dht_device = None

def read_dht22():
    if dht_device is None:
        return None, None
    for attempt in range(DHT_RETRIES):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            logging.warning(f"DHT22 returned None (attempt {attempt+1})")
        except RuntimeError as e:
            logging.warning(f"DHT22 read error (attempt {attempt+1}): {e}")
        except Exception as e:
            logging.error(f"DHT22 unexpected error (attempt {attempt+1}): {e}")
        time.sleep(DHT_RETRY_DELAY)
    logging.error("DHT22 failed after all retries.")
    return None, None

def read_mcp3008(channel):
    if spi is None:
        return None
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        logging.error(f"MCP3008 read error on channel {channel}: {e}")
        return None

def control_pump(command):
    if command == "on":
        pump.on()
        logging.info("Pump turned ON")
    elif command == "off":
        pump.off()
        logging.info("Pump turned OFF")
    else:
        logging.warning(f"Invalid pump command: {command}")

def control_fan(command):
    if command == "on":
        fan.on()
        logging.info("Fan turned ON")
    elif command == "off":
        fan.off()
        logging.info("Fan turned OFF")
    else:
        logging.warning(f"Invalid fan command: {command}")

def control_light(command):
    if command == "on":
        light.on()
        logging.info("Light turned ON")
    elif command == "off":
        light.off()
        logging.info("Light turned OFF")
    else:
        logging.warning(f"Invalid light command: {command}")

def set_led_status(status):
    if status == "online":
        led.on()
        logging.info("LED set to online")
    elif status == "offline":
        led.off()
        logging.info("LED set to offline")
    elif status == "error":
        for _ in range(5):
            led.on()
            time.sleep(0.2)
            led.off()
            time.sleep(0.2)
        logging.warning("LED set to error")
    elif status == "synchronizing":
        for _ in range(5):
            led.on()
            time.sleep(0.2)
            led.off()
            time.sleep(0.2)
        logging.info("LED set to synchronizing")
    else:
        logging.warning(f"Invalid LED status: {status}")

def cleanup():
    global spi, dht_device, pump, fan, light, led
    logging.info("Cleaning up resources...")
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    if pump:
        pump.close()
    if fan:
        fan.close()
    if light:
        light.close()
    if led:
        led.close()
    if spi:
        spi.close()
    logging.info("Cleanup complete.")

def main():
    global running, last_activity
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    setup_gpio()
    setup_spi()
    setup_dht22()
    logging.info("Greenhouse controller started.")
    while running:
        now = time.time()
        if now - last_activity > WATCHDOG_TIMEOUT:
            logging.critical("Watchdog timeout! Restarting...")
            cleanup()
            os.execv(sys.executable, [sys.executable] + sys.argv)
        try:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                soil_moisture = read_mcp3008(SPI_CHANNEL)
                if soil_moisture is not None:
                    logging.info(f"Temp: {temperature:.1f}C, Humidity: {humidity:.1f}%, Soil: {soil_moisture}")
                    if temperature > 30:
                        control_fan("on")
                    elif temperature < 20:
                        control_fan("off")
                    if humidity < 60:
                        control_light("on")
                    elif humidity > 80:
                        control_light("off")
                    if soil_moisture < 320:
                        control_pump("on")
                    elif soil_moisture > 700:
                        control_pump("off")
                    last_activity = now
                else:
                    logging.error("MCP3008 read failed, skipping control.")
            else:
                logging.warning("DHT22 read failed, skipping control.")
        except Exception as e:
            logging.error(f"Unexpected error in main loop: {e}")
        time.sleep(SENSOR_INTERVAL)
    cleanup()

if __name__ == "__main__":
    main()

