    if dht_device is None:
        return None, None
    for attempt in range(DHT_RETRIES):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            logging.warning(f"DHT22 returned None (attempt {attempt+1})")
        except RuntimeError as e:
            logging.warning(f"DHT22 read error (attempt {attempt+1}): {e}")
        except Exception as e:
            logging.error(f"DHT22 unexpected error (attempt {attempt+1}): {e}")
        time.sleep(DHT_RETRY_DELAY)
    logging.error("DHT22 failed after all retries.")
    return None, None

def read_mcp3008(channel):
    if spi is None:
        return None
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        logging.error(f"MCP3008 read error on channel {channel}: {e}")
        return None

