    elif command == "off":
        light.off()
        logging.info("Light turned OFF")
    else:
        logging.warning(f"Invalid light command: {command}")

def set_led_status(status):
    if status == "online":
        led.on()
        logging.info("LED set to online")
    elif status == "offline":
        led.off()
        logging.info("LED set to offline")
    elif status == "error":
        for _ in range(5):
            led.on()
            time.sleep(0.2)
            led.off()
            time.sleep(0.2)
        logging.warning("LED set to error")
    elif status == "synchronizing":
        for _ in range(5):
            led.on()
            time.sleep(0.2)
            led.off()
            time.sleep(0.2)
