    global spi, dht_device, pump, fan, light, led
    logging.info("Cleaning up resources...")
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    if pump:
        pump.close()
    if fan:
        fan.close()
    if light:
        light.close()
    if led:
        led.close()
    if spi:
        spi.close()
    logging.info("Cleanup complete.")

def main():
    global running, last_activity
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    setup_gpio()
    setup_spi()
    setup_dht22()
    logging.info("Greenhouse controller started.")
    while running:
        now = time.time()
        if now - last_activity > WATCHDOG_TIMEOUT:
            logging.critical("Watchdog timeout! Restarting...")
            cleanup()
            os.execv(sys.executable, [sys.executable] + sys.argv)
        try:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
