                    if temperature > 30:
                        control_fan("on")
                    elif temperature < 20:
                        control_fan("off")
                    if humidity < 60:
                        control_light("on")
                    elif humidity > 80:
                        control_light("off")
                    if soil_moisture < 320:
                        control_pump("on")
                    elif soil_moisture > 700:
                        control_pump("off")
                    last_activity = now
                else:
                    logging.error("MCP3008 read failed, skipping control.")
            else:
                logging.warning("DHT22 read failed, skipping control.")
        except Exception as e:
            logging.error(f"Unexpected error in main loop: {e}")
        time.sleep(SENSOR_INTERVAL)
    cleanup()

if __name__ == "__main__":
    main()

