import argparse
import logging
import queue
import signal
import sys
import threading
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

try:
    import spidev
except ImportError:
    spidev = None


class SoundSensor:
    """Reads sound levels from digital or analog sensors and logs events."""

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins if gpio_pins is not None else []
        self.channels = channels if channels is not None else []
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.running = False
        self.debounce_timer = None
        self.spi_lock = threading.Lock()

        if self.sensor_type == 'digital':
            if not self.gpio_pins:
                raise ValueError('gpio_pins must be provided for digital sensors')
            if len(self.gpio_pins) != 1:
                raise ValueError('Only one GPIO pin is supported for digital sensors')
            self.pin = self.gpio_pins[0]
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        elif self.sensor_type == 'analog':
            if not self.channels:
                raise ValueError('channels must be provided for analog sensors')
            if spidev is None:
                raise RuntimeError('spidev library not available')
            self.spi = spidev.SpiDev()
            try:
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                raise RuntimeError(f'Failed to initialize SPI: {e}')
        else:
            raise ValueError('Invalid sensor_type. Must be "digital" or "analog".')

        logging.info(f'SoundSensor {self.sensor_id} initialized: type={self.sensor_type}, threshold={self.threshold}, sample_rate={self.sample_rate}')

    def read_sensor(self):
        """Reads the sound sensor and returns the value."""
        if self.sensor_type == 'digital':
            try:
                value = GPIO.input(self.pin)
            except Exception as e:
                logging.error(f'Sensor {self.sensor_id} GPIO read error: {e}')
                return None
        elif self.sensor_type == 'analog':
            with self.spi_lock:
                try:
                    adc = self.spi.xfer2([1, (8 + self.channels[0]) << 4, 0])
                    data = ((adc[1] & 3) << 8) + adc[2]
                except Exception as e:
                    logging.error(f'Sensor {self.sensor_id} SPI read error: {e}')
                    return None
        return data

    def sound_event_detected(self):
        """Detects a sound event and logs it."""
        if self.sensor_type == 'digital':
            value = GPIO.input(self.pin)
        elif self.sensor_type == 'analog':
            with self.spi_lock:
                adc = self.spi.xfer2([1, (8 + self.channels[0]) << 4, 0])
                value = ((adc[1] & 3) << 8) + adc[2]

        if value is None:
            return

        if self.sensor_type == 'digital' and value == 1:
            self.log_event('Sound Detected')
        elif self.sensor_type == 'analog' and value >= self.threshold:
            self.log_event('Sound Detected')

    def log_event(self, message):
        """Logs the sound event to the log queue."""
        if self.log_queue:
            self.log_queue.put((self.sensor_id, message))

    def debounce(self):
        """Debounces the sound event."""
        if self.debounce_timer:
            self.debounce_timer.cancel()
        self.debounce_timer = threading.Timer(0.1, self._debounce_callback)
        self.debounce_timer.daemon = True
        self.debounce_timer.start()

    def _debounce_callback(self):
        self.debounce_timer = None
        logging.info(f'Sensor {self.sensor_id} debounced')

    def run(self):
        """Runs the sound sensor and detects sound events."""
        self.running = True
        while self.running:
            self.sound_event_detected()
            if self.debounce_timer:
                self.debounce_timer.cancel()
            self.debounce()
            time.sleep(1 / self.sample_rate)

    def stop(self):
        """Stops the sound sensor."""
        self.running = False
        if self.debounce_timer:
            self.debounce_timer.cancel()
            self.debounce_timer = None
        if self.sensor_type == 'analog' and self.spi:
            try:
                self.spi.close()
            except Exception:
                pass
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass
        logging.info(f'Sensor {self.sensor_id} stopped')


def main():
    parser = argparse.ArgumentParser(description='Sound Sensor Monitoring System')
    parser.add_argument('--sensor_type', choices=['digital', 'analog'], required=True, help='Type of sound sensor')
    parser.add_argument('--threshold', type=int, required=True, help='Threshold value for analog sensor')
    parser.add_argument('--sample_rate', type=int, required=True, help='Sampling rate in Hz')
    parser.add_argument('--log_file', type=str, required=True, help='Path to the log file')
    parser.add_argument('--gpio_pins', type=int, nargs='+', help='GPIO pins for digital sensors')
    parser.add_argument('--channels', type=int, nargs='+', help='MCP3008 channels for analog sensors')
    parser.add_argument('--spi_speed', type=int, default=1000000, help='SPI speed in Hz')
    parser.add_argument('--sensor_ids', type=int, nargs='+', help='Unique IDs for each sensor')
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

    log_queue = queue.Queue()
    sensors = []
    sensor_ids = args.sensor_ids if args.sensor_ids else [0]

    for i, sensor_id in enumerate(sensor_ids):
        try:
            if args.sensor_type == 'digital':
                sensor = SoundSensor(sensor_id, args.sensor_type, 0, args.sample_rate, gpio_pins=args.gpio_pins, log_queue=log_queue)
            else:
                sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, channels=args.channels, spi_speed=args.spi_speed, log_queue=log_queue)
            sensors.append(sensor)
        except Exception as e:
            logging.error(f'Failed to initialize sensor {sensor_id}: {e}')
            sys.exit(1)

    def signal_handler(sig, frame):
        logging.info('Shutdown signal received')
        for sensor in sensors:
            sensor.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run, daemon=True)
        thread.start()
        threads.append(thread)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        signal_handler(signal.SIGINT, None)

    for sensor in sensors:
        sensor.stop()
    for thread in threads:
        thread.join(timeout=5)


if __name__ == '__main__':
    main()

