import time
import signal
import sys
import board
import busio
import adafruit_max30102

LOG_FILE = "heart_rate_log.txt"
SAMPLE_INTERVAL = 1.0
FIFO_READ_TIMEOUT = 0.5
FIFO_SAMPLE_SIZE = 1024

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _format_value(value):
    if value is None:
        return "N/A"
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return f"{value:.2f}"
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        return value
    try:
        return int(value)
    except (TypeError, ValueError):
        return str(value)

def _log_reading(timestamp, heart_rate, spo2):
    try:
        with open(LOG_FILE, "a") as f:
            f.write(f"{timestamp}, {heart_rate}, {spo2}\n")
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def _read_fifo(sensor):
    try:
        fifo_data = sensor.fifo_data
        if fifo_data is None:
            return None
        return list(fifo_data)
    except OSError as e:
        print(f"I2C bus error reading FIFO: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading FIFO: {e}", file=sys.stderr)
        return None

def _estimate_heart_rate(fifo_data):
    if not fifo_data:
        return None
    ir_samples = [s[0] for s in fifo_data]
    red_samples = [s[1] for s in fifo_data]
    if len(ir_samples) < 10:
        return None
    peaks = 0
    for i in range(1, len(ir_samples) - 1):
        if ir_samples[i] > ir_samples[i - 1] and ir_samples[i] > ir_samples[i + 1]:
            peaks += 1
    if peaks == 0:
        return None
    bpm = (peaks / SAMPLE_INTERVAL) * 60.0
    return bpm

def _estimate_spo2(fifo_data):
    if not fifo_data:
        return None
    ir_samples = [s[0] for s in fifo_data]
    if len(ir_samples) < 10:
        return None
    avg_ir = sum(ir_samples) / len(ir_samples)
    if avg_ir < 100:
        return None
    spo2 = 100.0 - ((avg_ir - 100.0) / 100.0 * 99.0)
    return max(0.0, min(100.0, spo2))

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    sensor = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c, address=0x57)
        print("MAX30102 initialized at address 0x57.")
    except ValueError as e:
        print(f"Error initializing I2C bus or MAX30102: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"I2C bus error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing sensor: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        while _running:
            fifo_data = _read_fifo(sensor)
            if fifo_data is None:
                time.sleep(SAMPLE_INTERVAL)
                continue
            heart_rate = _estimate_heart_rate(fifo_data)
            spo2 = _estimate_spo2(fifo_data)
            timestamp = time.strftime("%Y-%m-%dT%H:%M:%S")
            print(f"Timestamp: {timestamp}, Heart Rate: {_format_value(heart_rate)}, SpO2: {_format_value(spo2)}")
            _log_reading(timestamp, _format_value(heart_rate), _format_value(spo2))
            time.sleep(SAMPLE_INTERVAL)
    finally:
        if sensor is not None:
            try:
                sensor.shutdown()
            except Exception:
                pass
        print("\nProgram terminated.")

if __name__ == "__main__":
    main()

