    if peaks == 0:
        return None
    bpm = (peaks / SAMPLE_INTERVAL) * 60.0
    return bpm

def _estimate_spo2(fifo_data):
    if not fifo_data:
        return None
    ir_samples = [s[0] for s in fifo_data]
    if len(ir_samples) < 10:
        return None
    avg_ir = sum(ir_samples) / len(ir_samples)
    if avg_ir < 100:
        return None
    spo2 = 100.0 - ((avg_ir - 100.0) / 100.0 * 99.0)
    return max(0.0, min(100.0, spo2))

