            elif humidity is not None:
                if validate_data(None, None, humidity):
                    store_data(timestamp, sensor_type, sensor_id, None, None, humidity)

        for _ in range(sampling_interval):
            if not running:
                break
            time.sleep(1)

    logging.info("Program terminated gracefully.")

if __name__ == "__main__":
