import signal
import sys
import time
import random
import board
import busio
import adafruit_amg88xx
from gpiozero import Buzzer

# Configuration
BUZZER_PIN = 17
THRESHOLD_TEMP = 30.0
POLL_INTERVAL = 0.1
BUZZER_DURATION = 1.0

# Global resources for cleanup
buzzer = None
i2c = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    running = False


def init_sensor():
    """Initialize the AMG8833 thermal camera sensor at I2C address 0x69."""
    global i2c
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_amg88xx.AMG88XX(i2c, addr=0x69)
        # Brief warm-up to allow sensor to stabilize
        time.sleep(0.1)
        return sensor
    except (ValueError, OSError, RuntimeError) as e:
        print(f"Warning: AMG8833 not detected at 0x69 ({e}). "
              "Simulating thermal data.", file=sys.stderr)
        return None


def read_thermal_data(sensor):
    """Read 8x8 thermal data from the AMG8833, or simulate if unavailable."""
    if sensor is not None:
        try:
            return sensor.pixels
        except (OSError, RuntimeError) as e:
            print(f"Warning: I2C read error ({e}). "
                  "Simulating thermal data.", file=sys.stderr)
    # Simulate: random values between 20 and 45°C
    return [[random.uniform(20.0, 45.0) for _ in range(8)] for _ in range(8)]


def detect_human(thermal_data):
    """Return True if any pixel exceeds the temperature threshold."""
    for row in thermal_data:
        for temp in row:
            if temp > THRESHOLD_TEMP:
                return True
    return False


def trigger_alert(buzzer_obj):
    """Sound the buzzer for BUZZER_DURATION seconds."""
    if buzzer_obj is not None:
        try:
            buzzer_obj.on()
            time.sleep(BUZZER_DURATION)
            buzzer_obj.off()
        except Exception as e:
            print(f"Warning: buzzer control error ({e}).", file=sys.stderr)


def cleanup():
    """Release all resources."""
    global buzzer, i2c
    if buzzer is not None:
        try:
            buzzer.close()
        except Exception:
            pass
        buzzer = None
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
        i2c = None


def main():
    global buzzer

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Fatal: could not initialize buzzer on GPIO{BUZZER_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    # Initialize sensor
    sensor = init_sensor()

    try:
        while running:
            thermal_data = read_thermal_data(sensor)
            human_detected = detect_human(thermal_data)

            if human_detected:
                print("WARNING: Human detected! Activating alert.")
                trigger_alert(buzzer)
            else:
                print("Status: No human detected.")

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

