import multiprocessing
import os
import signal
import time
import atexit
import threading
import traceback
from typing import Optional

from setproctitle import setproctitle

import config
import logsupport as L
from controlevents import CEvent, PostEvent, ConsoleEvent
from utils.utilfuncs import disptime


# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
KeepAlive = multiprocessing.Event()
KeepAlive.clear()
_watchdog_alive = threading.Event()
_watchdog_alive.set()


def _signal_handler_unexpected(signum: int, frame) -> None:
    """Unexpected signal handler: write tombstone, SIGUSR1/SIGKILL console, then exit 93."""
    try:
        with open("/home/pi/.tombstoneW", "a") as f:
            f.write(f"{disptime()} Unexpected signal {signum} from {os.getpid()}\n")
            f.flush()
            traceback.print_stack(file=f)
    except OSError as exc:
        print(f"Watchdog: could not write tombstone: {exc}", file=sys.stderr)
    try:
        console_pid = getattr(config.sysStore, "Console_pid", None)
    except Exception as exc:
        print(f"Watchdog: could not read Console_pid: {exc}", file=sys.stderr)
        console_pid = None
    if console_pid is not None and console_pid > 0:
        try:
            os.kill(console_pid, signal.SIGUSR1)
        except OSError:
            pass
        try:
            os.kill(console_pid, 0)
        except OSError:
            pass
        time.sleep(3)
        try:
            os.kill(console_pid, signal.SIGKILL)
        except OSError:
            pass
    os._exit(93)


def _signal_handler_sigterm(signum: int, frame) -> None:
    """SIGTERM handler: log from systemd, wait 30 s, then exit cleanly."""
    L.Logs.Log("Watchdog: SIGTERM received (systemd). Waiting for console to shut down.")
    try:
        console_pid = getattr(config.sysStore, "Console_pid", None)
    except Exception as exc:
        console_pid = None
    if console_pid is not None and console_pid > 0:
        time.sleep(30)
    os._exit(0)


def _signal_handler_sigint(signum: int, frame) -> None:
    """SIGINT handler: exit cleanly with code 94."""
    L.Logs.Log("Watchdog: SIGINT received. Exiting.")
    os._exit(94)


def _signal_handler_sigusr1(signum: int, frame) -> None:
    """SIGUSR1 handler: exit cleanly with code 94."""
    L.Logs.Log("Watchdog: SIGUSR1 received. Exiting.")
    os._exit(94)


def _signal_handler_sighup(signum: int, frame) -> None:
    """SIGHUP handler: ignored and only logged."""
    L.Logs.Log("Watchdog: SIGHUP received. Ignored.")


def _signal_handler_sigabrt(signum: int, frame) -> None:
    """SIGABRT handler: write tombstone, then exit 93."""
    try:
        with open("/home/pi/.tombstoneW", "a") as f:
            f.write(f"{disptime()} Watchdog abort from {os.getpid()}\n")
            f.flush()
            traceback.print_stack(file=f)
    except OSError as exc:
        print(f"Watchdog: could not write tombstone: {exc}", file=sys.stderr)
    os._exit(93)


def _injector() -> None:
    """Periodically post keep-alive events to the watchdog."""
    while True:
        try:
            now = time.time()
            L.Logs.Log(f"Inject: {now}")
            PostEvent(ConsoleEvent(CEvent.FailSafePing, inject=now))
            time.sleep(30)
        except Exception as exc:
            L.Logs.Log(f"Injector error: {exc}")
            time.sleep(1)


def _check_main_thread() -> None:
    """Background thread: kill watchdog if MainThread dies."""
    while True:
