import atexit
import signal
import threading
import time
import logging
from typing import Tuple, Optional

from flask import Flask, render_template, Response, request

from config import Config
from mail_config import MailConfig
from object_detector import ObjectDetector
from picam2_wrapper import Camera as Picam2Wrapper

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

app = Flask(__name__)
config = Config()
mail_config = MailConfig()
object_detector: Optional[ObjectDetector] = None
picam2: Optional[Picam2Wrapper] = None
shutdown_event = threading.Event()


def initialize_components() -> Tuple[Optional[ObjectDetector], Optional[Picam2Wrapper]]:
    """Initialize object detector and camera; return (detector, camera) or (None, None)."""
    try:
        object_detector = ObjectDetector(config.object_detector_type)
        logger.info("Object detector initialized.")
    except Exception as e:
        logger.error(f"Failed to initialize object detector: {e}")
        return None, None

    try:
        picam2 = Picam2Wrapper()
        # Configure for 640x480 JPEG streaming; vertical flip via transform
        picam2.configure(
            picam2.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                transform=picam2.Transform(vflip=True)
            )
        )
        picam2.start()
        logger.info("Camera initialized (640x480, vertical flip).")
    except Exception as e:
        logger.error(f"Failed to initialize camera: {e}")
        return object_detector, None

    return object_detector, picam2


def check_for_objects() -> None:
    """Background thread: periodically run object detection and send email notifications."""
    last_email_time = 0.0
    while not shutdown_event.is_set():
        try:
            if config.classifier_name == 'motion_detector':
                frame, detected = picam2.get_object_with_basic_motion_detection()
            else:
                frame, detected = picam2.get_object(config.classifier)
            if detected:
                if (time.time() - last_email_time) >= config.email_send_interval:
                    try:
                        mail_config.send_email(frame, config)
                        last_email_time = time.time()
                        logger.info("Email notification sent.")
                    except Exception as e:
                        logger.error(f"Failed to send email: {e}")
        except Exception as e:
            logger.error(f"Error in check_for_objects: {e}")
        shutdown_event.wait(1.0)


def cleanup() -> None:
    """Release camera resources on exit."""
    global picam2
    if picam2 is not None:
        try:
            picam2.stop()
            logger.info("Camera stopped.")
        except Exception as e:
            logger.error(f"Error stopping camera: {e}")
        picam2 = None


def signal_handler(signum, frame) -> None:
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    logger.info(f"Signal {signum} received, shutting down...")
    shutdown_event.set()


@app.route('/', methods=['GET', 'POST'])
def index():
    """Render the configuration form."""
    if request.method == 'POST':
        config.classifier_name = request.form.get('classifier_name', 'motion_detector')
        config.live_preview = 'live_preview' in request.form
        config.send_email_notifications = 'send_email_notifications' in request.form
        config.recipient_address = request.form.get('recipient_address', '')
        config.email_send_interval = int(request.form.get('email_send_interval', 60))
        logger.info(f"Configuration updated: {config}")
    return render_template('index.html', classifiers=object_detector.classifier_names, config=config)


def generate_frames() -> Response:
    """Generate JPEG frames for the video feed."""
    if not config.live_preview:
        return Response(b'', mimetype='multipart/x-mixed-replace; boundary=frame')

    while not shutdown_event.is_set():
        try:
            if config.classifier_name == 'motion_detector':
                frame, _ = picam2.get_object_with_basic_motion_detection()
            else:
                frame, _ = picam2.get_object(config.classifier)
            if frame is None:
                continue
            yield (b'--frame\r\n'
                   b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n\r\n')
        except Exception as e:
            logger.error(f"Error generating frames: {e}")
            shutdown_event.wait(1.0)
    return Response(b'', mimetype='multipart/x-mixed-replace; boundary=frame')


@app.route('/video_feed')
def video_feed():
    """Endpoint for the video feed."""
    return Response(generate_frames(), mimetype='multipart/x-mixed-replace; boundary=frame')


if __name__ == '__main__':
    object_detector, picam2 = initialize_components()
    if object_detector is None or picam2 is None:
        logger.error("Cannot start Flask: camera or object detector initialization failed.")
        cleanup()
        exit(1)

    atexit.register(cleanup)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        thread = threading.Thread(target=check_for_objects, daemon=True)
        thread.start()
        logger.info("Starting Flask server on 0.0.0.0:5000")
        app.run(host='0.0.0.0', port=5000, debug=False, use_reloader=False)
    except Exception as e:
        logger.error(f"Flask server error: {e}")
    finally:
        shutdown_event.set()
        if thread.is_alive():
            thread.join(timeout=5.0)
        cleanup()
        logger.info("Server stopped.")

