import time
import json
import logging
import signal
import sys
from gpiozero import OutputDevice, InputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning("config.json not found; using default configuration.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in config.json: {e}; using default configuration.")
        return DEFAULT_CONFIG.copy()


def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    try:
        trigger = OutputDevice(trigger_pin)
        echo = InputDevice(echo_pin)
    except GPIODeviceError as e:
        logging.error(f"Failed to initialize GPIO pins {trigger_pin}/{echo_pin}: {e}")
        return None
    except Exception as e:
        logging.error(f"Unexpected GPIO init error: {e}")
        return None

    try:
        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        timeout = time.time() + 0.05
        while echo.value == 0:
            if time.time() > timeout:
                logging.warning("Timeout waiting for echo rising edge.")
                return None
            time.sleep(0.000001)

        pulse_start = time.time()
        timeout = time.time() + 0.05
        while echo.value == 1:
            if time.time() > timeout:
                logging.warning("Timeout waiting for echo falling edge.")
                return None
            time.sleep(0.000001)
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * 34300) / 2
        water_level = max_distance - distance + offset

        if water_level < 0 or water_level > max_distance:
            logging.warning(f"Distance out of range: {water_level:.2f} cm")
            return None

        return water_level

    except GPIODeviceClosed:
        logging.error("GPIO device closed unexpectedly.")
        return None
    except Exception as e:
        logging.error(f"Error measuring distance: {e}")
        return None
    finally:
        try:
            trigger.close()
            echo.close()
        except Exception:
            pass


def check_alerts(sensor_readings, alert_threshold_low, alert_threshold_high, alert_repeat_delay):
    if not sensor_readings:
        return
    avg = sum(sensor_readings) / len(sensor_readings)
    now = time.time()
    if avg < alert_threshold_low:
        if not _alert_suppressed("low"):
            logging.warning(f"Water level LOW: {avg:.2f} cm")
    elif avg > alert_threshold_high:
        if not _alert_suppressed("high"):
            logging.warning(f"Water level HIGH: {avg:.2f} cm")
    else:
        _suppress_alert("low", now)
        _suppress_alert("high", now)


def _alert_suppressed(alert_type):
    if alert_type == "low":
        return _suppress_alert("low", time.time())
    return _suppress_alert("high", time.time())


def _suppress_alert(alert_type, now):
    if alert_type == "low":
        if "low_suppressed_until" in globals() and now < low_suppressed_until:
            return True
        low_suppressed_until = now + alert_repeat_delay
        return False
    if "high_suppressed_until" in globals() and now < high_suppressed_until:
        return True
    high_suppressed_until = now + alert_repeat_delay
    return False


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config()
    log_file = config.get("log_file", "water_level.log")
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Water level monitoring started.")

    sensors = config.get("sensors", [])
    if not sensors:
        logging.error("No sensors configured; exiting.")
        return

    trigger_pins = [s["trigger_pin"] for s in sensors]
    echo_pins = [s["echo_pin"] for s in sensors]
    offsets = [s["offset"] for s in sensors]
    max_distances = [s["max_distance"] for s in sensors]
    alert_threshold_low = config.get("alert_threshold_low", 10.0)
    alert_threshold_high = config.get("alert_threshold_high", 180.0)
    alert_repeat_delay = config.get("alert_repeat_delay", 60)

    sensor_errors = [0] * len(sensors)
    sensor_excluded = [False] * len(sensors)

    while _running:
        sensor_readings = []
        for i, (trigger, echo, offset, max_dist) in enumerate(zip(
            trigger_pins, echo_pins, offsets, max_distances)):
            if sensor_excluded[i]:
                logging.info(f"Sensor {i+1} excluded; skipping.")
                continue
            for attempt in range(3):
                if sensor_excluded[i]:
                    break
                reading = measure_distance(trigger, echo, offset, max_dist)
                if reading is not None:
                    sensor_readings.append(reading)
                    break
                sensor_errors[i] += 1
                logging.warning(f"Sensor {i+1} attempt {attempt+1} failed.")
            else:
                logging.error(f"Sensor {i+1} failed after 3 attempts; excluding.")
                sensor_excluded[i] = True
                sensor_errors[i] = 0

        if sensor_readings:
            check_alerts(sensor_readings, alert_threshold_low, alert_threshold_high, alert_repeat_delay)
            logging.info(f"Sensor readings: {sensor_readings}")
        else:
            logging.warning("No valid sensor readings this cycle.")

        for i in range(len(sensors)):
            if sensor_excluded[i]:
                logging.info(f"Sensor {i+1} excluded; skipping.")
                continue
            if sensor_errors[i] >= 5:
                logging.warning(f"Sensor {i+1} excluded after 5 consecutive errors.")
                sensor_excluded[i] = True
                sensor_errors[i] = 0

        time.sleep(5)

    logging.info("Water level monitoring stopped.")


if __name__ == "__main__":
    main()

