import RPi.GPIO as GPIO
import time
import speech_recognition as sr
import os
import random
import sys
import signal

# Configuration
LIGHT_PIN = 17
DHT_PIN = 4
CAMERA_RESOLUTION = (640, 480)
WAKE_WORD = "Greenhouse"

# Global state
lights_on = False
camera_available = False
gpio_available = False

# GPIO setup with error handling
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
    gpio_available = True
except Exception as e:
    print(f"GPIO initialization failed: {e}. Running in simulation mode.")
    gpio_available = False

# Camera setup with error handling
try:
    from picamera2 import Picamera2
    picam2 = Picamera2()
    picam2.configure(picam2.create_still_configuration(main={"size": CAMERA_RESOLUTION}))
    picam2.start()
    camera_available = True
except Exception as e:
    print(f"Camera initialization failed: {e}. Running in simulation mode.")
    camera_available = False

# DHT11 sensor setup with error handling
dht_device = None
if gpio_available:
    try:
        import adafruit_dht
        dht_device = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"DHT11 initialization failed: {e}. Running in simulation mode.")
        dht_device = None

# Voice recognition setup
recognizer = sr.Recognizer()

def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    if gpio_available:
        try:
            GPIO.cleanup()
        except Exception:
            pass
    if camera_available:
        try:
            picam2.stop()
        except Exception:
            pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    sys.exit(0)

signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

def turn_lights_on():
    """Turns the lights on."""
    global lights_on
    if gpio_available:
        try:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
        except Exception as e:
            print(f"GPIO output error: {e}")
    lights_on = True
    print("Lights are on")

def turn_lights_off():
    """Turns the lights off."""
    global lights_on
    if gpio_available:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
        except Exception as e:
            print(f"GPIO output error: {e}")
    lights_on = False
    print("Lights are off")

def read_temperature():
    """Reads the temperature from the DHT11 sensor."""
    if dht_device:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                print("Failed to read temperature from DHT11 sensor.")
        except RuntimeError as e:
            print(f"DHT11 read error: {e}")
        except Exception as e:
            print(f"Unexpected DHT11 error: {e}")
    # Fallback to simulated temperature
    return random.uniform(15, 35)

def take_picture():
    """Captures an image using the camera."""
    if camera_available:
        try:
            timestamp = time.strftime("%Y%m%d-%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            picam2.capture_file(filename)
            print(f"Image saved as {filename}")
        except Exception as e:
            print(f"Camera capture error: {e}")
    else:
        print("Camera not available. Taking picture in simulation mode.")

def process_command(command):
    """Processes the recognized voice command."""
    if "turn on the lights" in command:
        turn_lights_on()
    elif "turn off the lights" in command:
        turn_lights_off()
    elif "what is the temperature" in command:
        temperature = read_temperature()
        if temperature is not None:
            print(f"The temperature is {temperature:.1f} degrees Celsius")
        else:
            print("Temperature reading failed.")
    elif "take a picture" in command:
        take_picture()
    else:
        print("Unknown command.")

def main():
    """Main function to run the voice-controlled greenhouse system."""
    try:
        with sr.Microphone() as source:
            print("Say 'Greenhouse' to start...")
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            audio = recognizer.listen(source, timeout=5)
            command = recognizer.recognize_google(audio).lower()
            print(f"You said: {command}")
            process_command(command)
    except sr.WaitTimeoutError:
        print("No speech detected within the timeout period.")
    except sr.UnknownValueError:
        print("Could not understand audio.")
    except sr.RequestError as e:
        print(f"Could not request results from Google Web Speech API; {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

