signal.signal(signal.SIGTERM, cleanup)

def turn_lights_on():
    """Turns the lights on."""
    global lights_on
    if gpio_available:
        try:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
        except Exception as e:
            print(f"GPIO output error: {e}")
    lights_on = True
    print("Lights are on")

def turn_lights_off():
    """Turns the lights off."""
    global lights_on
    if gpio_available:
