import io
import os
import time
import signal
import logging
import configparser
import threading
import datetime
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput
import RPi.GPIO as GPIO
import smbus

# Constants
CONFIG_FILE = 'config.ini'
DEFAULT_CONFIG = {
    'camera': {
        'resolution_width': '640',
        'resolution_height': '480',
        'framerate': '24',
        'lores_width': '352',
        'lores_height': '288',
        'quality': '100',
        'motion_threshold': '10',
        'motion_sensitivity': '0.05',
        'debounce_time': '1',
        'recording_duration': '10',
        'disk_space_limit': '10'
    },
    'logging': {
        'level': 'INFO',
        'log_file': 'security_camera.log'
    },
    'gpio': {
        'motion_sensor_pin': '17'
    },
    'i2c': {
        'light_sensor_address': '0x23'
    }
}

# Global state
camera = None
encoder = None
output = None
running = True
last_frame = None
motion_detected = False
motion_start_time = None
debounce_start_time = None
light_sensor_address = 0x23
bus = None
gpio_pin = 17
config = configparser.ConfigParser()
light_sensor_data = 0.0
light_sensor_initialized = False
light_sensor_lock = threading.Lock()

# Logging setup
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler(config.get('logging', 'log_file', fallback='security_camera.log')),
        logging.StreamHandler()
    ]
)

def load_config():
    """Load configuration from config.ini, creating defaults if missing."""
    config.read(CONFIG_FILE)
    for section, defaults in DEFAULT_CONFIG.items():
        if section not in config:
            config[section] = {}
        for key, value in defaults.items():
            if key not in config[section]:
                config[section][key] = value
    logging.info("Configuration loaded from %s", CONFIG_FILE)

def initialize_camera():
    """Initialize the Raspberry Pi camera using picamera2."""
    global camera, encoder, output
    try:
        camera = Picamera2()
        camera_config = camera.create_video_configuration(
            main={"size": (int(config['camera']['resolution_width']), int(config['camera']['resolution_height'])),
                  "format": "RGB888"},
            lores={"size": (int(config['camera']['lores_width']), int(config['camera']['lores_height'])),
                   "format": "YUV420"},
            encode="lores"
        )
        camera.configure(camera_config)
        camera.start()
        time.sleep(2)  # Allow camera to warm up
        encoder = H264Encoder(bitrate=10000000)
        output = FileOutput("/home/pi/security_footage/camera1.h264")
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.error("Failed to initialize camera: %s", e)
        raise

def capture_frame():
    """Capture a single frame from the camera and return it as a numpy array."""
    try:
        frame = camera.capture_array("lores")
        return frame
    except Exception as e:
        logging.error("Failed to capture frame: %s", e)
        return None

def detect_motion(frame1, frame2, motion_threshold, motion_sensitivity):
    """Detect motion between two frames using average pixel difference and sensitivity."""
    global last_frame, motion_detected, motion_start_time, debounce_start_time
    if frame1 is None or frame2 is None:
        return False
    if last_frame is None:
        last_frame = frame2
        return False
    try:
        diff = np.abs(frame1.astype(np.int16) - frame2.astype(np.int16))
        avg_diff = np.mean(diff)
        changed_pixels = np.sum(diff > motion_threshold)
        total_pixels = frame1.shape[0] * frame1.shape[1]
        sensitivity_ratio = changed_pixels / total_pixels
        if avg_diff > motion_threshold and sensitivity_ratio > float(config['camera']['motion_sensitivity']):
            if not motion_detected:
                motion_detected = True
                motion_start_time = time.time()
                debounce_start_time = time.time()
                logging.info("Motion detected (avg_diff=%.2f, sensitivity=%.4f).", avg_diff, sensitivity_ratio)
            return True
        elif motion_detected and (time.time() - motion_start_time) > float(config['camera']['debounce_time']):
            if debounce_start_time is not None and (time.time() - debounce_start_time) > float(config['camera']['debounce_time']):
                logging.info("Motion stopped.")
                motion_detected = False
                debounce_start_time = None
                return False
    except Exception as e:
        logging.error("Error in motion detection: %s", e)
    return False

def record_video(filename, recording_duration):
    """Record video for a specified duration, appending circular buffer to the start."""
    global last_frame
    try:
        camera.start_encoder(encoder, output)
        camera.start_recording(encoder, filename)
        logging.info("Recording started: %s", filename)
        start_time = time.time()
        while running and (time.time() - start_time) < recording_duration:
            frame = capture_frame()
            if frame is not None:
                if last_frame is not None:
                    detect_motion(last_frame, frame, int(config['camera']['motion_threshold']), float(config['camera']['motion_sensitivity']))
                last_frame = frame
                time.sleep(1 / float(config['camera']['framerate']))
            else:
                logging.warning("Failed to capture frame during recording.")
                time.sleep(0.1)
        camera.stop_recording()
        camera.stop_encoder()
        logging.info("Recording stopped: %s", filename)
        save_circular_buffer(filename)
    except Exception as e:
        logging.error("Error recording video: %s", e)
        try:
            camera.stop_recording()
        except Exception:
            pass
        try:
            camera.stop_encoder()
        except Exception:
            pass

def save_circular_buffer(filename):
    """Save the last 3 seconds of frames to the circular buffer file."""
    global last_frame
    try:
        if last_frame is not None:
            with open(filename, 'ab') as f:
                f.write(last_frame.tobytes())
            logging.info("Circular buffer saved to %s", filename)
    except Exception as e:
        logging.error("Error saving circular buffer: %s", e)

def load_circular_buffer(filename):
    """Load the circular buffer file into memory."""
    global last_frame
    try:
        with open(filename, 'rb') as f:
            data = f.read()
        if data:
            last_frame = np.frombuffer(data, dtype=np.uint8).reshape(
                int(config['camera']['resolution_height']),
                int(config['camera']['resolution_width']),
                3
            )
            logging.info("Circular buffer loaded from %s", filename)
    except FileNotFoundError:
        logging.info("Circular buffer file not found: %s", filename)
    except Exception as e:
        logging.error("Error loading circular buffer: %s", e)

def manage_disk_space():
    """Delete oldest files if disk usage exceeds limit."""
    try:
        directory = "/home/pi/security_footage"
        files = [f for f in os.listdir(directory) if f.startswith("camera1_")]
        if not files:
            return
        total_size = sum(os.path.getsize(os.path.join(directory, f)) for f in files)
        limit_mb = int(config['camera']['disk_space_limit'])
        limit_bytes = limit_mb * 1024 * 1024
        if total_size > limit_bytes:
            files.sort(key=lambda f: os.path.getmtime(os.path.join(directory, f)))
            for f in files:
                if total_size <= limit_bytes:
                    break
                file_path = os.path.join(directory, f)
                try:
                    os.remove(file_path)
                    total_size -= os.path.getsize(file_path)
                    logging.info("Deleted old file: %s", file_path)
                except Exception as e:
                    logging.error("Error deleting file %s: %s", file_path, e)
    except Exception as e:
        logging.error("Error managing disk space: %s", e)

def read_light_sensor():
    """Read light sensor data from BH1750 via I2C."""
    global light_sensor_data, light_sensor_initialized, light_sensor_lock
    try:
        with light_sensor_lock:
            if not light_sensor_initialized:
                try:
                    bus.write_byte(light_sensor_address, 0x10)  # Continuous high-res mode
                    light_sensor_initialized = True
                    logging.info("Light sensor initialized at address 0x%02X", light_sensor_address)
                except Exception as e:
                    logging.error("Failed to initialize light sensor: %s", e)
                    light_sensor_initialized = False
                    return
            if bus is None:
                return
            try:
                data = bus.read_i2c_block_data(light_sensor_address, 0x00, 2)
                light_sensor_data = (data[1] + 256 * data[0]) / 1.2
                logging.info("Ambient light: %.2f lux", light_sensor_data)
            except Exception as e:
                logging.error("Error reading light sensor: %s", e)
                light_sensor_initialized = False
    except Exception as e:
        logging.error("Error reading light sensor: %s", e)

def signal_handler(sig, frame):
    """Handle SIGINT and SIGTERM for clean shutdown."""
    global running
    logging.info("Received signal %d, shutting down...", sig)
    running = False

def main():
    """Main function to run the security camera system."""
    global camera, bus, gpio_pin, running
    try:
        load_config()
        initialize_camera()
        gpio_pin = int(config['gpio']['motion_sensor_pin'])
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(gpio_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        logging.info("GPIO pin %d configured as input with pull-down.", gpio_pin)
        bus = smbus.SMBus(1)
        logging.info("I2C bus 1 initialized.")
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)
        while running:
            read_light_sensor()
            frame = capture_frame()
            if frame is not None:
                if last_frame is not None:
                    detect_motion(last_frame, frame, int(config['camera']['motion_threshold']), float(config['camera']['motion_sensitivity']))
                last_frame = frame
            time.sleep(1 / float(config['camera']['framerate']))
            if motion_detected:
                timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                filename = f"camera1_{timestamp}.h264"
                record_video(filename, int(config['camera']['recording_duration']))
                manage_disk_space()
                motion_detected = False
            else:
                time.sleep(0.1)
    except Exception as e:
        logging.error("Fatal error: %s", e)
    finally:
        logging.info("Cleaning up resources...")
        try:
            if camera:
                camera.stop()
                camera.close()
        except Exception as e:
            logging.error("Error stopping camera: %s", e)
        try:
            if bus:
                bus.close()
        except Exception as e:
            logging.error("Error closing I2C bus: %s", e)
        try:
            GPIO.cleanup()
        except Exception as e:
            logging.error("Error cleaning up GPIO: %s", e)
        logging.info("Shutdown complete.")

if __name__ == "__main__":
    main()

