import signal
import sys
import time

try:
    from gpiozero import Button, OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

INPUT_PINS = [4, 5, 6]
OUTPUT_PIN_1 = 23
OUTPUT_PIN_2 = 24

POLL_INTERVAL = 0.05

running = True
output_2_state = False


def handle_sigint(signum, frame):
    global running
    running = False


def main():
    global output_2_state

    signal.signal(signal.SIGINT, handle_sigint)

    try:
        inputs = [Button(pin, pull_up=True) for pin in INPUT_PINS]
        outputs = [OutputDevice(pin, initial_value=False) for pin in (OUTPUT_PIN_1, OUTPUT_PIN_2)]
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied accessing GPIO. Run with sudo or add user to the gpio group.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected initialization error: {e}", file=sys.stderr)
        sys.exit(1)

    output_1 = outputs[0]
    output_2 = outputs[1]

    try:
        while running:
            try:
                if inputs[0].is_active:
                    output_1.on()
                if inputs[1].is_active:
                    output_1.off()
                if inputs[2].is_active:
                    output_2_state = not output_2_state
                    output_2.value = output_2_state
            except GPIODeviceError as e:
                print(f"GPIO read/write error: {e}", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    finally:
        for dev in (output_1, output_2) + tuple(inputs) + tuple(outputs):
            try:
                dev.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

