import cv2
import numpy as np
import serial
import time
import signal
import sys
import RPi.GPIO as GPIO
from picamera2 import Picamera2

# Constants
CAMERA_RESOLUTION = (160, 120)
CAMERA_FRAMERATE = 16
SERIAL_PORT = '/dev/ttyACM0'
SERIAL_BAUDRATE = 115200
SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERVO_FREQUENCY = 50
SERVO_CENTER_DUTY_CYCLE = 7.0
MIN_TARGET_AREA = 10
X_THRESHOLD = 24
MAX_RECONNECT_ATTEMPTS = 3
RECONNECT_DELAY = 5

# Global state for cleanup
running = True
picam2 = None
arduino = None
servo1 = None
servo2 = None

def signal_handler(sig, frame):
    global running
    running = False

def cleanup():
    global picam2, arduino, servo1, servo2
    print("Cleaning up resources...")
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception as e:
            print(f"Error stopping camera: {e}")
    if servo1 is not None:
        try:
            servo1.stop()
        except Exception as e:
            print(f"Error stopping servo1: {e}")
    if servo2 is not None:
        try:
            servo2.stop()
        except Exception as e:
            print(f"Error stopping servo2: {e}")
    if arduino is not None and arduino.is_open:
        try:
            arduino.close()
        except Exception as e:
            print(f"Error closing serial port: {e}")
    GPIO.cleanup()
    print("Cleanup complete.")

def initialize_camera():
    global picam2
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": CAMERA_RESOLUTION, "format": "BGR888"},
            controls={"FrameRate": CAMERA_FRAMERATE}
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(0.1)
        return True
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return False

def initialize_arduino():
    global arduino
    for attempt in range(1, MAX_RECONNECT_ATTEMPTS + 1):
        try:
            arduino = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
            time.sleep(0.1)
            return True
        except serial.SerialException as e:
            print(f"Error connecting to Arduino (attempt {attempt}/{MAX_RECONNECT_ATTEMPTS}): {e}")
            if arduino is not None and arduino.is_open:
                try:
                    arduino.close()
                except Exception:
                    pass
            if attempt < MAX_RECONNECT_ATTEMPTS:
                time.sleep(RECONNECT_DELAY)
    return False

def initialize_servos():
    global servo1, servo2
    try:
        GPIO.setmode(GPIO.BOARD)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)
        servo1 = GPIO.PWM(SERVO_PIN_1, SERVO_FREQUENCY)
        servo2 = GPIO.PWM(SERVO_PIN_2, SERVO_FREQUENCY)
        servo1.start(SERVO_CENTER_DUTY_CYCLE)
        servo2.start(SERVO_CENTER_DUTY_CYCLE)
        time.sleep(0.5)
        return True
    except Exception as e:
        print(f"Error initializing servos: {e}")
        return False

def segment_red_hsv(frame):
    hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    lower_red = np.array([160, 160, 10])
    upper_red = np.array([190, 255, 255])
    mask = cv2.inRange(hsv, lower_red, upper_red)
    return mask

def segment_red_ycrcb(frame):
    ycr = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    lower_red = np.array([0, 165, 0])
    upper_red = np.array([255, 255, 255])
    mask = cv2.inRange(ycr, lower_red, upper_red)
    return mask

def segment_red(frame):
    mask1 = segment_red_hsv(frame)
    mask2 = segment_red_ycrcb(frame)
    mask = cv2.bitwise_or(mask1, mask2)
    return mask

def find_blob(mask):
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if contours:
        largest_contour = max(contours, key=cv2.contourArea)
        x, y, w, h = cv2.boundingRect(largest_contour)
        return (x, y, w, h)
    return None

def control_servos(x_position):
    if x_position < -X_THRESHOLD:
        servo1.ChangeDutyCycle(12.0)
        servo2.ChangeDutyCycle(12.0)
    elif x_position > X_THRESHOLD:
        servo1.ChangeDutyCycle(2.0)
        servo2.ChangeDutyCycle(2.0)
    else:
        servo1.ChangeDutyCycle(SERVO_CENTER_DUTY_CYCLE)
        servo2.ChangeDutyCycle(SERVO_CENTER_DUTY_CYCLE)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_camera():
        cleanup()
        sys.exit(1)

    if not initialize_arduino():
        cleanup()
        sys.exit(1)

    if not initialize_servos():
        cleanup()
        sys.exit(1)

    try:
        while running:
            frame = picam2.capture_array()
            if frame is None:
                continue

            mask = segment_red(frame)
            blob = find_blob(mask)

            if blob:
                x, y, w, h = blob
                area = cv2.contourArea(blob)
                if area > MIN_TARGET_AREA:
                    center_x = x + w // 2
                    control_servos(center_x - CAMERA_RESOLUTION[0] // 2)
                    print(f"Target detected at X: {center_x}, Y: {y}, Area: {area}")

            time.sleep(0.03)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

