import asyncio
import logging
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Thread-safe WebSocket connection manager for broadcasting frames."""

    def __init__(self) -> None:
        self._connections: list[asyncio.AbstractEventLoop] = []
        self._lock = threading.Lock()

    def has_connections(self) -> bool:
        with self._lock:
            return bool(self._connections)

    def add_connection(self, loop: asyncio.AbstractEventLoop) -> None:
        with self._lock:
            self._connections.append(loop)

    def remove_connection(self, loop: asyncio.AbstractEventLoop) -> None:
        with self._lock:
            self._connections.remove(loop) if loop in self._connections else None

    def broadcast(self, data: bytes) -> None:
        with self._lock:
            loops = list(self._connections)
        for loop in loops:
            try:
                loop.call_soon_threadsafe(self._send_frame, data)
            except (OSError, RuntimeError) as exc:
                logger.error("Error broadcasting to loop: %s", exc)

    def _send_frame(self, data: bytes) -> None:
        try:
            for loop in list(self._connections):
                try:
                    loop.call_soon_threadsafe(self._send_frame, data)
                except (OSError, RuntimeError):
                    self._connections.remove(loop)
        except Exception as exc:
            logger.error("Error sending frame: %s", exc)


class MotionDetector:
    """Detects motion between consecutive frames using a user-provided callback."""

    def __init__(
        self,
        detect_motion_function: Callable[[np.ndarray, np.ndarray], None],
    ) -> None:
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self._prev_frame: Optional[np.ndarray] = None
        self._lock = threading.Lock()

    def process_frame(self, frame: np.ndarray) -> None:
        with self._lock:
            if self._prev_frame is not None:
                self.detect_motion_function(self._prev_frame, frame)
            self._prev_frame = frame


class CameraStream:
    """Streams video from the Raspberry Pi camera to WebSocket clients."""

    def __init__(
        self,
        detect_motion_function: Callable[[np.ndarray, np.ndarray], None],
        resolution: tuple[int, int] = (640, 480),
        framerate: int = 10,
    ) -> None:
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.resolution = resolution
        self.framerate = framerate
        self.detect_motion_function = detect_motion_function
        self._stop_event = threading.Event()
        self._lock = threading.Lock()
        self._picam2: Optional[Picamera2] = None
        self._ws_handler = WebSocketHandler()
        self._motion_detector = MotionDetector(self.detect_motion_function)
        self._loop: Optional[asyncio.AbstractEventLoop] = None
        self._prev_frame: Optional[np.ndarray] = None
        self._current_frame: Optional[np.ndarray] = None
        self._running = False

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def start(self) -> None:
        if self._running:
            logger.warning("CameraStream already running.")
            return
        self._running = True
        try:
            self._init_camera()
            self._init_loop()
            self._start_camera()
        except Exception as exc:
            logger.error("Error starting camera stream: %s", exc)
            self.stop()

    def stop(self) -> None:
        if not self._running:
            return
        self._running = False
        self._stop_event.set()
        with self._lock:
            self._picam2 = None
        if self._loop is not None:
            try:
                self._loop.call_soon_threadsafe(self._stop_event.set)
            except Exception:
                pass
        logger.info("Camera stream stopped.")

    def has_connections(self) -> bool:
        return self._ws_handler.has_connections()

    def add_connection(self, loop: asyncio.AbstractEventLoop) -> None:
        self._ws_handler.add_connection(loop)

    def remove_connection(self, loop: asyncio.AbstractEventLoop) -> None:
        self._ws_handler.remove_connection(loop)

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------
    def _init_camera(self) -> None:
        try:
            self._picam2 = Picamera2()
            config = self._picam2.create_preview_configuration(
                main={"size": self.resolution, "format": "RGB888"},
