import time
import json
import logging
import logging.handlers
import threading
import signal
import sys
import numpy as np
import matplotlib.pyplot as plt
from smbus2 import SMBus
import adafruit_amg88xx
from picamera2 import Picamera2

DEFAULT_CONFIG = {
    "sampling_rate": 5,
    "motion_detection_threshold": 1.0,
    "logging_file_path": "beehive.log",
    "log_max_size": 1048576,
    "enable_camera": False,
}

running = True
bus = None
amg = None
camera = None
last_frames = None
latest_frame = None
logger = None
config = None

def load_config(path):
    try:
        with open(path, "r") as f:
            cfg = json.load(f)
        for k, v in DEFAULT_CONFIG.items():
            if k not in cfg:
                cfg[k] = v
        return cfg
    except FileNotFoundError:
        print(f"Config file not found: {path}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        print(f"Invalid JSON in config file: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()

def init_i2c():
    global bus
    try:
        bus = SMBus(1)
        return True
    except Exception as e:
        print(f"Failed to open I2C bus 1: {e}")
        return False

def init_amg88xx():
    global amg
    for attempt in range(3):
        try:
            amg = adafruit_amg88xx.AMG88XX(bus, addr=0x69)
            time.sleep(0.1)
            if all(0 <= p <= 255 for p in amg.pixels):
                return True
            print(f"AMG88XX init attempt {attempt+1}: pixels out of range")
        except Exception as e:
            print(f"AMG88XX init attempt {attempt+1} failed: {e}")
        time.sleep(2)
    print("Failed to initialize AMG88XX after 3 attempts.")
    return False

def init_camera():
    global camera
    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration())
        camera.start()
        return True
    except Exception as e:
        print(f"Failed to initialize camera: {e}")
        return False

def capture_image():
    global camera
    if not config.get("enable_camera", False):
        return
    if camera is None:
        return
    try:
        filename = f"motion_{time.strftime('%Y%m%d_%H%M%S')}.jpg"
        camera.capture_file(filename)
        logger.info(f"Captured image: {filename}")
    except Exception as e:
        logger.error(f"Failed to capture image: {e}")

def detect_motion():
    global last_frames, latest_frame, config, logger
    if last_frames is None or len(last_frames) < 2:
        return
    try:
        current = np.array(latest_frame)
        prev = np.array(last_frames[-1])
        diff = np.abs(current - prev)
        mean_diff = float(np.mean(diff))
        if mean_diff > config["motion_detection_threshold"]:
            logger.info(f"Motion detected! Mean diff: {mean_diff:.2f}")
            capture_image()
    except Exception as e:
        logger.error(f"Motion detection error: {e}")

def plot_thermal():
    global latest_frame, logger
    try:
        plt.clf()
        plt.imshow(latest_frame, cmap='jet', interpolation='nearest')
        plt.colorbar()
        plt.title(time.strftime("%Y-%m-%d %H:%M:%S"))
        plt.pause(0.001)
        logger.debug("Thermal plot rendered")
    except Exception as e:
        logger.error(f"Thermal plot error: {e}")

def sensor_thread():
    global last_frames, latest_frame, config, logger
    while running:
        try:
            pixels = np.array(amg.pixels)
            latest_frame = pixels
            if last_frames is not None:
                last_frames = np.roll(last_frames, -1, axis=0)
                last_frames[0] = pixels
            detect_motion()
            plot_thermal()
        except Exception as e:
            logger.error(f"Sensor thread error: {e}")
        time.sleep(1.0 / config["sampling_rate"])

def signal_handler(sig, frame):
    global running
    print("\nShutting down...")
    running = False

def main():
    global running, bus, amg, camera, last_frames, latest_frame, logger, config
    config = load_config("config.json")
    logger = logging.getLogger("BeehiveMonitor")
    logger.setLevel(logging.DEBUG)
    handler = logging.handlers.RotatingFileHandler(
        config["logging_file_path"],
        maxBytes=config.get("log_max_size", 1048576),
        backupCount=1
    )
    formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    handler.setFormatter(formatter)
    logger.addHandler(handler)
    logger.info("Beehive monitor started")
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not init_i2c():
        logger.error("I2C init failed. Exiting.")
        sys.exit(1)
    if not init_amg88xx():
        logger.error("AMG88XX init failed. Exiting.")
        sys.exit(1)
    if config.get("enable_camera", False):
        if not init_camera():
            logger.warning("Camera init failed. Continuing without camera.")
    last_frames = np.zeros((300, 8, 8), dtype=np.float32)
    sensor_thread = threading.Thread(target=sensor_thread, daemon=True)
    sensor_thread.start()
    try:
        while running:
            time.sleep(5)
    except KeyboardInterrupt:
        running = False
    finally:
        running = False
        sensor_thread.join(timeout=5)
        if camera is not None:
            try:
                camera.stop()
                camera.close()
            except Exception:
                pass
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        logger.info("Beehive monitor stopped")
        logger.handlers.clear()

if __name__ == "__main__":
    main()

