import io
import logging
import numpy as np
import cv2
from picamera2 import Picamera2

logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Accumulates MJPEG frames from a picamera2 stream and forwards complete
    non-I-frame JPEGs to an output sink."""

    def __init__(self, c):
        self.c = c
        self.b = io.BytesIO()
        self._closed = False

    def write(self, d):
        """Accumulate bytes; flush complete non-I-frame JPEGs to the sink."""
        if self._closed:
            return len(d) if d else 0
        try:
            self.b.write(d)
            cfg = self.c.current_configuration()
            if cfg is None:
                return len(d)
            enc = cfg.get('encode')
            if enc is None:
                return len(d)
            if enc.get('frame_type') != 1:
                # Non-I-frame: flush JPEG payload
                data = self.b.getvalue()
                if data:
                    try:
                        ok, data = cv2.imencode('.jpg', np.frombuffer(data, dtype=np.uint8))
                        if ok:
                            self.b.seek(0)
                            self.b.truncate()
                            self.sink(data.tobytes())
                    except Exception as exc:
                        logger.error("JPEG encode failed: %s", exc)
            return len(d)
        except Exception as exc:
            logger.error("Error in CameraStreamBuffer.write: %s", exc)
            return 0

    def close(self):
        self._closed = True
        try:
            self.b.close()
        except Exception:
            pass


class MotionDetectionBuffer:
    """Accumulates MJPEG frames and triggers a motion callback on new JPEG
    frames (SOI marker \xff\xd8)."""

    def __init__(self, f):
        self.f = f
        self.b = io.BytesIO()
        self._closed = False

    def write(self, d):
        """Parse MJPEG; decode new JPEG frames and call the motion callback."""
        if self._closed:
            return len(d) if d else 0
        try:
            self.b.write(d)
            data = self.b.getvalue()
            if data:
                soi = b'\xff\xd8'
                if data.startswith(soi):
                    prev = None
                    try:
                        prev = cv2.imdecode(np.frombuffer(data, dtype=np.uint8), cv2.IMREAD_COLOR)
                    except Exception as exc:
                        logger.error("JPEG decode failed: %s", exc)
                    if prev is not None:
                        if self.b.tell() > len(soi):
                            try:
                                ok, data = cv2.imdecode(np.frombuffer(data[len(soi):], dtype=np.uint8), cv2.IMREAD_COLOR)
                                if ok:
                                    self.b.seek(0)
                                    self.b.truncate()
                                    self.f(prev, data)
                            except Exception as exc:
                                logger.error("JPEG decode failed: %s", exc)
                    # Start accumulating the new frame after SOI
                    self.b.seek(0)
                    self.b.truncate()
            return len(d)
        except Exception as exc:
            logger.error("Error in MotionDetectionBuffer.write: %s", exc)
            return 0

    def close(self):
        self._closed = True
        try:
            self.b.close()
        except Exception:
            pass

