import signal
import sys
import time
import logging
import cv2
import pygame.mixer
from gpiozero import OutputDevice, Button
from picamera2 import Picamera2

import config
import face

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DOOR_PIN = 18
BUTTON_PIN = 17
SAMPLE_RATE = 48000

_running = True

def _signal_handler(signum, frame):
    global _running
    logger.info('Signal %s received, shutting down...', signum)
    _running = False

def _cleanup(mixer, door, button, picam2):
    logger.info('Cleaning up resources...')
    if mixer:
        try:
            pygame.mixer.quit()
        except Exception:
            pass
    if door:
        try:
            door.close()
        except Exception:
            pass
    if button:
        try:
            button.close()
        except Exception:
            pass
    if picam2:
        try:
            picam2.stop()
        except Exception:
            pass

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    door = None
    button = None
    picam2 = None
    mixer = None
    model = None

    try:
        try:
            door = OutputDevice(DOOR_PIN, active_high=True, initial_value=False)
            button = Button(BUTTON_PIN, pull_up=True, bounce_time=0.05)
        except Exception as e:
            logger.error('Failed to initialize GPIO: %s', e)
            return

        try:
            pygame.mixer.init(SAMPLE_RATE, -16, 1, 1024)
            mixer = pygame.mixer
        except Exception as e:
            logger.error('Failed to initialize pygame.mixer: %s', e)
            return

        try:
            model = cv2.face.EigenFaceRecognizer_create()
            model.read(config.TRAINING_FILE)
        except Exception as e:
            logger.error('Failed to load training data: %s', e)
            return

        try:
            picam2 = Picamera2()
            picam2.configure(picam2.create_preview_configuration(main={'format': 'BGR888', 'size': (640, 480)}))
            picam2.start()
        except Exception as e:
            logger.error('Failed to initialize camera: %s', e)
            return

        sounds = {}
        for name in ('welcome', 'wait', 'later'):
            try:
                sounds[name] = mixer.Sound(f'sounds/{name}.wav')
            except Exception as e:
                logger.error('Failed to load sound %s: %s', name, e)
                return

        logger.info('System initialized. Waiting for button press...')

        while _running:
            if button.is_button_up():
                logger.info('Button pressed, looking for face...')
                try:
                    frame = picam2.capture_array()
                except Exception as e:
                    logger.error('Camera capture failed: %s', e)
                    time.sleep(0.1)
                    continue

                if frame is None or frame.size == 0:
                    logger.warning('Empty frame received')
                    time.sleep(0.1)
                    continue

                try:
                    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                    label, confidence = face.recognize(gray)
                    logger.info('Predicted label: %s, confidence: %.2f', label, confidence)

                    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                        logger.info('Face recognized, unlocking door...')
                        door.on()
                        sounds['welcome'].play()
                    else:
                        sounds['wait'].play()
                except Exception as e:
                    logger.error('Face recognition error: %s', e)
                    sounds['later'].play()

            time.sleep(0.1)

    except Exception as e:
        logger.exception('Unexpected error: %s', e)
    finally:
