import time
import signal
import sys
import board
import busio
import adafruit_ssd1306
import adafruit_bme280
import adafruit_tsl2561

# Global resources for cleanup
i2c_bus = None
display = None
bme280 = None
tsl2561 = None
running = True

def cleanup():
    """Release all hardware resources cleanly."""
    global display, i2c_bus
    if display is not None:
        try:
            display.fill(0)
            display.show()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass

def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    running = False

def init_i2c():
    """Initialize the I2C bus on GPIO3 (SCL) and GPIO2 (SDA)."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return True
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return False

def init_oled():
    """Initialize the SSD1306 OLED display at address 0x3C."""
    global display
    try:
        display = adafruit_ssd1306.SSD1306_I2C(128, 64, i2c_bus, addr=0x3C)
        display.fill(0)
        display.show()
        return True
    except Exception as e:
        print(f"Error initializing OLED display: {e}")
        return False

def init_bme280():
    """Initialize the BME280 sensor at address 0x76."""
    global bme280
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=0x76)
        return True
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return False

def init_tsl2561():
    """Initialize the TSL2561 luminosity sensor at address 0x39."""
    global tsl2561
    try:
        tsl2561 = adafruit_tsl2561.TSL2561(i2c_bus, address=0x39)
        return True
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return False

def read_sensor_data():
    """Read temperature, humidity, pressure, and light intensity."""
    temp = humidity = pressure = light = None
    if bme280 is not None:
        try:
            temp = bme280.temperature
            humidity = bme280.humidity
        except Exception as e:
            print(f"Error reading BME280: {e}")
    if tsl2561 is not None:
        try:
            light = tsl2561.lux
        except Exception as e:
            print(f"Error reading TSL2561: {e}")
    return temp, humidity, pressure, light

def update_display(temp, humidity, pressure, light):
    """Update the OLED display with sensor readings."""
    if display is None:
        return
    try:
        display.fill(0)
        if temp is not None:
            display.text(f"Temp: {temp:.1f} C", 0, 0, 1)
        else:
            display.text("Temp: -- C", 0, 0, 1)
        if humidity is not None:
            display.text(f"Humidity: {humidity:.1f} %", 0, 16, 1)
        else:
            display.text("Humidity: -- %", 0, 16, 1)
        if pressure is not None:
            display.text(f"Pressure: {pressure:.1f} hPa", 0, 32, 1)
        else:
            display.text("Pressure: -- hPa", 0, 32, 1)
        if light is not None:
            display.text(f"Light: {light:.1f} lux", 0, 48, 1)
        else:
            display.text("Light: -- lux", 0, 48, 1)
        display.show()
    except Exception as e:
        print(f"Error updating display: {e}")

def main():
    """Main loop: initialize devices, read sensors, update display, handle shutdown."""
    global running
    signal.signal(signal.SIGINT, signal_handler)

    if not init_i2c():
        cleanup()
        sys.exit(1)

    if not init_oled():
        cleanup()
        sys.exit(1)

    if not init_bme280():
        print("BME280 not found; continuing without temperature/humidity/pressure.")

    if not init_tsl2561():
        print("TSL2561 not found; continuing without light sensor.")

    print("Starting sensor monitoring. Press Ctrl+C to exit.")

    while running:
        temp, humidity, pressure, light = read_sensor_data()
        update_display(temp, humidity, pressure, light)
        time.sleep(1)

    cleanup()
    print("Program terminated.")

if __name__ == "__main__":
    main()

