            logger.error("Invalid file index: %d", current_frame)
            return False

        logger.info("Playing GIF: %s", self.files[current_frame])

        try:
            while self._is_running:
                for frame in self.frames:
                    if not self._is_running:
                        return False

                    start_time = time.monotonic()
                    try:
                        self.display.display(frame.image)
                    except Exception as exc:
                        logger.exception(
                            "Error displaying frame on display: %s", exc
                        )
                        return False

                    elapsed = time.monotonic() - start_time
                    sleep_time = max(0.0, frame.duration / 1000.0 - elapsed)
                    if sleep_time > 0:
                        time.sleep(sleep_time)

                    if frame.loop == 0:
                        continue
                    if frame.loop > 0:
                        frame.loop -= 1
                        if frame.loop == 0:
                            break
        except Exception as exc:
            logger.exception("Error playing GIF: %s", exc)
            return False

        return True

    def run(self) -> None:
        """Continuously play through the loaded GIF files."""
        self._install_signal_handlers()
        try:
            while self._is_running:
                if not self.files:
                    logger.error("No files loaded. Call load_files() first.")
                    break

                if not self.play():
                    break

                self.advance()
        except Exception as exc:
            logger.exception("Error in run loop: %s", exc)
        finally:
            self.stop()

    def advance(self) -> None:
        """Advance to the next GIF file."""
        self.current_file_index = (self.current_file_index + 1) % len(self.files)
        logger.info("Advancing to next GIF: %s", self.files[self.current_file_index])

    def stop(self) -> None:
        """Stop the animation and release resources."""
        self._is_running = False
        self._restore_signal_handlers()
        logger.info("Animated GIF playback stopped.")

    def __enter__(self) -> "AnimatedGif":
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.stop()

