    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None

def initialize_lcd(i2c_bus, address=LCD_I2C_ADDRESS):
    try:
        lcd = character_lcd.Character_LCD_I2C(i2c_bus, LCD_COLS, LCD_ROWS, address=address)
        lcd.clear()
        return lcd
    except Exception as e:
        print(f"Error initializing LCD at 0x{address:02X}: {e}", file=sys.stderr)
        return None

def initialize_dht22(pin):
    try:
        return adafruit_dht.DHT22(pin, use_pulseio=False)
