        return None

def read_sensor_data(dht22_sensor):
    try:
        temperature = dht22_sensor.temperature
        humidity = dht22_sensor.humidity
        if temperature is not None and humidity is not None:
            return temperature, humidity
        return None, None
    except RuntimeError as e:
        # DHT22 often throws checksum or timing errors; retry next cycle
        print(f"Sensor read error (retry next cycle): {e}", file=sys.stderr)
        return None, None
    except Exception as e:
        print(f"Unexpected sensor error: {e}", file=sys.stderr)
        return None, None

