    try:
        lcd_display.clear()
        if temperature is not None and humidity is not None:
            lcd_display.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
        else:
            lcd_display.message = "Sensor Error!"
    except Exception as e:
        print(f"Error displaying data: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    lcd_display = initialize_lcd(i2c_bus)
    if lcd_display is None:
        sys.exit(1)

    dht22_sensor = initialize_dht22(DHT_PIN)
    if dht22_sensor is None:
        sys.exit(1)

    try:
        while _running:
            temperature, humidity = read_sensor_data(dht22_sensor)
            display_data(lcd_display, temperature, humidity)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        try:
            lcd_display.clear()
        except Exception:
            pass
        try:
            dht22_sensor.exit()
        except Exception:
            pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

