import signal
import sys
import time
import smbus2
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

TSL2561_ADDR = 0x29
OLED_ADDR = 0x3C
I2C_BUS = 1

TSL2561_COMMAND_BIT = 0x80
TSL2561_REGISTER_ENABLE = 0x00
TSL2561_REGISTER_CONTROL = 0x01
TSL2561_REGISTER_DATA0_LOW = 0x14
TSL2561_REGISTER_DATA1_LOW = 0x16
TSL2561_REGISTER_ID = 0x12

TSL2561_ID = 0x50
TSL2561_POWER_ON = 0x03
TSL2561_INTEGRATIONTIME_101MS = 0x00
TSL2561_GAIN_1X = 0x00

running = True


def signal_handler(sig, frame):
    global running
    running = False


def write_register(bus, addr, reg, value):
    bus.write_byte_data(addr, TSL2561_COMMAND_BIT | reg, value)


def read_register(bus, addr, reg):
    return bus.read_byte_data(addr, TSL2561_COMMAND_BIT | reg)


def read_block(bus, addr, reg, length):
    return list(bus.read_i2c_block_data(addr, TSL2561_COMMAND_BIT | reg, length))


def init_tsl2561(bus):
    try:
        id = read_register(bus, TSL2561_ADDR, TSL2561_REGISTER_ID)
        if id != TSL2561_ID:
            print(f"Error: TSL2561 not found (ID=0x{id:02X}, expected 0x{TSL2561_ID:02X})")
            return False
        write_register(bus, TSL2561_ADDR, TSL2561_REGISTER_ENABLE, TSL2561_POWER_ON)
        write_register(bus, TSL2561_ADDR, TSL2561_REGISTER_CONTROL,
                       TSL2561_INTEGRATIONTIME_101MS | TSL2561_GAIN_1X)
        return True
    except OSError as e:
        print(f"Error initializing TSL2561: {e}")
        return False


def read_lux(bus):
    try:
        data = read_block(bus, TSL2561_ADDR, TSL2561_REGISTER_DATA0_LOW, 4)
        ch0 = data[0] | (data[1] << 8)
        ch1 = data[2] | (data[3] << 8)
        if ch0 == 0:
            return 0.0
        ratio = ch1 / float(ch0)
        if ratio <= 0.50:
            lux = 0.0304 * ch0 - 0.062 * ch0 * (ratio ** 1.4)
        elif ratio <= 0.61:
            lux = 0.0224 * ch0 - 0.031 * ch1
        elif ratio <= 0.80:
            lux = 0.0128 * ch0 - 0.0153 * ch1
        elif ratio <= 1.3:
            lux = 0.00146 * ch0 - 0.00112 * ch1
        else:
            lux = 0.0
        return max(0.0, lux)
    except OSError as e:
        print(f"Error reading TSL2561: {e}")
        return 0.0


def init_oled(bus):
    try:
        serial = i2c(port=I2C_BUS, address=OLED_ADDR)
        device = ssd1306(serial)
        device.clear()
        return device
    except OSError as e:
        print(f"Error initializing OLED: {e}")
        return None


def set_oled_contrast(device, lux):
    contrast = int((lux / 1000.0) * 255)
    contrast = max(0, min(255, contrast))
    try:
        device.contrast(contrast)
    except OSError as e:
        print(f"Error setting OLED contrast: {e}")


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    oled = None
    try:
        bus = smbus2.SMBus(I2C_BUS)
        if not init_tsl2561(bus):
            print("TSL2561 initialization failed; continuing without sensor.")
        oled = init_oled(bus)
        if oled is None:
            print("OLED initialization failed; continuing without display.")
    except OSError as e:
        print(f"Fatal: I2C bus {I2C_BUS} unavailable: {e}")
        sys.exit(1)

    try:
        while running:
            lux = 0.0
            if bus is not None:
                lux = read_lux(bus)
            if oled is not None:
                set_oled_contrast(oled, lux)
            if oled is not None:
                with canvas(oled) as draw:
                    draw.text((0, 0), f"Lux: {lux:.1f}", fill="white")
            time.sleep(1)
    finally:
        if bus is not None:
            try:
                write_register(bus, TSL2561_ADDR, TSL2561_REGISTER_ENABLE, 0x00)
            except OSError:
                pass
            try:
                bus.close()
            except OSError:
                pass
        if oled is not None:
            try:
                oled.clear()
            except OSError:
                pass


if __name__ == "__main__":
    main()

