import os
import time
import signal
import logging
from PIL import Image, ImageOps
from luma.core.interface.serial import spi
from luma.core.render import canvas
from luma.lcd.device import st7789

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class GifPlayer:
    """
    Plays GIF images on an ST7789 display connected via SPI on a Raspberry Pi.
    """

    def __init__(self, folder_path, width=240, height=240):
        self.folder_path = folder_path
        self.width = width
        self.height = height
        self.device = None
        self._running = True

        if not os.path.isdir(self.folder_path):
            raise FileNotFoundError(f"Folder not found: {self.folder_path}")

        try:
            serial = spi(port=0, device=0, bus_speed_hz=32000000)
            self.device = st7789(serial, width=self.width, height=self.height)
            logger.info("Display initialized successfully.")
        except Exception as e:
            logger.error(f"Failed to initialize display: {e}")
            raise

    def _signal_handler(self, signum, frame):
        logger.info(f"Signal {signum} received, shutting down...")
        self._running = False

    def play(self, gif_path):
        try:
            with Image.open(gif_path) as img:
                duration = img.info.get("duration", 100)
                if duration < 10:
                    duration = 100

                for frame_index in range(img.n_frames):
                    img.seek(frame_index)
                    frame = img.convert("RGB")
                    padded = ImageOps.pad(
                        frame,
                        (self.width, self.height),
                        method=Image.NEAREST,
                        color=(0, 0, 0),
                        centering=(0.5, 0.5)
                    )
                    self.device.display(padded)
                    time.sleep(duration / 1000.0)
        except FileNotFoundError:
            logger.error(f"GIF file not found: {gif_path}")
        except Exception as e:
            logger.error(f"Error playing GIF {gif_path}: {e}")

    def run(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            gif_files = [f for f in os.listdir(self.folder_path) if f.lower().endswith(".gif")]
            if not gif_files:
                logger.warning(f"No GIF files found in {self.folder_path}")
                return

            logger.info(f"Found {len(gif_files)} GIF files. Starting playback loop...")
            while self._running:
                for gif_file in gif_files:
                    if not self._running:
                        break
                    gif_path = os.path.join(self.folder_path, gif_file)
                    self.play(gif_path)
        except Exception as e:
            logger.error(f"An unexpected error occurred: {e}")
        finally:
            if self.device:
                try:
                    self.device.cleanup()
                    logger.info("Display resources cleaned up.")
                except Exception as e:
                    logger.error(f"Error during display cleanup: {e}")

if __name__ == "__main__":
    gif_player = None
    try:
        gif_player = GifPlayer(folder_path="/home/pi/gifs")
        gif_player.run()
    except FileNotFoundError as e:
        logger.error(f"Initialization failed: {e}")
    except Exception as e:
        logger.error(f"Initialization failed: {e}")
    finally:
        if gif_player:
            if gif_player.device:
                try:
                    gif_player.device.cleanup()
                except Exception:
                    pass

