from typing import List, Optional

from PIL import Image
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

GIF_WIDTH = 128
GIF_HEIGHT = 64
I2C_ADDRESS = 0x3C
I2C_BUS = 1

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    logger.info("Signal received, shutting down...")


def load_gif_files(folder_path: str) -> List[str]:
    if not os.path.isdir(folder_path):
        logger.error(f"Folder not found: {folder_path}")
        return []
    gif_files = [f for f in os.listdir(folder_path) if f.lower().endswith('.gif')]
    if not gif_files:
        logger.warning(f"No .gif files found in {folder_path}")
    return [os.path.join(folder_path, f) for f in gif_files]


def load_gif_images(gif_path: str) -> Optional[List[Image.Image]]:
    try:
        with Image.open(gif_path) as img:
            img = img.convert('RGB')
            frames = []
            for frame_index in range(img.n_frames):
                img.seek(frame_index)
                frame = img.resize((GIF_WIDTH, GIF_HEIGHT), Image.LANCZOS)
                frame = Image.new('RGB', (GIF_WIDTH, GIF_HEIGHT), (0, 0, 0))
                frame.paste(img, (0, 0))
                frames.append(frame)
            return frames
    except FileNotFoundError:
        logger.error(f"File not found: {gif_path}")
    except Exception as e:
        logger.error(f"Error loading GIF {gif_path}: {e}")
    return None


def get_gif_duration(gif_path: str) -> Optional[int]:
    try:
        with Image.open(gif_path) as img:
            return img.info.get('duration', 100)
    except Exception as e:
        logger.error(f"Error getting duration of {gif_path}: {e}")
        return None


def get_gif_loop_count(gif_path: str) -> Optional[int]:
    try:
        with Image.open(gif_path) as img:
            return img.info.get('loop', 0)
    except Exception as e:
        logger.error(f"Error getting loop count of {gif_path}: {e}")
        return None


