    images = load_gif_images(gif_path)
    if not images:
        return

    duration = get_gif_duration(gif_path)
    if duration is None:
        return

    if loop_count == 0:
        loop_count = float('inf')

    total_frames = len(images)
    for _ in range(loop_count):
        for image in images:
            if not _running:
                return
            try:
                device.display(image)
            except Exception as e:
                logger.error(f"Error displaying image: {e}")
                return
            time.sleep(duration / 1000.0)


def display_gif(device: ssd1306, gif_path: str, loop_count: int) -> None:
    try:
        play_gif(device, gif_path, loop_count)
    except Exception as e:
        logger.error(f"Error displaying GIF: {e}")
        traceback.print_exc()


def main(gif_folder: str, loop_count: int) -> None:
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        serial = i2c(port=I2C_BUS, address=I2C_ADDRESS)
        device = ssd1306(serial)
    except Exception as e:
        logger.error(f"Failed to initialize OLED display: {e}")
        return

    gif_files = load_gif_files(gif_folder)
    if not gif_files:
        logger.warning("No GIF files to display.")
        return

    logger.info(f"Found {len(gif_files)} GIF files. Starting playback...")
    try:
        while _running:
            for gif_path in gif_files:
                if not _running:
                    break
                display_gif(device, gif_path, loop_count)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        try:
            device.cleanup()
        except Exception:
            pass
        logger.info("Display closed. Exiting.")


if __name__ == "__main__":
    main("/home/pi/gifs", 0)

