import time
import sys
import board
import adafruit_dht

# DHT11 sensor on GPIO4 (BCM) — physical pin 7
DHT_PIN = board.D4
MAX_RETRIES = 5
RETRY_DELAY_S = 2.0
READ_INTERVAL_S = 1.0  # DHT11 requires >=1 s between reads

def read_dht11_sensor():
    """
    Attempt up to MAX_RETRIES reads from the DHT11 sensor.
    Returns (temperature_c, humidity) on success, or None on failure.
    """
    sensor = None
    try:
        sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Error: failed to initialize DHT11 on GPIO4: {e}")
        return None

    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            # DHT11 checksum or timing errors raise RuntimeError
            print(f"Read attempt {attempt}/{MAX_RETRIES} failed: {e}")
        except Exception as e:
            print(f"Unexpected error on attempt {attempt}/{MAX_RETRIES}: {e}")

        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY_S)

    return None

def main():
    result = read_dht11_sensor()
    if result is not None:
        temperature, humidity = result
        print(f"Temperature: {temperature:.1f} C")
        sys.exit(0)
    else:
        print("Error: Failed to read from DHT11 sensor after multiple attempts.")
        sys.exit(1)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
        sys.exit(130)

