import json
import random
import time
import logging
import threading
import paho.mqtt.client as mqtt

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

BROKER = "test.mosquitto.org"
PORT = 1883
KEEPALIVE = 60
TOPIC = "classroom/temperature"
NUM_MESSAGES = 5
RECONNECT_DELAY = 2
MAX_RECONNECT_ATTEMPTS = 3


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to broker %s:%d", BROKER, PORT)
    else:
        logger.error("Connection failed with reason code %s", reason_code)


def on_publish(client, userdata, mid, reason_code, properties):
    logger.debug("Message %s published (reason code: %s)", mid, reason_code)


def on_disconnect(client, userdata, flags, reason_code, properties):
    if reason_code != 0:
        logger.warning("Unexpected disconnect from broker (reason code: %s)", reason_code)
    else:
        logger.info("Disconnected from broker cleanly")


def build_payload(index):
    temperature = round(random.uniform(19.0, 26.0), 2)
    return json.dumps({"index": index, "temperature": temperature})


def publish_once(client, index):
    payload = build_payload(index)
    info = client.publish(TOPIC, payload, qos=1)
    if info.rc == mqtt.MQTT_ERR_SUCCESS:
        logger.info("Published index %d: %s", index, payload)
    else:
        logger.error("Failed to publish index %d: rc=%s", index, info.rc)


def run_publisher():
    client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        client_id="rpi-classroom-publisher",
    )
    client.on_connect = on_connect
    client.on_publish = on_publish
    client.on_disconnect = on_disconnect

    connected = threading.Event()

    def _on_connect_wrapper():
        connected.set()

    client._on_connect = _on_connect_wrapper

    for attempt in range(1, MAX_RECONNECT_ATTEMPTS + 1):
        try:
            logger.info("Connecting to %s:%d (attempt %d/%d)", BROKER, PORT, attempt, MAX_RECONNECT_ATTEMPTS)
            client.connect(BROKER, PORT, KEEPALIVE)
            connected.wait()
            break
        except Exception as e:
            logger.error("Connection attempt %d failed: %s", attempt, e)
            if attempt < MAX_RECONNECT_ATTEMPTS:
                logger.info("Retrying in %d seconds...", RECONNECT_DELAY)
                time.sleep(RECONNECT_DELAY)
            else:
                logger.error("Max reconnect attempts reached; aborting.")
                client.disconnect()
                return False
    else:
        return False

    try:
        for i in range(NUM_MESSAGES):
            publish_once(client, i)
            if i < NUM_MESSAGES - 1:
                time.sleep(1)
        logger.info("All %d messages published successfully.", NUM_MESSAGES)
        return True
    except Exception as e:
        logger.error("Unexpected error during publishing: %s", e)
        return False
    finally:
        client.disconnect()
        logger.info("Disconnected cleanly.")


if __name__ == "__main__":
    success = run_publisher()
    exit(0 if success else 1)

