from datetime import datetime

import adafruit_dht
from board import D4

DATA_DIR = '/home/pi/data'
CSV_FILE = os.path.join(DATA_DIR, 'sensor_data.csv')
ERROR_LOG = os.path.join(DATA_DIR, 'error.log')

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def ensure_data_dir():
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
    except OSError as e:
        print(f'Error creating data directory {DATA_DIR}: {e}', file=sys.stderr)
        sys.exit(1)

def log_error(message):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(ERROR_LOG, 'a') as f:
            f.write(f'{timestamp} - ERROR: {message}\n')
    except OSError as e:
        print(f'Failed to write to error log: {e}', file=sys.stderr)

def log_data(timestamp, temperature):
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
        file_exists = os.path.isfile(CSV_FILE)
        with open(CSV_FILE, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            if not file_exists:
                writer.writerow(['Timestamp', 'Temperature (Celsius)'])
            writer.writerow([timestamp, f'{temperature:.2f}'])
    except OSError as e:
        log_error(f'Failed to write to CSV file: {e}')

def main():
    global _running
    ensure_data_dir()

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        dht_device = adafruit_dht.DHT22(D4, use_pulseio=False)
    except Exception as e:
        log_error(f'Failed to initialize DHT22 on GPIO4: {e}')
        sys.exit(1)

    try:
        while _running:
            timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            try:
                temperature = dht_device.temperature
                if temperature is None:
                    raise RuntimeError('Sensor returned None')
                log_data(timestamp, temperature)
                print(f'{timestamp} - Temperature: {temperature:.2f} C')
            except RuntimeError as e:
                log_error(f'Sensor read failed: {e}')
            except Exception as e:
                log_error(f'Unexpected error: {e}')
            time.sleep(5)
    finally:
        try:
            dht_device.exit()
        except Exception:
            pass
        print('Program terminated gracefully.')

if __name__ == '__main__':
    main()

