import time
import logging
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20:
    def __init__(self, i2c_bus=1, address=0x38):
        self.address = address
        self.bus = None
        try:
            self.bus = smbus2.SMBus(i2c_bus)
            time.sleep(0.5)
            status = self._read_register(0x71, 1)[0]
            if (status & 0x18) != 0x18:
                logging.error("DHT20 not responding at address 0x%02X. Status byte 0x%02X does not match 0x18.", address, status)
                self.close()
                return
            logging.info("DHT20 initialized at address 0x%02X.", address)
        except Exception as e:
            logging.error("Failed to initialize DHT20: %s", e)
            self.close()

    def _read_register(self, register, length):
        if self.bus is None:
            raise RuntimeError("I2C bus not initialized.")
        try:
            return self.bus.read_i2c_block_data(self.address, register, length)
        except Exception as e:
            logging.error("I2C read error at register 0x%02X: %s", register, e)
            raise

    def _write_register(self, register, data):
        if self.bus is None:
            raise RuntimeError("I2C bus not initialized.")
        try:
            self.bus.write_i2c_block_data(self.address, register, data)
        except Exception as e:
