import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20:
    def __init__(self, i2c_bus=1, address=0x38):
        self.address = address
        self.bus = None
        self.crc_error = False
        try:
            self.bus = SMBus(i2c_bus)
            time.sleep(0.05)
            status = self._read_register(0x71)
            if status is None:
                self._close()
                raise IOError("Failed to read status register")
            logging.info(f"DHT20 detected at address 0x{address:02X}, status=0x{status:02X}")
        except Exception as e:
            logging.error(f"Error initializing DHT20: {e}")
            self._close()

    def _read_register(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except Exception as e:
            logging.error(f"I/O error reading register 0x{register:02X}: {e}")
            return None

    def _write_register(self, register, value):
        try:
            self.bus.write_byte_data(self.address, register, value)
        except Exception as e:
            logging.error(f"I/O error writing register 0x{register:02X}: {e}")

    def _crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def measure(self):
        if self.bus is None:
            logging.error("I2C bus not initialized")
            return None, None, True
        try:
            self._write_register(0xAC, 0x33)
            start_time = time.time()
            while True:
                status = self._read_register(0x71)
                if status is None:
                    logging.error("Failed to read status register during measurement")
                    return None, None, True
                if not (status & 0x80):
                    break
                if time.time() - start_time > 0.1:
                    logging.error("Measurement timeout (100ms)")
                    return None, None, True
                time.sleep(0.01)
            data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
            if len(data) < 7:
                logging.error(f"Insufficient data read: got {len(data)} bytes")
                return None, None, True
            if self._crc8(data[:6]) != data[6]:
                logging.error("CRC mismatch")
                self.crc_error = True
                return None, None, True
            humidity_raw = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4)
            temperature_raw = ((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]
            temperature = float(temperature_raw) / 5242.88 - 50.0
            humidity = float(humidity_raw) / 0x100000 * 100.0
            return temperature, humidity, False
        except Exception as e:
            logging.error(f"Error during measurement: {e}")
            return None, None, True

    def _close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None

    def __del__(self):
        self._close()

def main():
    sensor = DHT20(i2c_bus=1, address=0x38)
    if sensor.bus is None:
        logging.error("Sensor initialization failed")
        sys.exit(1)
    def signal_handler(sig, frame):
        logging.info("Interrupt received, shutting down...")
        sensor._close()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        temperature, humidity, crc_error = sensor.measure()
        if crc_error:
            logging.error("Measurement failed due to CRC error")
        else:
            logging.info(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        sensor._close()

if __name__ == "__main__":
    main()

