import time
import logging
import random
import sqlite3
import signal
import sys
import gpiod

# Configuration
MOTOR_FORWARD_PIN = 17
MOTOR_BACKWARD_PIN = 18
MOTOR_ENABLE_PIN = 27
TEMP_MIN = 25.0
TEMP_MAX = 30.0
CONFIG_FILE = "config.txt"
LOG_FILE = "greenhouse_vent.log"
DATABASE_FILE = "greenhouse_data.db"
LOOP_INTERVAL = 60  # seconds

# Global state
running = True
chip = None
lines = []

def setup_logging():
    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.DEBUG,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

def read_config():
    global TEMP_MIN, TEMP_MAX
    try:
        with open(CONFIG_FILE, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    logging.warning(f"Skipping malformed line: {line}")
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip()
                if key == "TEMP_MIN":
                    try:
                        TEMP_MIN = float(value)
                    except ValueError:
                        logging.error(f"Invalid TEMP_MIN value: {value}")
                elif key == "TEMP_MAX":
                    try:
                        TEMP_MAX = float(value)
                    except ValueError:
                        logging.error(f"Invalid TEMP_MAX value: {value}")
        logging.info(f"Config loaded: TEMP_MIN={TEMP_MIN}, TEMP_MAX={TEMP_MAX}")
    except FileNotFoundError:
        logging.warning(f"Config file {CONFIG_FILE} not found. Using defaults.")
    except Exception as e:
        logging.error(f"Error reading config: {e}")

def setup_gpio():
    global chip, lines
    try:
        chip = gpiod.Chip("gpiochip0")
        for pin in [MOTOR_FORWARD_PIN, MOTOR_BACKWARD_PIN, MOTOR_ENABLE_PIN]:
            line = chip.get_line(pin)
            line.request(consumer="greenhouse_vent", type=gpiod.LINE_REQ_DIR_OUT)
            line.set_value(0)
            lines.append(line)
        logging.info("GPIO setup complete.")
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        raise

def cleanup_gpio():
    global chip, lines
    if chip is not None:
        for line in lines:
            try:
                line.set_value(0)
                line.release()
            except Exception:
                pass
        try:
            chip.close()
        except Exception:
            pass
        logging.info("GPIO cleanup complete.")

def signal_handler(sig, frame):
    global running
    logging.info("Received signal, shutting down...")
    running = False

def get_temperature():
    return random.uniform(20.0, 35.0)

def calculate_vent_position(temperature):
    if temperature <= TEMP_MIN:
        return 0.0
    elif temperature >= TEMP_MAX:
        return 100.0
    else:
        return ((temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * 100.0

def store_data(timestamp, temperature, vent_position):
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS greenhouse_data (
                timestamp TEXT,
                temperature REAL,
                vent_position REAL
            )
        """)
        cursor.execute(
            "INSERT INTO greenhouse_data (timestamp, temperature, vent_position) VALUES (?, ?, ?)",
            (timestamp, temperature, vent_position)
        )
        conn.commit()
        conn.close()
        logging.debug(f"Data stored: {timestamp}, {temperature:.2f}, {vent_position:.2f}")
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

def main():
    global running
    setup_logging()
    read_config()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        setup_gpio()
    except Exception:
        logging.error("Failed to initialize GPIO. Exiting.")
        sys.exit(1)
    try:
        while running:
            temperature = get_temperature()
            logging.debug(f"Simulated temperature: {temperature:.2f}°C")
            if not (0.0 <= temperature <= 50.0):
                logging.warning(f"Temperature {temperature:.2f}°C out of range. Skipping.")
                time.sleep(LOOP_INTERVAL)
                continue
            vent_position = calculate_vent_position(temperature)
            logging.debug(f"Vent position: {vent_position:.2f}%")
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            store_data(timestamp, temperature, vent_position)
            current_position = vent_position
            target_position = vent_position
            if current_position < target_position - 1:
                logging.info("Motor would move forward")
                # In a real system, drive forward here
            elif current_position > target_position + 1:
                logging.info("Motor would move backward")
                # In a real system, drive backward here
            else:
                logging.info("Motor would stay")
            time.sleep(LOOP_INTERVAL)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

