import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Initialize I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Failed to initialize I2C bus: {e}")
    exit(1)

# Initialize TCA9548A multiplexer at default address 0x70
try:
    tca9548a = adafruit_tca9548a.TCA9548A(i2c_bus)
except Exception as e:
    print(f"Failed to initialize TCA9548A multiplexer: {e}")
    exit(1)

# Initialize BME280 on multiplexer channel 0 (default address 0x76 or 0x77)
try:
    bme280 = adafruit_bme280.Adafruit_BME280_I2C(tca9548a[0], i2c_bus)
except Exception as e:
    print(f"Failed to initialize BME280 on channel 0: {e}")
    exit(1)

# Initialize TSL2591 on multiplexer channel 1 (default address 0x29)
try:
    tsl2591 = adafruit_tsl2591.TSL2591(tca9548a[1])
except Exception as e:
    print(f"Failed to initialize TSL2591 on channel 1: {e}")
    exit(1)

# Main loop
try:
    while True:
        # Read temperature and humidity from BME280
        try:
            temperature = bme280.temperature
            humidity = bme280.humidity
            print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
        except Exception as e:
            print(f"Error reading BME280: {e}")

        # Read light intensity from TSL2591
        try:
            light_intensity = tsl2591.lux
            print(f"Light Intensity: {light_intensity:.2f} lux")
        except Exception as e:
            print(f"Error reading TSL2591: {e}")

        time.sleep(2)

except KeyboardInterrupt:
    print("Exiting program.")

