import time
import signal
import sys
from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 50
MIN_TEMP = 40.0
MAX_TEMP = 50.0
MIN_DUTY = 0.0
MAX_DUTY = 100.0
READ_INTERVAL = 1.0

fan = None
running = True

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
        fan = None

def handle_signal(signum, frame):
    global running
    running = False

def read_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def compute_duty(temp):
    if temp <= MIN_TEMP:
        return MIN_DUTY
    if temp >= MAX_TEMP:
        return MAX_DUTY
    return (temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) + MIN_DUTY

def main():
    global fan
    signal.signal(signal.SIGTERM, handle_signal)
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        while running:
            temp = read_cpu_temp()
            if temp is not None:
                duty = compute_duty(temp)
                fan.value = duty / 100.0
                print(f"CPU: {temp:.1f}°C  Fan: {duty:.1f}%")
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nFan control stopped by user.")
    finally:
        cleanup()

if __name__ == '__main__':
    main()

