import time
import sys
import signal

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT_S = 1.0
LOG_FILE = 'temperature_log.csv'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def celsius_to_fahrenheit(celsius):
    return celsius * 9.0 / 5.0 + 32.0

def ensure_csv_header(ser):
    try:
        with open(LOG_FILE, 'a', newline='') as f:
            pass
    except OSError as e:
        print(f"Error opening log file: {e}", file=sys.stderr)
        return False
    try:
        with open(LOG_FILE, 'r') as f:
            pass
    except FileNotFoundError:
        try:
            with open(LOG_FILE, 'w', newline='') as f:
                f.write('timestamp,celsius,fahrenheit\n')
        except OSError as e:
            print(f"Error writing CSV header: {e}", file=sys.stderr)
            return False
    return True

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not ensure_csv_header(None):
        sys.exit(1)

    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT_S,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                celsius = float(line)
            except ValueError:
                print(f"Invalid data received (not numeric): {line!r}", file=sys.stderr)
                continue

            fahrenheit = celsius_to_fahrenheit(celsius)
            timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
            try:
                with open(LOG_FILE, 'a', newline='') as f:
                    f.write(f"{timestamp},{celsius:.2f},{fahrenheit:.2f}\n")
            except OSError as e:
                print(f"Error writing to log file: {e}", file=sys.stderr)

    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

