import RPi.GPIO as GPIO
import time
import sys

DHT_PIN = 4
RETRY_DELAY = 2
MAX_RETRIES = 3
LOOP_DELAY = 5
SENSOR_TIMEOUT = 0.0001  # 10 ms max wait for sensor response

def read_dht22():
    """Read temperature and humidity from DHT22 sensor.
    Returns (temperature, humidity) as floats, or (None, None) on failure."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            # Send start signal
            GPIO.setup(DHT_PIN, GPIO.OUT)
            GPIO.output(DHT_PIN, GPIO.LOW)
            time.sleep(0.018)  # 18 ms
            GPIO.output(DHT_PIN, GPIO.HIGH)
            time.sleep(0.000040)  # 40 µs hold
            GPIO.setup(DHT_PIN, GPIO.IN)

            # Wait for sensor response (80 µs low + 80 µs high)
            timeout_start = time.time()
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() - timeout_start > SENSOR_TIMEOUT:
                    raise TimeoutError("No response from sensor (timeout)")
            timeout_start = time.time()
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                if time.time() - timeout_start > SENSOR_TIMEOUT:
                    raise TimeoutError("No response from sensor (timeout)")
            timeout_start = time.time()
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() - timeout_start > SENSOR_TIMEOUT:
                    raise TimeoutError("No response from sensor (timeout)")

            # Read 40 bits
            data = []
            for _ in range(40):
                timeout_start = time.time()
                while GPIO.input(DHT_PIN) == GPIO.LOW:
                    if time.time() - timeout_start > SENSOR_TIMEOUT:
                        raise TimeoutError("Timeout reading bit")
                timeout_start = time.time()
                while GPIO.input(DHT_PIN) == GPIO.HIGH:
                    if time.time() - timeout_start > SENSOR_TIMEOUT:
                        raise TimeoutError("Timeout reading bit")
                data.append(1 if GPIO.input(DHT_PIN) == GPIO.HIGH else 0)

            # Parse bytes
            humidity_int = (data[0] << 7) | (data[1] << 6) | (data[2] << 5) | (data[3] << 4) | (data[4] << 3) | (data[5] << 2) | (data[6] << 1) | data[7]
            humidity_dec = (data[8] << 7) | (data[9] << 6) | (data[10] << 5) | (data[11] << 4) | (data[12] << 3) | (data[13] << 2) | (data[14] << 1) | data[15]
            temp_int = (data[16] << 7) | (data[17] << 6) | (data[18] << 5) | (data[19] << 4) | (data[20] << 3) | (data[21] << 2) | (data[22] << 1) | data[23]
            temp_dec = (data[24] << 7) | (data[25] << 6) | (data[26] << 5) | (data[27] << 4) | (data[28] << 3) | (data[29] << 2) | (data[30] << 1) | data[31]
            checksum = (data[32] << 7) | (data[33] << 6) | (data[34] << 5) | (data[35] << 4) | (data[36] << 3) | (data[37] << 2) | (data[38] << 1) | data[39]

            # Validate checksum
            if (humidity_int + humidity_dec + temp_int + temp_dec) % 256 != checksum:
                raise ValueError("Checksum mismatch")

            # Convert to meaningful values
            humidity = humidity_int + humidity_dec / 10.0
            temperature = temp_int + temp_dec / 10.0
            if temp_int >= 128:
                temperature = -temperature + 0.5
            if humidity_int >= 128:
                humidity = -humidity + 0.5

            return temperature, humidity

        except (TimeoutError, ValueError, RuntimeError) as e:
            print(f"Attempt {attempt}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                print("Max retries reached. Waiting 5 seconds before next attempt.")
                time.sleep(5)
                return None, None

    return None, None

def main():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    try:
        while True:
            temp, hum = read_dht22()
            if temp is not None and hum is not None:
                print(f"Temperature: {temp:.1f}°C, Humidity: {hum:.1f}%")
            time.sleep(LOOP_DELAY)
    except KeyboardInterrupt:
        print("\nExiting...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

