import signal
import sys
import time
import logging
import requests
from requests.auth import HTTPBasicAuth
from gpiozero import InputDevice

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

SERVER_URL = 'http://localhost:5000/sensor'
USERNAME = 'user'
PASSWORD = 'pass'
SENSOR_PIN = 4
POLL_INTERVAL = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    logger.info('Received signal %s, shutting down...', signum)
    _running = False


def read_sensor(device):
    try:
        return int(device.value)
    except Exception as exc:
        logger.error('Failed to read GPIO%d: %s', SENSOR_PIN, exc)
        return None


def transmit_data(sensor_value):
    payload = {'sensor': 'Temperature', 'value': sensor_value}
    try:
        resp = requests.post(
            SERVER_URL,
            json=payload,
            auth=HTTPBasicAuth(USERNAME, PASSWORD),
            timeout=10
        )
        logger.info('Server response: %d %s', resp.status_code, resp.text)
    except requests.exceptions.Timeout:
        logger.error('Request timed out after 10 s.')
    except requests.exceptions.ConnectionError as exc:
        logger.error('Connection error: %s', exc)
    except requests.exceptions.HTTPError as exc:
        logger.error('HTTP error: %s', exc)
    except requests.exceptions.RequestException as exc:
        logger.error('Request failed: %s', exc)


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = InputDevice(SENSOR_PIN, pull_up=None)
    except Exception as exc:
        logger.error('Failed to initialize GPIO%d: %s', SENSOR_PIN, exc)
        sys.exit(1)

    logger.info('Monitoring GPIO%d every %d s. Press Ctrl+C to stop.', SENSOR_PIN, POLL_INTERVAL)

    try:
        while _running:
            value = read_sensor(sensor)
            if value is not None:
                logger.info('Sensor value: %d', value)
                transmit_data(value)
            else:
                logger.warning('Skipping transmission due to read error.')
            time.sleep(POLL_INTERVAL)
    finally:
        sensor.close()
        logger.info('GPIO cleanup completed.')


if __name__ == '__main__':
    main()

