import time
import board
import adafruit_dht

# Initialize the DHT11 sensor on GPIO4 (board.D4)
# Note: adafruit_dht.DHT11 uses the internal pull-up on the data pin by default
# and requires a 10k-20k pull-up resistor between data and 3V3.
sensor = None
try:
    sensor = adafruit_dht.DHT11(board.D4)
except Exception as e:
    print(f"Failed to initialize DHT11 sensor: {e}")
    exit(1)

try:
    while True:
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")
            else:
                print("Failed to retrieve data from DHT11 sensor.")
        except RuntimeError as e:
            # DHT sensors frequently throw RuntimeError on missed reads due to timing
            # issues. We print the error and continue the loop.
            print(f"RuntimeError reading DHT11 sensor: {e}")
        except Exception as e:
            # Catch any other unexpected errors during the read cycle
            print(f"Unexpected error reading DHT11 sensor: {e}")

        time.sleep(5)

except KeyboardInterrupt:
    print("\nProgram terminated by user.")
finally:
    # Clean up the sensor resources on all exit paths
    if sensor is not None:
        try:
            sensor.exit()
        except Exception:
            pass

