import time
import signal
import sys
import logging
from datetime import datetime

try:
    import board
    import adafruit_dht
    from gpiozero import OutputDevice
    _GPIOZERO_AVAILABLE = True
except Exception:
    _GPIOZERO_AVAILABLE = False

LOG_FILE = 'urban_data_log.txt'
DHT_PIN = board.D17
FAN_PIN = 18
TEMP_THRESHOLD = 30.0
HUM_THRESHOLD = 70.0
READ_INTERVAL = 2.0
NUM_READINGS = 5

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

_running = True
_fan = None
_sensor = None


def _signal_handler(signum, frame):
    global _running
    logger.info('Signal %s received, shutting down...', signum)
    _running = False


def _cleanup():
    global _fan, _sensor
    if _fan is not None:
        try:
            _fan.close()
        except Exception:
            pass
        _fan = None
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _init_sensor():
    if not _GPIOZERO_AVAILABLE:
        logger.warning('adafruit-circuitpython-dht / adafruit_blinka not installed; '
                       'sensor init skipped (non-hardware environment).')
        return None
    try:
        sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
        logger.info('DHT11 initialized on GPIO17.')
        return sensor
    except Exception as e:
        logger.warning('DHT11 init failed: %s', e)
        return None


def _init_fan():
    if not _GPIOZERO_AVAILABLE:
        logger.warning('gpiozero not installed; fan control skipped.')
        return None
    try:
        fan = OutputDevice(FAN_PIN, active_high=True, initial_value=False)
        logger.info('Fan initialized on GPIO18.')
        return fan
    except Exception as e:
        logger.warning('Fan init failed: %s', e)
        return None


def read_sensor(sensor):
    if sensor is None:
        return None, None
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            logger.error('Sensor returned None values.')
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        logger.error('Sensor read error: %s', e)
        return None, None
    except Exception as e:
        logger.error('Unexpected sensor error: %s', e)
        return None, None


def control_fan(fan, temperature, humidity):
    if fan is None:
        return
    try:
        if temperature is not None and temperature > TEMP_THRESHOLD:
            fan.on()
            logger.info('Fan ON: temperature %.1f°C exceeds %.1f°C threshold.',
                        temperature, TEMP_THRESHOLD)
        elif humidity is not None and humidity > HUM_THRESHOLD:
            fan.on()
            logger.info('Fan ON: humidity %.1f%% exceeds %.1f%% threshold.',
                        humidity, HUM_THRESHOLD)
        else:
            fan.off()
            logger.info('Fan OFF: conditions normal.')
    except Exception as e:
        logger.error('Fan control error: %s', e)


def log_data(timestamp, temperature, humidity, fan_state):
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f'{timestamp}, {temperature}, {humidity}, {fan_state}\n')
    except Exception as e:
        logger.error('Failed to write log: %s', e)


def main():
    global _running, _fan, _sensor

    signal.signal(signal.SIGINT, _signal_handler)
