import time
import signal
import sys
import logging
from datetime import datetime

try:
    import board
    import adafruit_dht
    from gpiozero import OutputDevice
    _GPIOZERO_AVAILABLE = True
except Exception:
    _GPIOZERO_AVAILABLE = False

