    (70.0, 100.0),
    (60.0, 85.0),
    (50.0, 70.0),
    (40.0, 50.0),
    (32.0, 25.0),
    (25.0, 15.0),
]


class FanController:
    def __init__(self, pin: int, pwm_freq: float):
        self.fan = PWMOutputDevice(pin, frequency=pwm_freq, initial_value=0.0)
        self._running = True

    def set_speed(self, speed_percent: float) -> None:
        clamped = max(0.0, min(100.0, speed_percent))
        self.fan.value = clamped / 100.0
        log.info("Fan speed set to %.1f%%", clamped)

    def get_cpu_temp(self):
        """Return CPU temperature in degrees Celsius, or None on failure."""
        try:
            out = (
                subprocess.run(
                    ["vcgencmd", "measure_temp"],
                    capture_output=True,
                    text=True,
                    timeout=5,
                )
                .stdout
                .strip()
            )
            return float(out.split("=")[1].split("'")[0])
        except (subprocess.CalledProcessError, IndexError, ValueError, TimeoutError):
            try:
                with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
                    return float(f.read().strip()) / 1000.0
            except (OSError, ValueError):
                return None

    def run(self) -> None:
        while self._running:
            temp = self.get_cpu_temp()
            if temp is None:
                log.warning("Temperature read failed; keeping current fan speed.")
            else:
                log.info("CPU temperature: %.1f°C", temp)
                speed = 0.0
                for threshold, percent in TEMP_THRESHOLDS:
                    if temp > threshold:
                        speed = percent
                self.set_speed(speed)
            time.sleep(CHECK_INTERVAL)

    def stop(self) -> None:
        self._running = False
        self.fan.value = 0.0
        self.fan.close()


