#!/usr/bin/env python3
"""
Raspberry Pi UPS Plus HAT Monitor

Reads power supply and battery data from the INA219 sensors (I2C bus 1, addresses
0x40 and 0x45) and status registers from the UPS Plus controller (address 0x17).
"""

import signal
import sys
import time
from smbus2 import SMBus, i2c_msg
from ina219 import INA219, DeviceRangeError

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
UPS_ADDR = 0x17
SUPPLY_ADDR = 0x40
BATTERY_ADDR = 0x45
SHUNT_SUPPLY = 0.00725   # Ω
SHUNT_BATTERY = 0.005    # Ω

# --- Globals for cleanup -----------------------------------------------------
_bus: SMBus | None = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _bus
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
        _bus = None


def _read_register(bus: SMBus, addr: int, reg: int, length: int = 1) -> bytes:
    """Read `length` bytes from a big-endian register field."""
    write_msg = i2c_msg.write(addr, [reg])
    read_msg = i2c_msg.read(addr, length)
    bus.i2c_rdwr(write_msg, read_msg)
    return bytes(read_msg)


def _write_register(bus: SMBus, addr: int, reg: int, value: int) -> None:
    """Write a single byte to a register."""
    write_msg = i2c_msg.write(addr, [reg, value & 0xFF])
    bus.i2c_rdwr(write_msg)


class INA219Sensor:
    """Thin wrapper around ina219.INA219 with error handling."""

    def __init__(self, bus_num: int, address: int, shunt_resistance: float):
        self.address = address
        self.shunt_resistance = shunt_resistance
        self.ina: INA219 | None = None
        try:
            self.ina = INA219(shunt_resistance, busnum=bus_num, address=address)
            self.ina.configure()
        except Exception as exc:
            print(f"[ERROR] INA219 at 0x{address:02X} on bus {bus_num}: {exc}", file=sys.stderr)
            self.ina = None

    def read(self):
        if self.ina is None:
            return None
        try:
            return self.ina.get_shunt_voltage(), self.ina.get_bus_voltage(), self.ina.get_current(), self.ina.get_power()
        except DeviceRangeError:
            print(f"[WARN] INA219 at 0x{self.address:02X}: current out of range", file=sys.stderr)
            return None
        except Exception as exc:
            print(f"[ERROR] INA219 at 0x{self.address:02X}: {exc}", file=sys.stderr)
            return None

    def close(self):
        if self.ina is not None:
            try:
                self.ina.close()
            except Exception:
                pass
            self.ina = None


class UPSPlus:
    """Driver for the UPS Plus HAT status registers."""

    _REGISTERS = {
        "processor_voltage": 0x01,
        "rpi_voltage":       0x03,
        "battery_port_voltage": 0x05,
        "typec_charging_port_voltage": 0x07,
        "micro_usb_charging_port_voltage": 0x09,
        "battery_temperature": 0x0B,
        "full_battery_voltage": 0x0D,
        "empty_battery_voltage": 0x0F,
        "battery_protection_voltage": 0x11,
        "remaining_capacity_percent": 0x13,
        "sampling_period_minutes": 0x15,
        "power_state": 0x17,
        "shutdown_countdown_seconds": 0x18,
        "auto_power_on": 0x19,
        "restart_countdown_seconds": 0x1A,
    }

    def __init__(self, bus_num: int, address: int):
        self.address = address
        self.bus_num = bus_num
        self._closed = False
        try:
            self.bus = SMBus(bus_num)
        except Exception as exc:
            print(f"[ERROR] Cannot open I2C bus {bus_num}: {exc}", file=sys.stderr)
            self.bus = None
            return
        for reg in self._REGISTERS.values():
            try:
                _read_register(self.bus, address, reg, 1)
            except Exception as exc:
                print(f"[ERROR] UPS Plus at 0x{address:02X} register 0x{reg:02X}: {exc}", file=sys.stderr)
                self.close()
                return

    def read_all(self) -> dict:
        if self.bus is None:
            return {}
        data: dict[str, int] = {}
        for name, reg in self._REGISTERS.items():
            try:
                raw = _read_register(self.bus, self.address, reg, 2)
                if len(raw) < 2:
                    data[name] = 0
                    continue
                data[name] = (raw[0] << 8) | raw[1]
            except Exception as exc:
                print(f"[ERROR] UPS Plus at 0x{self.address:02X} register 0x{reg:02X}: {exc}", file=sys.stderr)
                data[name] = 0
        return data

    def close(self):
        if self._closed:
            return
        self._closed = True
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None


def main():
    global _bus

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    supply = INA219Sensor(I2C_BUS, SUPPLY_ADDR, SHUNT_SUPPLY)
    battery = INA219Sensor(I2C_BUS, BATTERY_ADDR, SHUNT_BATTERY)
    ups = UPSPlus(I2C_BUS, UPS_ADDR)

    try:
        while _running:
            # INA219 sensors
            if supply.ina is not None:
                sv, bv, c, p = supply.read()
                if sv is not None:
                    print(f"Power Supply Voltage: {bv:.3f} V")
                    print(f"Power Supply Current: {c:.3f} mA")
                    print(f"Power Supply Power: {p:.3f} mW")
            else:
                print("Power Supply Sensor: unavailable")

            if battery.ina is not None:
                bv, bv, c, p = battery.read()
                if bv is not None:
                    print(f"Battery Voltage: {bv:.3f} V")
                    print(f"Battery Current: {c:.3f} mA")
                    print(f"Battery Power: {p:.3f} mW")
            else:
                print("Battery Sensor: unavailable")

            # UPS Plus status
            if ups.bus is not None:
                status = ups.read_all()
                print("\nUPS Plus Status:")
                for name, reg in ups._REGISTERS.items():
                    val = status.get(name, 0)
                    print(f"  {name.replace('_', ' ').title()}: {val}")
            else:
                print("UPS Plus: unavailable")

            time.sleep(1.0)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

