import subprocess
import time
import logging
import signal
import sys

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    logging.basicConfig(level=logging.INFO)
    logging.getLogger(__name__).warning("gpiozero not installed; running in degraded mode.")
    PWMOutputDevice = None
    GPIOZeroError = Exception

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

FAN_PIN = 14
PWM_FREQ = 100
POLL_INTERVAL = 5
TEMP_THRESHOLDS = [
    (70, 100),
    (60, 85),
    (50, 70),
    (40, 50),
    (32, 25),
    (25, 15),
]

fan = None
running = True


def get_cpu_temperature():
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        temp_str = result.stdout.strip()
        return float(temp_str.split('=')[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, IndexError, ValueError) as e:
        logger.error(f"Failed to get CPU temperature: {e}")
        return None


def set_fan_speed(duty_cycle):
    if fan is not None:
        try:
            fan.value = duty_cycle / 100.0
            logger.info(f"Fan speed set to {duty_cycle}%")
        except GPIOZeroError as e:
            logger.error(f"Failed to set fan speed: {e}")


def cleanup(signum=None, frame=None):
    global running
    running = False
    if fan is not None:
        try:
            fan.value = 0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        logger.info(f"Received signal {signum}, exiting.")
        sys.exit(0)


def main():
    global fan
    if PWMOutputDevice is None:
        logger.warning("PWMOutputDevice unavailable; running in degraded mode.")
        fan = None
    else:
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
            logger.info(f"PWM initialized on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
        except GPIOZeroError as e:
            logger.warning(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}. Running in degraded mode.")
            fan = None

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    last_speed = 0

    while running:
        temp = get_cpu_temperature()
        if temp is not None:
            for threshold, speed in TEMP_THRESHOLDS:
                if temp > threshold:
                    last_speed = speed
                    set_fan_speed(speed)
                    break
            else:
                last_speed = 0
                set_fan_speed(0)
        else:
            logger.warning(f"Temperature read failed; keeping last speed ({last_speed}%).")

        for _ in range(POLL_INTERVAL):
            if not running:
                break
            time.sleep(1)

    cleanup()


if __name__ == "__main__":
    main()

