#!/usr/bin/env python3
"""
Raspberry Pi Model 1 (I2C bus 0) — MCP23017 I2C GPIO expander.

Wiring:
  MCP23017 SDA -> GPIO2 (pin 3)
  MCP23017 SCL -> GPIO3 (pin 5)
  MCP23017 VDD -> 3.3 V
  MCP23017 VSS -> GND
  MCP23017 A0/A1/A2 -> GND  (I2C address 0x20)
  LED anode -> MCP23017 GPA0 (pin 12) via 330 Ω resistor
  LED cathode -> GND
  Switch between MCP23017 GPB7 (pin 11) and GND with internal pull-up enabled

Requires: smbus2 (pip install smbus2)
"""

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_BUS = 0
MCP23017_ADDR = 0x20

# MCP23017 register addresses
IODIRA = 0x00
IODIRB = 0x01
GPPUA = 0x0C
GPPUB = 0x0D
GPIOA = 0x12
GPIOB = 0x13
OLATA = 0x14
OLATB = 0x15

# Pin masks
LED_PIN = 0x01          # GPA0
