import RPi.GPIO as GPIO
import threading
import time
import signal
import sys

# Constants
SERVER_PORT = 12345
RECEIVE_INTERVAL = 0.1  # seconds

# Global variables
server_active = False
receive_thread = None
log_file = None
log_file_path = None
running = True

# DOG (Data Over GPIO) class
class DOG:
    def __init__(self, port):
        self.port = port

    def send(self, data):
        try:
            # In a real implementation, this would write data to the GPIO pin
            # For this example, we just print it
            print(f"Sending data: {data} on port {self.port}")
        except Exception as e:
            print(f"Error sending data: {e}")

    def receive(self):
        try:
            # In a real implementation, this would read data from the GPIO pin
            # For this example, we simulate receiving data
            time.sleep(RECEIVE_INTERVAL)
            return "Simulated data"
        except Exception as e:
            print(f"Error receiving data: {e}")
            return None

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global running
    print("\nShutdown signal received. Cleaning up...")
    running = False
    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=2.0)
    GPIO.cleanup()
    sys.exit(0)

# Help function
def help(command=None):
    commands = {
        "start": "Starts the server. Usage: start <filename>",
        "stop": "Stops the server. Usage: stop",
        "help": "Displays help. Usage: help [command]",
        "display": "Displays the log file. Usage: display",
        "send": "Sends data. Usage: send <data>",
        "write": "Writes data directly to the log file. Usage: write <data>",
        "exit": "Exits the server. Usage: exit",
    }
    if command:
        if command in commands:
            print(commands[command])
        else:
            print("Unknown command.")
    else:
        print("Available commands:")
        for cmd in commands:
            print(f"  {cmd}: {commands[cmd]}")

# Start the server
def start(filename):
    global server_active, receive_thread, log_file, log_file_path
    if server_active:
        print("Server is already running.")
        return
    try:
        log_file_path = filename
        log_file = open(filename, "w")
        server_active = True
        receive_thread = threading.Thread(target=receive_data, daemon=True)
        receive_thread.start()
        print(f"Server started. Logging to {filename}")
    except Exception as e:
        print(f"Error starting server: {e}")
        server_active = False

# Stop the server
def stop():
    global server_active, receive_thread
    if not server_active:
        print("Server is not running.")
        return
    server_active = False
    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=2.0)
    if log_file:
        log_file.close()
        log_file = None
        print("Server stopped and log file closed.")
    else:
        print("Server stopped.")

# Receive data and log it
def receive_data():
    global server_active, log_file
    while server_active:
        try:
            data = DOG(SERVER_PORT).receive()
            if data:
                if log_file:
                    log_file.write(data + "\n")
                    log_file.flush()
                print(f"Received: {data}")
        except Exception as e:
            print(f"Error receiving data: {e}")
        time.sleep(RECEIVE_INTERVAL)

# Display the log file
def display():
    global log_file
    if not log_file:
        print("No log file is open.")
        return
    try:
        with open(log_file_path, "r") as f:
            print(f.read())
    except Exception as e:
        print(f"Error displaying log file: {e}")

# Send data
def send(data):
    if not server_active:
        print("Server is not running.")
        return
    try:
        DOG(SERVER_PORT).send(data)
    except Exception as e:
        print(f"Error sending data: {e}")

# Write data directly to the log file
def write(data):
    global log_file
    if not log_file:
        print("No log file is open.")
        return
    try:
        log_file.write(data + "\n")
        log_file.flush()
        print(f"Wrote: {data}")
    except Exception as e:
        print(f"Error writing to log file: {e}")

# Main function
def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    while running:
        try:
            command = input("Enter command: ").strip().lower()
            if not command:
                continue
            parts = command.split()
            if parts[0] == "start":
                if len(parts) < 2:
                    print("Usage: start <filename>")
                    continue
                start(parts[1])
            elif parts[0] == "stop":
                stop()
            elif parts[0] == "help":
                if len(parts) > 1:
                    help(parts[1])
                else:
                    help()
            elif parts[0] == "display":
                display()
            elif parts[0] == "send":
                if len(parts) < 2:
                    print("Usage: send <data>")
                    continue
                send(" ".join(parts[1:]))
            elif parts[0] == "write":
                if len(parts) < 2:
                    print("Usage: write <data>")
                    continue
                write(" ".join(parts[1:]))
            elif parts[0] == "exit":
                stop()
                GPIO.cleanup()
                print("Exiting.")
                running = False
            else:
                print("Unknown command.")
        except EOFError:
            print("\nEOF received. Exiting.")
            running = False
        except Exception as e:
            print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

