    """Initialize GPIO with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VOLTAGE_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def check_voltage():
    """Read voltage status and send alert if failure detected."""
    try:
        voltage_level = GPIO.input(VOLTAGE_PIN)
        if voltage_level == GPIO.LOW:
            print("Power failure detected!")
            send_alert()
        else:
            print("Power OK")
    except Exception as e:
        print(f"Error reading GPIO: {e}", file=sys.stderr)

def send_alert():
    """Send HTTP POST alert with error handling."""
    try:
        response = requests.post(
            ALERT_ENDPOINT,
            json={'alert': 'Power failure detected'},
            timeout=ALERT_TIMEOUT
        )
        response.raise_for_status()
        print("Alert sent successfully.")
    except requests.exceptions.RequestException as e:
        print(f"Error sending alert: {e}", file=sys.stderr)

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup error: {e}", file=sys.stderr)

def main():
    setup_gpio()
    try:
        while True:
            check_voltage()
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

