import time
import signal
import sys
import logging
from gpiozero import PWMLED
import board
import busio
import adafruit_tsl2561

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

LED_PIN = 18
PWM_FREQUENCY = 1000
SAMPLE_INTERVAL = 1.0

running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        logger.error(f"Failed to initialize I2C bus: {e}")
        return None

def initialize_sensor(i2c):
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c)
        return sensor
    except ValueError as e:
        logger.error(f"TSL2561 not found on I2C bus: {e}")
        return None
    except Exception as e:
        logger.error(f"Failed to initialize TSL2561 sensor: {e}")
        return None

def initialize_led(pin):
    try:
        led = PWMLED(pin, frequency=PWM_FREQUENCY)
        led.value = 0.0
        return led
    except Exception as e:
        logger.error(f"Failed to initialize LED on GPIO {pin}: {e}")
        return None

def read_lux(sensor):
    try:
        lux = sensor.lux
        if lux is None:
            raise RuntimeError("Sensor returned None for lux")
        return lux
    except Exception as e:
        logger.error(f"Error reading lux from sensor: {e}")
        return None

def map_lux_to_brightness(lux):
    if lux is None:
        return None
    return max(0.0, min(100.0, lux / 1000.0))

def set_led_brightness(led, brightness):
    if led is None:
        return
    try:
        led.value = brightness / 100.0
    except Exception as e:
        logger.error(f"Error setting LED brightness: {e}")

def cleanup(led, sensor, i2c):
    logger.info("Cleaning up resources...")
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if sensor is not None:
        try:
            sensor.deinit()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
    logger.info("Cleanup complete.")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c = initialize_i2c()
    if i2c is None:
        sys.exit(1)

    sensor = initialize_sensor(i2c)
    if sensor is None:
        cleanup(None, None, i2c)
        sys.exit(1)

    led = initialize_led(LED_PIN)
    if led is None:
        cleanup(sensor, None, i2c)
        sys.exit(1)

    brightness = 0.0
    try:
        while running:
            lux = read_lux(sensor)
            if lux is not None:
                brightness = map_lux_to_brightness(lux)
                set_led_brightness(led, brightness)
                logger.info(f"Lux: {lux:.2f}, Brightness: {brightness:.2f}%")
            else:
                logger.warning("Skipping brightness update due to sensor read error.")
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup(led, sensor, i2c)

if __name__ == "__main__":
    main()

