#!/usr/bin/env python3
"""
Line-following robot using two TCRT5000 IR sensors on a Raspberry Pi.
Reads left (GPIO 5) and right (GPIO 6) sensors every 0.5 s for 10 samples.
Decides steering direction from sensor states (0 = black line, 1 = white surface).
"""

import RPi.GPIO as GPIO
import time
import sys

# GPIO pin assignments (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Timing constants
SAMPLE_INTERVAL = 0.5  # seconds between readings
NUM_SAMPLES = 10

def setup_gpio():
    """Initialize GPIO mode and set sensor pins as inputs with pull-down resistors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def read_sensor(pin):
    """Read a TCRT5000 sensor and return 0 (black line) or 1 (white surface)."""
    try:
        value = GPIO.input(pin)
        if value == GPIO.HIGH:
            return 1  # white surface
        else:
            return 0  # black line
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}", file=sys.stderr)
        return -1  # indicate read failure

def decide_steering(left_state, right_state):
    """
    Decide steering direction based on sensor states.
    Returns one of: 'forward', 'turn-left', 'turn-right', 'search'.
    """
    if left_state == -1 or right_state == -1:
        return "search"  # avoid driving when sensor read fails
    if left_state == 0 and right_state == 0:
        return "forward"
    if left_state == 1 and right_state == 0:
        return "turn-left"
    if left_state == 0 and right_state == 1:
        return "turn-right"
    return "search"

def cleanup_gpio():
    """Safely clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup warning: {e}", file=sys.stderr)

def main():
    setup_gpio()
    try:
        for sample_index in range(NUM_SAMPLES):
            left_state = read_sensor(LEFT_SENSOR_PIN)
            right_state = read_sensor(RIGHT_SENSOR_PIN)
            steering = decide_steering(left_state, right_state)
            print(f"Sample {sample_index+1}: left={left_state}, right={right_state} -> steering={steering}")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nLine-following interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

