import signal
import sys
from flask import Flask, render_template_string
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)

LED_PIN = 17
led = None

INDEX_HTML = """
<!DOCTYPE html>
<html>
<head><title>LED Control</title></head>
<body>
  <h1>LED Control</h1>
  <a href="/light_on">Turn LED ON</a> |
  <a href="/light_off">Turn LED OFF</a>
</body>
</html>
"""

STATUS_HTML = """
<!DOCTYPE html>
<html>
<head><title>LED Status</title></head>
<body>
  <h1>LED Status</h1>
  <p>LED is now <strong>{{ state }}</strong></p>
  <a href="/">Back</a>
</body>
</html>
"""

def init_led():
    """Initialize the LED on GPIO 17; return the LED object or None on failure."""
    try:
        return LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"Error initializing LED on GPIO {LED_PIN}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error initializing LED: {e}", file=sys.stderr)
        return None

def cleanup(signum=None, frame=None):
    """Release the LED resource and exit."""
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        sys.exit(0)

@app.route('/')
def index():
    return render_template_string(INDEX_HTML)

@app.route('/light_on')
def light_on():
    if led is None:
        return render_template_string("<h1>Error: LED not initialized</h1>"), 500
    try:
        led.on()
        return render_template_string(STATUS_HTML, state="ON")
    except Exception as e:
        return render_template_string(f"<h1>Error turning LED on: {e}</h1>"), 500

@app.route('/light_off')
def light_off():
    if led is None:
        return render_template_string("<h1>Error: LED not initialized</h1>"), 500
    try:
        led.off()
        return render_template_string(STATUS_HTML, state="OFF")
    except Exception as e:
        return render_template_string(f"<h1>Error turning LED off: {e}</h1>"), 500

if __name__ == '__main__':
    led = init_led()
    if led is None:
        print("LED initialization failed; exiting.", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        app.run(host='0.0.0.0', port=8080, debug=False)
    finally:
        cleanup()

