import signal
import sys
import time
import logging
from gpiozero import DigitalOutputDevice, DigitalInputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1.0

START_SIGNAL = '101'
END_SIGNAL = '111'
DEFAULT_DELAY = 0.0005
DEFAULT_TIMEOUT = 1.0

_running = True

def signal_handler(signum, frame):
    global _running
    _running = False
    logging.info(f"Signal {signum} received, shutting down...")

def initialize_gpio():
    try:
        data_out = DigitalOutputDevice(DATA_OUT_PIN)
        timer_out = DigitalOutputDevice(TIMER_OUT_PIN)
        data_in = DigitalInputDevice(DATA_IN_PIN)
        timer_in = DigitalInputDevice(TIMER_IN_PIN)
        logging.info("GPIO initialized successfully.")
        return data_out, timer_out, data_in, timer_in
    except GPIOZeroError as e:
        logging.error(f"GPIO initialization failed: {e}")
        return None, None, None, None

def cleanup_gpio(data_out, timer_out, data_in, timer_in):
    for dev in [data_out, timer_out, data_in, timer_in]:
        if dev is not None:
            try:
                dev.close()
            except DeviceClosed:
                pass
            except Exception as e:
                logging.warning(f"Error closing device: {e}")
    logging.info("GPIO cleanup complete.")

def string_to_bits(string):
    try:
        binary_string = ''.join(format(ord(char), '08b') for char in string)
        return binary_string
    except Exception as e:
        logging.error(f"Error converting string to bits: {e}")
        return None

def bits_to_string(bits):
    try:
        binary_string = ''.join(format(ord(char), '08b') for char in bits)
        return binary_string
    except Exception as e:
        logging.error(f"Error converting bits to string: {e}")
        return None

def send_data(data_out, timer_out, data, delay=DEFAULT_DELAY):
    try:
        binary_string = string_to_bits(data)
        if binary_string is None:
            return False

        for bit in binary_string:
            if not _running:
                logging.info("Transmission interrupted by signal.")
                return False

            timer_out.on()
            data_out.on() if bit == '1' else data_out.off()
            time.sleep(delay)
            timer_out.off()
            time.sleep(delay)

        timer_out.on()
        data_out.on()  # Send end signal
        time.sleep(delay)
        timer_out.off()
        return True

    except Exception as e:
        logging.error(f"Error sending data: {e}")
        return False

def receive_data(data_in, timer_in, timeout=DEFAULT_TIMEOUT):
    try:
        start_time = time.time()
        start_signal_received = False
        end_signal_received = False
        received_bits = []

        while _running:
            if time.time() - start_time > timeout:
                logging.warning("Reception timed out.")
                return None

            if timer_in.is_active:
                if data_in.is_active:
                    received_bits.append('1')
                else:
                    received_bits.append('0')

                if ''.join(received_bits) == START_SIGNAL:
                    start_signal_received = True
                elif ''.join(received_bits) == END_SIGNAL:
                    end_signal_received = True

                if start_signal_received and end_signal_received:
                    break

                if len(received_bits) > 100:
                    received_bits = []

            time.sleep(0.0001)

        if not start_signal_received or not end_signal_received:
            logging.warning("Start or end signal not received.")
            return None

        return ''.join(received_bits)

    except Exception as e:
        logging.error(f"Error receiving data: {e}")
        return None

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    data_out, timer_out, data_in, timer_in = initialize_gpio()
    if data_out is None:
        sys.exit(1)

    try:
        if send_data(data_out, timer_out, 'Hello, GPIO!'):
            logging.info("Data sent successfully.")
        else:
            logging.error("Data sending failed.")

        received_data = receive_data(data_in, timer_in)
        if received_data:
            logging.info(f"Received data: {bits_to_string(received_data)}")
        else:
            logging.error("Data reception failed.")

    finally:
        cleanup_gpio(data_out, timer_out, data_in, timer_in)

if __name__ == "__main__":
    main()

