# fingerprint_access_control.py
# Raspberry Pi 5 - Fingerprint Access Control System
# Uses Adafruit Fingerprint sensor over I2C (address 0x26)

import time
import board
import busio
import adafruit_fingerprint

# I2C address of the fingerprint sensor
FINGERPRINT_ADDRESS = 0x26

# Global I2C bus object
i2c_bus = None


def initialize_i2c():
    """Initialize the I2C bus on board.SCL and board.SDA."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to confirm the sensor is present
        while not i2c_bus.try_lock():
            pass
        try:
            devices = i2c_bus.scan()
        finally:
            i2c_bus.unlock()
        if FINGERPRINT_ADDRESS not in devices:
            print(f"Error: Fingerprint sensor not found at I2C address 0x{FINGERPRINT_ADDRESS:02X}.")
            i2c_bus = None
            return False
        return True
    except ValueError as e:
        print(f"Error: I2C bus initialization failed (bus locked): {e}")
        i2c_bus = None
        return False
    except Exception as e:
        print(f"Error: I2C bus initialization failed: {e}")
        i2c_bus = None
        return False


def initialize_fingerprint_sensor():
    """Initialize the Adafruit Fingerprint sensor."""
    if i2c_bus is None:
        print("Error: I2C bus not initialized.")
        return None
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return sensor
    except Exception as e:
        print(f"Error: Failed to initialize fingerprint sensor: {e}")
        return None


def get_fingerprint_image(sensor):
    """Acquire a fingerprint image from the sensor."""
    try:
        while True:
            ret = sensor.get_image()
            if ret == adafruit_fingerprint.OK:
                return True
            elif ret == adafruit_fingerprint.NOFINGER:
                time.sleep(0.1)
                continue
            else:
                print(f"Error: Failed to get fingerprint image (error code: {ret})")
                return False
    except Exception as e:
        print(f"Error: Unexpected error during fingerprint image acquisition: {e}")
        return False


def image_to_fingerprint_template(sensor):
    """Convert the acquired fingerprint image to a template."""
    try:
        if sensor.image_2_tz(1) != adafruit_fingerprint.OK:
            print("Error: Failed to convert fingerprint image to template.")
            return False
        return True
    except Exception as e:
        print(f"Error: Failed to convert fingerprint image to template: {e}")
        return False


def search_fingerprint_database(sensor):
    """Search the fingerprint database for a match."""
    try:
        if sensor.finger_search() != adafruit_fingerprint.OK:
            return None
        return sensor.finger_id, sensor.confidence
    except Exception as e:
        print(f"Error: Failed to search fingerprint database: {e}")
        return None


def authenticate_user(sensor):
    """Authenticate a user by scanning their fingerprint."""
    if not get_fingerprint_image(sensor):
        return None

    if not image_to_fingerprint_template(sensor):
        return None

    result = search_fingerprint_database(sensor)
    if result is None:
        return None

    return result


def main():
    """Main function to run the fingerprint authentication system."""
    global i2c_bus

    if not initialize_i2c():
        return

    sensor = initialize_fingerprint_sensor()
    if sensor is None:
        return

    try:
        while True:
            print("Waiting for fingerprint...")
            result = authenticate_user(sensor)

            if result is not None:
                user_id, confidence = result
                print(f"Access Granted. User ID: {user_id}, Confidence: {confidence}")
            else:
                print("Access Denied.")

            time.sleep(1)

    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        if i2c_bus is not None:
            try:
                i2c_bus.deinit()
            except Exception:
                pass
        print("Program finished.")


if __name__ == "__main__":
    main()

