import time

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQUENCY = 25000  # 25 kHz – standard for 4-wire PWM fans

fan = None
running = True


def cleanup(signum=None, frame=None):
    """Stop PWM and release resources on exit."""
    global fan, running
    running = False
    if fan is not None:
        try:
            fan.value = 0  # 0% duty cycle
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global fan

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize PWM output device; fall back to software PWM if hardware is unavailable
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except GPIOZeroError as e:
        print(f"Error: Failed to initialize PWM on GPIO{FAN_PIN}: {e}")
        print("Hint: Ensure this script is running on a Raspberry Pi with GPIO hardware.")
        sys.exit(1)
    except Exception as e:
        print(f"Error: Unexpected failure during GPIO initialization: {e}")
        sys.exit(1)

    print(f"PWM fan control started on GPIO{FAN_PIN} at {PWM_FREQUENCY} Hz.")
    print("Enter a speed between 0 and 100 (q to quit).")

    while running:
        try:
            user_input = input("Enter fan speed (0-100): ").strip()
            if not user_input:
                continue

            fan_speed = float(user_input)

            if 0 <= fan_speed <= 100:
                fan.value = fan_speed / 100.0
                print(f"Fan speed set to: {fan_speed:.1f}%")
            else:
                print("Invalid input. Please enter a value between 0 and 100.")

        except ValueError:
            print("Invalid input. Please enter a number.")
        except EOFError:
            print("\nEOF received. Exiting...")
            break
        except KeyboardInterrupt:
            break
        except Exception as e:
            print(f"An unexpected error occurred: {e}")
            break

    cleanup()


if __name__ == "__main__":
    main()

