import http.server
import socketserver
import signal
import sys
from gpiozero import LED

# Configuration
PORT = 8080
LED_PIN = 18  # BCM numbering

# Global resources for signal handler
led = None
httpd = None


class LEDRequestHandler(http.server.BaseHTTPRequestHandler):
    """HTTP request handler for LED control."""

    def do_GET(self):
        """Handle GET requests."""
        if self.path == '/led/on':
            led.on()
            self._respond(200, 'LED is ON')
        elif self.path == '/led/off':
            led.off()
            self._respond(200, 'LED is OFF')
        else:
            self._respond(404, 'Not Found')

    def _respond(self, status_code, message):
        """Send a plain-text HTTP response."""
        body = message.encode('utf-8')
        self.send_response(status_code)
        self.send_header('Content-Type', 'text/plain; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, fmt, *args):
        """Suppress default stderr logging for cleaner output."""
        pass


def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    global httpd, led
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global led, httpd

    # Initialize LED
    try:
        led = LED(LED_PIN)
    except Exception as e:
        print(f'Failed to initialize LED on GPIO{LED_PIN}: {e}', file=sys.stderr)
        sys.exit(1)

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Create HTTP server
    try:
        httpd = socketserver.TCPServer(('0.0.0.0', PORT), LEDRequestHandler)
    except OSError as e:
        print(f'Failed to bind to port {PORT}: {e}', file=sys.stderr)
        cleanup()
        sys.exit(1)

    print(f'Server running on port {PORT}...')
    try:
        httpd.serve_forever()
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
    finally:
        cleanup()


if __name__ == '__main__':
    main()

