import time

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 library not installed. Install with: pip install smbus2")
    sys.exit(1)

# BH1750 constants
BH1750_ADDR = 0x23
POWER_ON = 0x01
CONTINUOUS_HIGH_RES_MODE = 0x10
MEASUREMENT_DELAY_S = 0.12  # max conversion time for high-res mode

running = True
bus = None


def signal_handler(sig, frame):
    global running
    running = False


def init_sensor(bus_obj):
    """Initialize the BH1750 sensor: power on and set high-res mode."""
    try:
        bus_obj.write_byte(BH1750_ADDR, POWER_ON)
        time.sleep(0.01)
        bus_obj.write_byte(BH1750_ADDR, CONTINUOUS_HIGH_RES_MODE)
        time.sleep(0.18)  # allow first measurement to complete
    except OSError as e:
        raise RuntimeError(f"Failed to initialize BH1750 at 0x{BH1750_ADDR:02X}: {e}")


def read_lux(bus_obj):
    """Read a 2-byte measurement and convert to lux (1.2 lx/count)."""
    try:
        data = bus_obj.read_i2c_block_data(BH1750_ADDR, CONTINUOUS_HIGH_RES_MODE, 2)
        raw = (data[0] << 8) | data[1]
        return raw / 1.2
