import time
import signal
import sys
import board
import busio
import adafruit_tsl2561
from gpiozero import PWMOutputDevice

# Constants
I2C_ADDRESS = 0x39
LED_GPIO_PIN = 18
PWM_FREQUENCY = 1000
READ_INTERVAL_SECONDS = 1
MAX_RETRIES = 3
RETRY_DELAY_SECONDS = 0.5

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def initialize_i2c():
    """Initialize the I2C bus using board.SCL and board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor with retries."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=I2C_ADDRESS)
            # Force a read to verify the sensor is responding
            _ = sensor.lux
            return sensor
        except Exception as e:
            print(f"Error initializing TSL2561 (attempt {attempt}/{MAX_RETRIES}): {e}", file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY_SECONDS)
    return None

def initialize_led(pin):
    """Initialize the LED PWM output using gpiozero."""
    try:
        led = PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0)
        return led
    except Exception as e:
        print(f"Error initializing LED on GPIO{pin}: {e}", file=sys.stderr)
        return None

def read_light_level(sensor):
    """Read the ambient light level in lux from the sensor."""
    try:
        lux = sensor.lux
        if lux is None:
            print("Warning: Sensor returned None for lux reading.", file=sys.stderr)
            return None
        return lux
    except Exception as e:
        print(f"Error reading light level: {e}", file=sys.stderr)
        return None

def calculate_brightness(lux):
    """Map lux to a 0-100 brightness percentage."""
    if lux is None:
        return None
    return max(0, min(100, int(lux / 10)))

def set_led_brightness(led, brightness):
    """Set the LED brightness using PWM duty cycle (0.0 to 1.0)."""
    if led is None or brightness is None:
        return
    try:
        led.value = brightness / 100.0
    except Exception as e:
        print(f"Error setting LED brightness: {e}", file=sys.stderr)

def cleanup(led, sensor, i2c_bus):
    """Release resources cleanly."""
    print("\nCleaning up resources...")
    if led is not None:
        try:
            led.value = 0
            led.close()
        except Exception:
            pass
    if sensor is not None:
        try:
            sensor.deinit()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
    print("Cleanup complete.")

def main():
    """Main function to read light level and adjust LED brightness."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    sensor = initialize_light_sensor(i2c_bus)
    if sensor is None:
        cleanup(None, None, i2c_bus)
        sys.exit(1)

    led = initialize_led(LED_GPIO_PIN)
    if led is None:
        cleanup(sensor, None, i2c_bus)
        sys.exit(1)

    try:
        while _running:
            lux = read_light_level(sensor)
            brightness = calculate_brightness(lux)

            if brightness is not None:
                set_led_brightness(led, brightness)
                print(f"Ambient Light: {lux:.2f} lux, LED Brightness: {brightness}%")
            else:
                print("Failed to read light level.")

            # Sleep in small increments to allow prompt signal handling
            for _ in range(READ_INTERVAL_SECONDS):
                if not _running:
                    break
                time.sleep(1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup(led, sensor, i2c_bus)

if __name__ == "__main__":
    main()

