import time
import atexit
import logging
import signal
import sys
from typing import Dict, Any

try:
    from adafruit_pca9685 import PCA9685
    from adafruit_extended_bus import ExtendedI2C as I2C
except ImportError:
    logging.error("Required libraries not found. Install with: pip install adafruit-circuitpython-pca9685 adafruit-circuitpython-busdevice")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

SERVO_MIN_PULSE = 150
SERVO_MAX_PULSE = 600
DEFAULT_FREQUENCY = 60
SERVO_ANGLE_RANGE = 77
PCA9685_ADDRESS = 0x40

class Fuchikoma:
    def __init__(self, i2c_address: int = PCA9685_ADDRESS):
        self.pwm: PCA9685 | None = None
        self.servo_config: Dict[str, Dict[str, Any]] = {
            'claw': {'channel': 0, 'min_pulse': SERVO_MIN_PULSE, 'max_pulse': SERVO_MAX_PULSE, 'angle_range': SERVO_ANGLE_RANGE},
            'lock': {'channel': 1, 'min_pulse': SERVO_MIN_PULSE, 'max_pulse': SERVO_MAX_PULSE, 'angle_range': SERVO_ANGLE_RANGE},
            'water_gun': {'channel': 2, 'min_pulse': SERVO_MIN_PULSE, 'max_pulse': SERVO_MAX_PULSE, 'angle_range': SERVO_ANGLE_RANGE}
        }
        self._initialize_pca9685(i2c_address)

    def _initialize_pca9685(self, i2c_address: int) -> None:
        try:
            self.i2c = I2C()
            self.pwm = PCA9685(self.i2c, address=i2c_address)
            self.pwm.frequency = DEFAULT_FREQUENCY
            logging.info(f"PCA9685 initialized at address 0x{i2c_address:02X} with {DEFAULT_FREQUENCY} Hz.")
            atexit.register(self.cleanup)
        except (ValueError, OSError) as e:
            logging.error(f"Failed to initialize PCA9685 at address 0x{i2c_address:02X}: {e}")
            self.pwm = None
            raise

    def _validate_servo(self, servo_name: str) -> None:
        if servo_name not in self.servo_config:
            raise ValueError(f"Invalid servo name: {servo_name}. Valid names: {list(self.servo_config.keys())}")

    def _calculate_pulse(self, angle: float) -> int:
        zero_pulse = (self.servo_config[servo_name]['min_pulse'] + self.servo_config[servo_name]['max_pulse']) / 2
        pulse_width = zero_pulse + (angle / self.servo_config[servo_name]['angle_range']) * (self.servo_config[servo_name]['max_pulse'] - zero_pulse)
        return int(pulse_width)

    def move_servo(self, servo_name: str, angle: float, delay: float = 0.029) -> None:
        if self.pwm is None:
            raise RuntimeError("PCA9685 not initialized.")
        self._validate_servo(servo_name)
        servo_config = self.servo_config[servo_name]
        pulse = self._calculate_pulse(angle)
        channel = servo_config['channel']
        try:
            self.pwm.channels[channel].duty_cycle = pulse
            time.sleep(delay)
            self.pwm.channels[channel].duty_cycle = 0
        except Exception as e:
            logging.error(f"Error moving servo {servo_name} to angle {angle}: {e}")
            raise

    def bite(self) -> None:
        self.move_servo('claw', -75)

    def open_claw(self) -> None:
        self.move_servo('claw', 75)

    def lock(self) -> None:
        self.move_servo('lock', 75)

    def unlock(self) -> None:
        self.move_servo('lock', -75)

    def shoot(self) -> None:
        self.move_servo('water_gun', -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self) -> None:
        self.move_servo('water_gun', 75)

    def cleanup(self) -> None:
        if self.pwm is not None:
            try:
                for channel in range(16):
                    self.pwm.channels[channel].duty_cycle = 0
                logging.info("PCA9685 channels deinitialized.")
            except Exception as e:
                logging.error(f"Error during cleanup: {e}")
            finally:
                self.pwm = None
                try:
                    self.i2c.deinit()
                except Exception:
                    pass

