import time
import signal
import sys
import board
import busio
import adafruit_tcs34725
from PIL import Image

# Global resources for cleanup
i2c_bus = None
color_sensor = None
running = True

def cleanup(signum=None, frame=None):
    """Release resources on exit."""
    global running, i2c_bus, color_sensor
    running = False
    if color_sensor is not None:
        try:
            color_sensor.deinit()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def get_sensor_color_data():
    """Read color data from the TCS34725 sensor.
    Returns (R, G, B, Clear) or (0, 0, 0, 0) on error."""
    try:
        red, green, blue, clear = color_sensor.color_rgb_bytes
        return red, green, blue, clear
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return 0, 0, 0, 0

def find_dominant_image_color(image_path):
    """Identify the dominant color in an image file.
    Returns (R, G, B) or (0, 0, 0) on error."""
    try:
        with Image.open(image_path) as img:
            resized_img = img.resize((100, 100))
            colors = resized_img.getcolors(10000)
            if colors:
                dominant_color = max(colors, key=lambda item: item[0])[1]
                return dominant_color
            else:
                return (0, 0, 0)
    except FileNotFoundError:
        print(f"Image file not found: {image_path}")
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def main():
