#!/usr/bin/env python3
"""Wildlife-tracking IoT gateway: TCP command server with GPS read fallback."""

import json
import socket
import signal
import sys
import time
from typing import Optional, Tuple

import serial
import smbus2

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LISTEN_HOST = "127.0.0.1"
LISTEN_PORT = 9099
GPS_SERIAL_PORT = "/dev/serial0"  # UART on GPIO14/15 (Pi 3/4/5)
GPS_I2C_ADDR = 0x42
GPS_READ_TIMEOUT = 2.0
MAX_CONNECTIONS = 5

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
gps_serial: Optional[serial.Serial] = None
gps_i2c_bus: Optional[smbus2.SMBus] = None
listening_socket: Optional[socket.socket] = None
tracking_state = False


def read_gps_position() -> Tuple[Optional[float], Optional[float]]:
    """Return (lat, lon) from GPS module, or (None, None) if unavailable."""
    global gps_serial, gps_i2c_bus

    # Try serial first
    if gps_serial is not None and gps_serial.is_open:
        try:
            line = gps_serial.readline()
            if not line:
                return None, None
            text = line.decode("ascii", errors="replace").strip()
            if not text:
                return None, None
            # Example: $GPRMC,123519,A,4807.12,N,01131.00,W,0.0,8.2,250323,0.0,A*39
            if text.startswith("$GPRMC"):
                parts = text.split(",")
                if len(parts) >= 7 and parts[2] == "A":
                    lat = float(parts[3])
                    lon = float(parts[5])
                    return lat, lon
        except serial.SerialException as exc:
            print(f"GPS serial read error: {exc}", file=sys.stderr)
            gps_serial = None

    # Try I2C fallback
    if gps_i2c_bus is not None:
        try:
            # Read 20 bytes from GPS module (usually NMEA data)
            data = gps_i2c_bus.read_i2c_block_data(GPS_I2C_ADDR, 0, 20)
            text = "".join(chr(b) for b in data).strip()
            if not text:
                return None, None
            # Same NMEA parsing as above
            if text.startswith("$GPRMC"):
                parts = text.split(",")
                if len(parts) >= 7 and parts[2] == "A":
                    lat = float(parts[3])
                    lon = float(parts[5])
                    return lat, lon
        except OSError as exc:
            print(f"GPS I2C read error: {exc}", file=sys.stderr)
            gps_i2c_bus = None

    # Fallback to simulated coordinates
    return 48.0712, 011.3100


def handle_command(command_text: str) -> str:
    """Process a command and return a JSON response."""
    global tracking_state
    command_text = command_text.strip().lower()

    if command_text == "start":
        tracking_state = True
        return json.dumps({"status": "tracking started"})
    elif command_text == "stop":
        tracking_state = False
        return json.dumps({"status": "tracking stopped"})
    elif command_text == "report":
        lat, lon = read_gps_position()
        if lat is not None and lon is not None:
            return json.dumps({"lat": lat, "lon": lon})
        else:
            return json.dumps({"status": "gps unavailable"})
    else:
        return json.dumps({"error": "unknown command"})


def cleanup(signum: Optional[int] = None, frame=None) -> None:
    """Release all resources on exit."""
    global gps_serial, gps_i2c_bus, listening_socket
    if listening_socket is not None:
        listening_socket.close()
        listening_socket = None
    if gps_serial is not None and gps_serial.is_open:
        gps_serial.close()
        gps_serial = None
    if gps_i2c_bus is not None:
        gps_i2c_bus.close()
        gps_i2c_bus = None
    if signum is not None:
        sys.exit(0)


def main() -> None:
    global gps_serial, gps_i2c_bus, listening_socket

    # Initialize GPS hardware (fall back to simulated coordinates)
    try:
        gps_serial = serial.Serial(
            GPS_SERIAL_PORT, baudrate=9600, timeout=GPS_READ_TIMEOUT
        )
        print(f"GPS serial initialized on {GPS_SERIAL_PORT}")
    except serial.SerialException as exc:
        print(f"GPS serial init failed: {exc}; using simulated coordinates", file=sys.stderr)
        gps_serial = None

    try:
        gps_i2c_bus = smbus2.SMBus(1)
        print(f"GPS I2C bus opened at address 0x{GPS_I2C_ADDR:02X}")
    except OSError as exc:
        print(f"GPS I2C init failed: {exc}; using simulated coordinates", file=sys.stderr)
        gps_i2c_bus = None

    # Set up signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    listening_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    listening_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    listening_socket.bind((LISTEN_HOST, LISTEN_PORT))
    listening_socket.listen(MAX_CONNECTIONS)
    listening_socket.settimeout(1.0)  # Allow periodic signal checks

    print(f"Listening on {LISTEN_HOST}:{LISTEN_PORT} for commands...")

    try:
        while True:
            try:
                connection, address = listening_socket.accept()
                print(f"Connection from {address}")
                with connection:
                    while True:
                        data = connection.recv(1024)
                        if not data:
                            break
                        command_text = data.decode("utf-8", errors="replace")
                        response_text = handle_command(command_text)
                        connection.sendall(response_text.encode("utf-8"))
            except socket.timeout:
                continue
            except ConnectionResetError:
                continue
            except OSError as exc:
                print(f"Socket error: {exc}", file=sys.stderr)
                break
    finally:
        cleanup()


if __name__ == "__main__":
    main()

