import signal
import sys
import time

from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Define GPIO pins for the LEDs (BCM numbering)
LED1_PIN = 18
LED2_PIN = 23

# Global references for cleanup
led1 = None
led2 = None


def setup_gpio():
    """Initialize the two LEDs. Returns True on success, False on failure."""
    global led1, led2
    try:
        led1 = LED(LED1_PIN)
        led2 = LED(LED2_PIN)
        return True
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error setting up GPIO: {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Unexpected error during GPIO setup: {e}", file=sys.stderr)
        return False


def turn_on_leds():
    """Turn both LEDs on simultaneously."""
    try:
        led1.on()
        led2.on()
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error turning LEDs on: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error turning LEDs on: {e}", file=sys.stderr)


def turn_off_leds():
    """Turn both LEDs off simultaneously."""
    try:
        led1.off()
        led2.off()
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error turning LEDs off: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error turning LEDs off: {e}", file=sys.stderr)


def toggle_leds():
    """Toggle both LEDs on for 1 second and off for 1 second, 5 times."""
    for _ in range(5):
        turn_on_leds()
        time.sleep(1)
        turn_off_leds()
        time.sleep(1)


def cleanup_gpio():
    """Close the GPIO resources cleanly."""
    global led1, led2
    try:
        if led1 is not None:
            led1.close()
            led1 = None
        if led2 is not None:
            led2.close()
            led2 = None
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}", file=sys.stderr)


def signal_handler(sig, frame):
    """Handle Ctrl+C to ensure proper cleanup."""
    print("\nCtrl+C detected. Cleaning up GPIO...")
    cleanup_gpio()
    sys.exit(0)


def main():
    """Main function to control the LEDs."""
    if not setup_gpio():
        sys.exit(1)

    signal.signal(signal.SIGINT, signal_handler)

    try:
        toggle_leds()
    except Exception as e:
        print(f"An error occurred during toggling: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

