import signal
import sys
import time
from gpiozero import AngularServo, exc

# SG90 servo pulse-width limits (seconds)
MIN_PULSE_WIDTH = 0.5 / 1000   # 0.5 ms
MAX_PULSE_WIDTH = 2.5 / 1000   # 2.5 ms
FREQUENCY = 50                 # Hz


class RoboticArm:
    """Three-joint robotic arm controlled by gpiozero AngularServo objects."""

    def __init__(self, base_pin=17, shoulder_pin=27, gripper_pin=22):
        self.base_servo = None
        self.shoulder_servo = None
        self.gripper_servo = None
        try:
            self.base_servo = AngularServo(
                base_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=MIN_PULSE_WIDTH,
                max_pulse_width=MAX_PULSE_WIDTH,
                frame_width=1.0 / FREQUENCY,
            )
            self.shoulder_servo = AngularServo(
                shoulder_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=MIN_PULSE_WIDTH,
                max_pulse_width=MAX_PULSE_WIDTH,
                frame_width=1.0 / FREQUENCY,
            )
            self.gripper_servo = AngularServo(
                gripper_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=MIN_PULSE_WIDTH,
                max_pulse_width=MAX_PULSE_WIDTH,
                frame_width=1.0 / FREQUENCY,
            )
        except exc.OutputDeviceBadValue as e:
            self.close()
            raise ValueError(
                f"Invalid pin or angle configuration: {e}"
            ) from e
        except exc.GPIODeviceError as e:
            self.close()
            raise RuntimeError(f"GPIO allocation failed: {e}") from e

    def move_joint(self, servo, target_angle):
        """Move a single servo joint to a clamped target angle with settling."""
        if servo is None:
            return
        try:
            clamped = max(-90, min(90, target_angle))
            servo.angle = clamped
            time.sleep(0.4)
        except exc.OutputDeviceBadValue as e:
            print(f"Warning: invalid angle {target_angle} for servo: {e}")
        except Exception as e:
            print(f"Warning: error moving servo: {e}")

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        """Move all three joints to the specified angles sequentially."""
        self.move_joint(self.base_servo, base_angle)
        self.move_joint(self.shoulder_servo, shoulder_angle)
        self.move_joint(self.gripper_servo, gripper_angle)

    def release(self):
        """Detach all servos so they stop driving the PWM pins."""
        for servo in (self.base_servo, self.shoulder_servo, self.gripper_servo):
            if servo is not None:
                try:
                    servo.angle = None
                except Exception:
                    pass

    def close(self):
        """Release all servos and release GPIO resources."""
        self.release()
        for servo in (self.base_servo, self.shoulder_servo, self.gripper_servo):
            if servo is not None:
                try:
                    servo.close()
                except Exception:
                    pass


def run_demo_sequence(robot_arm):
    """Execute the predefined robotic arm demonstration sequence."""
    demo_poses = [
        (0, 0, 0),
        (45, -30, 20),
        (-45, 30, -20),
        (0, 0, 0),
    ]
    for base_angle, shoulder_angle, gripper_angle in demo_poses:
        print(f"Moving to pose: base={base_angle}, shoulder={shoulder_angle}, gripper={gripper_angle}")
        robot_arm.go_to_pose(base_angle, shoulder_angle, gripper_angle)


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, exiting.")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    robot_arm = None
    try:
        robot_arm = RoboticArm()
