import signal
import sys
import logging
import time
from typing import Dict, Any, Optional

import serial
from pymodbus.client import ModbusSerialClient
from pymodbus.exceptions import ModbusException
from pymodbus.payload import BinaryPayloadDecoder
from pymodbus.constants import Endian

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

SERIAL_PORT = '/dev/serial0'
BAUDRATE = 115200
TIMEOUT = 1.0
MOTOR_ID = 1


class Servo:
    """
    A class to represent a servo motor connected to a Raspberry Pi via Modbus RTU.
    """

    CONTROL = {
        'R/W': 'W',
        'Register': 0x3100,
        'functioncode': 6,
        'Value': {
            'Stop': 0x0006,
            'Start': 0x000F,
        },
    }

    STATUS = {
        'R/W': 'R',
        'Register': 0x3000,
        'functioncode': 3,
    }

    OPMODE = {
        'R/W': 'W',
        'Register': 0x3500,
        'functioncode': 6,
        'Value': {
            'Position': 1,
        },
    }

    VelocityCommand = {
        'R/W': 'W',
        'Register': 0x6F00,
        'functioncode': 6,
    }

    VelocityFeedback = {
        'R/W': 'R',
        'Register': 0x3B00,
        'functioncode': 3,
        'read_length': 2,
    }

    PositionCommand = {
        'R/W': 'W',
        'Register': 0x4000,
        'functioncode': 6,
    }

    PositionFeedback = {
        'R/W': 'R',
        'Register': 0x3700,
        'functioncode': 3,
        'read_length': 2,
    }

    def __init__(self, port: str = SERIAL_PORT, baudrate: int = BAUDRATE, timeout: float = TIMEOUT, motor_id: int = MOTOR_ID):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.motor_id = motor_id
        self.client: Optional[ModbusSerialClient] = None
        self._running = True
        self._connect()

    def _connect(self) -> None:
        try:
            self.client = ModbusSerialClient(
                port=self.port,
                baudrate=self.baudrate,
                parity='N',
                stopbits=1,
                bytesize=8,
                timeout=self.timeout,
            )
            if not self.client.connect():
                logger.error("Failed to connect to Modbus RTU device on %s", self.port)
                self.client = None
                raise ConnectionError(f"Cannot open serial port {self.port}")
            logger.info("Connected to Modbus RTU device on %s", self.port)
        except Exception as e:
            logger.error("Error connecting to Modbus RTU device: %s", e)
            self.client = None
            raise

    def _read_register(self, register_address: int, count: int = 2) -> Optional[Any]:
        if self.client is None:
            logger.error("Client not connected; cannot read register 0x%04X", register_address)
            return None
        try:
            response = self.client.read_holding_registers(
                address=register_address,
                count=count,
                slave=self.motor_id,
            )
            if response.isError():
                logger.error("Modbus error reading register 0x%04X: %s", register_address, response)
                return None
            decoder = BinaryPayloadDecoder.fromRegisters(response.registers, byteorder=Endian.BIG, wordorder=Endian.LITTLE)
            return decoder.decode_16bit_uint()
        except ModbusException as e:
            logger.error("Modbus exception reading register 0x%04X: %s", register_address, e)
            return None
        except Exception as e:
            logger.error("Unexpected error reading register 0x%04X: %s", register_address, e)
            return None

    def _write_register(self, register_address: int, value: int, count: int = 2) -> bool:
        if self.client is None:
            logger.error("Client not connected; cannot write register 0x%04X", register_address)
            return False
        try:
            response = self.client.write_registers(
                address=register_address,
                values=[value],
                count=count,
                slave=self.motor_id,
            )
            if response.isError():
                logger.error("Modbus error writing register 0x%04X: %s", register_address, response)
                return False
            return True
        except ModbusException as e:
            logger.error("Modbus exception writing register 0x%04X: %s", register_address, e)
            return False
        except Exception as e:
            logger.error("Unexpected error writing register 0x%04X: %s", register_address, e)
            return False

    def get_status(self) -> Optional[int]:
        return self._read_register(self.STATUS['Register'])

    def get_opmode(self) -> Optional[int]:
        return self._read_register(self.OPMODE['Register'])

    def set_opmode(self, mode: int) -> bool:
        if self.OPMODE['Value'].get(mode) is None:
            logger.error("Invalid OPMODE value: %s", mode)
            return False
        return self._write_register(self.OPMODE['Register'], self.OPMODE['Value'][mode])

    def get_velocity_feedback(self) -> Optional[int]:
        return self._read_register(self.VelocityFeedback['Register'], self.VelocityFeedback['read_length'])

    def get_position_feedback(self) -> Optional[int]:
        return self._read_register(self.PositionFeedback['Register'], self.PositionFeedback['read_length'])

    def set_velocity_command(self, velocity: int) -> bool:
        return self._write_register(self.VelocityCommand['Register'], velocity)

    def set_position_command(self, position: int) -> bool:
        return self._write_register(self.PositionCommand['Register'], position)

    def stop(self) -> bool:
        if self.CONTROL['Value'].get('Stop') is None:
            logger.error("Invalid STOP value")
            return False
        return self._write_register(self.CONTROL['Register'], self.CONTROL['Value']['Stop'])

    def start(self) -> bool:
        if self.CONTROL['Value'].get('Start') is None:
            logger.error("Invalid START value")
            return False
        return self._write_register(self.CONTROL['Register'], self.CONTROL['Value']['Start'])

    def close(self) -> None:
        if self.client is not None:
            try:
                self.client.close()
            except Exception as e:
                logger.warning("Error closing Modbus client: %s", e)
            finally:
                self.client = None
        logger.info("Servo connection closed.")


def _signal_handler(signum, frame):
    logger.info("Signal %s received, shutting down...", signum)
    if 'servo' in globals() and servo is not None:
        servo.close()
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    servo = None
    try:
        servo = Servo()
        logger.info("Servo connected. Status: %s", servo.get_status())
        logger.info("Current OPMODE: %s", servo.get_opmode())
        logger.info("Velocity Feedback: %s", servo.get_velocity_feedback())
        logger.info("Position Feedback: %s", servo.get_position_feedback())
        if servo.set_opmode(1):
            logger.info("OPMODE set to Position")
        if servo.set_velocity_command(100):
            logger.info("Velocity Command set to 100")
        if servo.set_position_command(5000):
            logger.info("Position Command set to 5000")
        if servo.start():
            logger.info("Servo started")
        time.sleep(2)
        logger.info("Current OPMODE: %s", servo.get_opmode())
        logger.info("Velocity Feedback: %s", servo.get_velocity_feedback())
        logger.info("Position Feedback: %s", servo.get_position_feedback())
        if servo.stop():
            logger.info("Servo stopped")
    except Exception as e:
        logger.error("Fatal error: %s", e)
    finally:
        if servo is not None:
            servo.close()

