#!/usr/bin/env python3
"""
Raspberry Pi Garage Door Controller using Pimoroni Automation HAT.

Wiring:
  - Automation HAT relay one (output 1) -> relay module input (e.g., relay 1)
  - Automation HAT input one (state_pin=1) -> magnetic reed switch to GND
    (HIGH = door closed, LOW = door open)

Requires: automationhat (pip install automationhat)
"""

import logging
import signal
import sys
import time

try:
    import automationhat
except ImportError:
    automationhat = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DOOR_CLOSED = "closed"
DOOR_OPEN = "open"

RELAY_CHANNEL = 1          # Automation HAT relay one
TRIGGER_DURATION = 0.5     # seconds
STATE_PIN = 1              # Automation HAT input one

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global _running
    logger.info("Signal %s received – shutting down.", signum)
    _running = False


def _check_automationhat():
    """Verify that the automationhat library is available and connected."""
    if automationhat is None:
        logger.error("automationhat library is not installed. "
                     "Install with: pip install automationhat")
        return False
    if not automationhat.connected:
        logger.error("Automation HAT not detected on the I2C bus. "
                     "Check wiring and I2C address (default 0x62).")
        return False
    return True


def _read_door_state():
    """
    Read the door state from the Automation HAT input channel.

    Returns:
        str: DOOR_CLOSED if HIGH, DOOR_OPEN if LOW.
    Raises:
        RuntimeError: if the read fails or returns an unexpected value.
    """
    if not automationhat.connected:
        raise RuntimeError("Automation HAT is not connected.")

    value = automationhat.input[STATE_PIN].read()
    if value is None:
        raise RuntimeError("Failed to read input channel %d: no response from HAT." % STATE_PIN)
    if not isinstance(value, int):
        raise RuntimeError("Unexpected data type from input %d: %r" % (STATE_PIN, value))

    if value == 1:
        return DOOR_CLOSED
    if value == 0:
        return DOOR_OPEN
    raise RuntimeError("Invalid input value %r on channel %d." % (value, STATE_PIN))


def _trigger_relay():
    """Energize relay one for TRIGGER_DURATION seconds, then de-energize."""
    if not automationhat.connected:
        raise RuntimeError("Automation HAT is not connected.")
    automationhat.relay[RELAY_CHANNEL].on()
    logger.info("Relay %d energized for %.1f s.", RELAY_CHANNEL, TRIGGER_DURATION)
    time.sleep(TRIGGER_DURATION)
    automationhat.relay[RELAY_CHANNEL].off()
    logger.info("Relay %d de-energized.", RELAY_CHANNEL)


class GarageDoor:
    """Manage a garage door via the Automation HAT relay and state input."""

    def __init__(self, name, state_pin=STATE_PIN):
        self.name = name
        self.state_pin = state_pin
        self._closed = False
        self._open = False

        if not _check_automationhat():
            raise RuntimeError("Automation HAT hardware unavailable – cannot continue.")

        # Ensure relay starts in a safe OFF state
        try:
            automationhat.relay[RELAY_CHANNEL].off()
        except Exception as exc:
            logger.error("Failed to initialise relay %d: %s", RELAY_CHANNEL, exc)
            raise

        logger.info("%s initialised: state_pin=%d, relay=%d.",
                    self.name, self.state_pin, RELAY_CHANNEL)

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    @property
    def closed(self):
        """True if the door is currently closed (HIGH on state_pin)."""
        return self._closed

    @property
    def open(self):
        """True if the door is currently open (LOW on state_pin)."""
        return self._open

    @property
    def state(self):
        """Current door state: 'closed' or 'open'."""
        try:
            return _read_door_state()
        except Exception as exc:
            logger.error("Error reading door state: %s", exc)
            raise

    def trigger(self):
        """Energize the relay to toggle the door state."""
        try:
            if self.state == DOOR_CLOSED:
                logger.info("%s: door is closed – opening.", self.name)
                self._closed = False
                self._open = True
            else:
                logger.info("%s: door is open – closing.", self.name)
                self._closed = True
                self._open = False
            _trigger_relay()
        except Exception as exc:
            logger.error("Error triggering door: %s", exc)
            raise

    def close(self):
        """Close the door if it is currently open."""
        if self.state == DOOR_OPEN:
            logger.info("%s: closing door.", self.name)
            self.trigger()
        else:
            logger.info("%s: door is already closed.", self.name)

    def open(self):
        """Open the door if it is currently closed."""
        if self.state == DOOR_CLOSED:
            logger.info("%s: opening door.", self.name)
            self.trigger()
        else:
            logger.info("%s: door is already open.", self.name)

    def cleanup(self):
        """Release resources: ensure relay is OFF."""
        try:
            automationhat.relay[RELAY_CHANNEL].off()
            logger.info("%s: relay %d turned OFF.", self.name, RELAY_CHANNEL)
        except Exception as exc:
            logger.error("Error during cleanup: %s", exc)


def main():
    """Entry point: initialise the garage door and run until interrupted."""
