#!/usr/bin/env python3
"""
Raspberry Pi Zero W Soil Moisture Monitor with Water Pump Control

Reads soil moisture from an Adafruit Seesaw sensor on I2C (address 0x36).
Controls a 12V water pump via a relay on GPIO17 (BCM).
Prints readings every 10 seconds. Ensures pump is off and resources are released on exit.
"""

import signal
import sys
import time
import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# Configuration
I2C_ADDRESS = 0x36
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

# Global resources for cleanup
i2c_bus = None
soil_sensor = None
pump_relay = None
running = True


def cleanup_resources():
    """Release all resources cleanly."""
    global i2c_bus, pump_relay, running
    running = False

    if pump_relay is not None:
        try:
            pump_relay.off()
            pump_relay.close()
        except Exception:
            pass
        pump_relay = None

    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        i2c_bus = None


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    cleanup_resources()
    sys.exit(0)


def initialize_i2c():
    """Initialize the I2C bus."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return True
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return False


def initialize_soil_sensor():
    """Initialize the Seesaw soil moisture sensor."""
    global soil_sensor
    try:
        soil_sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
        return True
    except ValueError as e:
        print(f"Seesaw sensor not found at address 0x{I2C_ADDRESS:02X}: {e}")
        return False
    except Exception as e:
        print(f"Error initializing Seesaw sensor: {e}")
        return False


def initialize_pump():
    """Initialize the pump relay on GPIO17."""
    global pump_relay
    try:
        pump_relay = OutputDevice(PUMP_GPIO_PIN, active_high=True, initial_value=False)
        return True
    except GPIOZeroError as e:
        print(f"Error initializing GPIO {PUMP_GPIO_PIN}: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error initializing GPIO {PUMP_GPIO_PIN}: {e}")
        return False


def read_soil_moisture():
    """Read soil moisture from the sensor."""
    if soil_sensor is None:
        return None
    try:
        return soil_sensor.moisture_read()
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None


def control_water_pump(moisture_level):
    """Control the water pump based on moisture level."""
    if pump_relay is None:
        return
    try:
        if moisture_level is not None and moisture_level < MOISTURE_THRESHOLD:
            pump_relay.on()
            print("Water Pump ON: Soil is dry.")
        else:
            pump_relay.off()
            print("Water Pump OFF: Soil is moist enough.")
    except GPIOZeroError as e:
        print(f"Error controlling pump: {e}")
    except Exception as e:
        print(f"Unexpected error controlling pump: {e}")


def main():
    """Main program loop."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize hardware
    if not initialize_i2c():
        print("Failed to initialize I2C. Exiting.")
        sys.exit(1)

    if not initialize_soil_sensor():
        print("Failed to initialize soil sensor. Exiting.")
        cleanup_resources()
        sys.exit(1)

    if not initialize_pump():
        print("Failed to initialize pump. Exiting.")
        cleanup_resources()
        sys.exit(1)

    print("Soil moisture monitor started. Press Ctrl+C to exit.")

    try:
        while running:
            moisture = read_soil_moisture()
            if moisture is not None:
                print(f"Soil Moisture: {moisture}")
            else:
                print("Failed to read soil moisture.")
            control_water_pump(moisture)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup_resources()
        print("Program terminated.")


if __name__ == "__main__":
    main()

