SHORT_DELAY = 0.5
LONG_DELAY = 1.0
LASER_ON_TIME = 0.1


class Laser:
    """Controls a laser module via gpiozero.OutputDevice."""

    def __init__(self, pin=LASER_PIN):
        self.pin = pin
        self.device = None
        try:
            self.device = OutputDevice(pin)
        except GPIOZeroError as e:
            raise RuntimeError(f"Failed to initialize laser on GPIO{pin}: {e}") from e

    def on(self):
        if self.device is None:
            raise RuntimeError("Laser device is not initialized.")
        self.device.on()

    def off(self):
        if self.device is None:
            raise RuntimeError("Laser device is not initialized.")
        self.device.off()

    def close(self):
        if self.device is not None:
            try:
                self.device.close()
            except DeviceClosed:
                pass
            except Exception:
                pass
            finally:
                self.device = None


class Aim:
    """Controls horizontal and vertical servos and a laser for aiming."""

    def __init__(self, ld=LASER_ON_TIME, sd=SHORT_DELAY):
        self.ld = ld
        self.sd = sd
        self.laser = Laser()
        self.h = None
        self.v = None
        try:
            self.h = Servo(
                HORIZONTAL_PIN,
                min_pulse_width=HORIZONTAL_MIN,
                max_pulse_width=HORIZONTAL_MAX,
            )
            self.v = Servo(
                VERTICAL_PIN,
                min_pulse_width=VERTICAL_MIN,
                max_pulse_width=VERTICAL_MAX,
            )
        except GPIOZeroError as e:
            self.laser.close()
            raise RuntimeError(f"Failed to initialize servos: {e}") from e

