                else:
                    break
            except serial.SerialException as e:
                logging.error(f"Serial read error: {e}")
                return None
            except Exception as e:
                logging.error(f"Unexpected read error: {e}")
                return None
            time.sleep(0.1)
        try:
            decoded = response.decode('utf-8', errors='ignore')
            logging.debug(f"Read response: {decoded.strip()}")
            return decoded.strip()
        except Exception as e:
            logging.error(f"Failed to decode response: {e}")
            return None

    def set_message_storage(self, storage="SM"):
        command = f'AT+CPMS="{storage}","{storage}","{storage}"'
        if self._send_at_command(command, expected_response="OK"):
            logging.info(f"Message storage set to {storage}.")
            return True
        return False

    def close(self):
        self._cleanup()


def _signal_handler(signum, frame, gsm=None):
    logging.info(f"Signal {signum} received, shutting down.")
    if gsm:
        gsm.close()
    sys.exit(0)


if __name__ == "__main__":
    gsm = None
    try:
        gsm = GSMModule(port='/dev/serial0', baudrate=115200, timeout=2, power_pin=4)
        signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, gsm))
        signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, gsm))

        gsm.set_gps_reporting(interval_seconds=10)
        gsm.send_tcp_data("Hello, TCP!")
        gsm.send_terminator()
        gsm.set_message_storage(storage="SM")
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if gsm:
            gsm.close()

