import time
import signal
import sys
import adafruit_servokit as sdk

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def initialize_servokit():
    """Initializes the ServoKit with error handling."""
    try:
        kit = sdk.ServoKit(channels=16, i2c=None, address=0x40)
        return kit
    except OSError as e:
        print(f"Error initializing ServoKit (OSError): {e}")
        return None
    except ValueError as e:
        print(f"Error initializing ServoKit (ValueError): {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        return None

def move_servo(kit, servo_num, target_angle):
    """Moves a servo to a target angle with error handling."""
    if kit is None:
        print("ServoKit not initialized. Cannot move servo.")
        return False

    if not (0 <= servo_num <= 15):
        print(f"Invalid servo number: {servo_num}. Must be between 0 and 15.")
        return False

    if not (0 <= target_angle <= 180):
        print(f"Invalid target angle: {target_angle}. Must be between 0 and 180.")
        return False

    try:
        current_angle = kit.servo[servo_num].angle
        if current_angle is None:
            current_angle = 0

        # Smooth movement in 5-degree increments
        step = 5 if target_angle > current_angle else -5
        angle = current_angle
        while _running and (step > 0 and angle < target_angle or step < 0 and angle > target_angle):
            angle += step
            kit.servo[servo_num].angle = angle
            time.sleep(0.04)

        # Ensure final position
        kit.servo[servo_num].angle = target_angle
        return True

    except OSError as e:
        print(f"OSError moving servo {servo_num}: {e}")
        return False
    except ValueError as e:
        print(f"ValueError moving servo {servo_num}: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")
        return False

def grab_object(kit, servo_num=0):
    """Grabs an object using the specified servo."""
    print("Grabbing object...")
    return move_servo(kit, servo_num, 90)

def release_object(kit, servo_num=0):
    """Releases an object using the specified servo."""
    print("Releasing object...")
    return move_servo(kit, servo_num, 150)

def main():
    """Main function to demonstrate object manipulation."""
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        if grab_object(kit, servo_num=0):
            print("Object grabbed successfully.")
        else:
            print("Failed to grab object.")

        if release_object(kit, servo_num=0):
            print("Object released successfully.")
        else:
            print("Failed to release object.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        # Clean up: stop any ongoing movement and release resources
        try:
            for i in range(16):
                kit.servo[i].angle = None
        except Exception:
            pass

        print("ServoKit resources released. Exiting.")

if __name__ == "__main__":
    main()

