    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Define GPIO pins for the hydroponics actuators
NUTRIENT_PUMP_PIN = 20
GROW_LIGHT_PIN = 21

# Initialize hydroponics actuators using gpiozero
try:
    nutrient_pump = OutputDevice(NUTRIENT_PUMP_PIN)
    grow_light = OutputDevice(GROW_LIGHT_PIN)
    logging.info("Hydroponics actuators initialized successfully.")
except GPIOZeroError as e:
    logging.error(f"Failed to initialize hydroponics actuators: {e}")
    raise SystemExit(1)

# Dictionary mapping recognized phrases to hydroponics intents
INTENT_MAP = {
    "turn the pump on": "pump_on",
    "switch the light": "light_toggle",
    "turn pump off": "pump_off",
}


def parse_phrase(phrase):
    """Parses a plain English phrase into a hydroponics intent."""
    # Convert the phrase to lowercase for case-insensitive matching
    lower_phrase = phrase.lower()
    # Return the corresponding intent if it exists in the map
    return INTENT_MAP.get(lower_phrase)


def execute_intent(intent):
    """Executes the given hydroponics intent on the actuators."""
    if intent == "pump_on":
        nutrient_pump.on()
        logging.info("Nutrient pump turned ON.")
    elif intent == "pump_off":
        nutrient_pump.off()
        logging.info("Nutrient pump turned OFF.")
    elif intent == "light_toggle":
        grow_light.toggle()
        logging.info("Grow light toggled.")
    else:
        logging.warning(f"Unknown intent: {intent}")


def cleanup():
    """Safely shut down all hydroponics actuators."""
    logging.info("Shutting down hydroponics actuators...")
    try:
        nutrient_pump.off()
        nutrient_pump.close()
    except Exception as e:
        logging.error(f"Error closing nutrient pump: {e}")
    try:
        grow_light.off()
        grow_light.close()
    except Exception as e:
        logging.error(f"Error closing grow light: {e}")
    logging.info("Hydroponics actuators shut down.")


if __name__ == "__main__":
    # List of test phrases to demonstrate the system
    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]

    try:
        for phrase in test_phrases:
            intent = parse_phrase(phrase)
            if intent:
                execute_intent(intent)
            else:
                logging.warning(f"Could not parse phrase: {phrase}")
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

