import smbus2
import time
import signal
import sys

# CCS811 I2C address and registers
CCS811_ADDR = 0x5A
APP_START_REG = 0xF4
ALG_RESULT_DATA_REG = 0x02

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def init_ccs811(bus):
    """Initialize the CCS811 sensor by writing 0x20 to APP_START register."""
    try:
        bus.write_byte_data(CCS811_ADDR, APP_START_REG, 0x20)
        time.sleep(0.1)  # Allow time for the sensor to boot
    except OSError as e:
        print(f"Error initializing CCS811: {e}")
        raise

def read_co2_concentration(bus):
    """Read CO2 concentration from the CCS811 sensor."""
    try:
        data = bus.read_i2c_block_data(CCS811_ADDR, ALG_RESULT_DATA_REG, 2)
        if len(data) < 2:
            raise IOError("Incomplete data read from CCS811")
        co2_value = (data[0] << 8) | data[1]
        return co2_value
    except OSError as e:
        print(f"Error reading CO2 concentration: {e}")
        raise

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        # Verify sensor presence before attempting communication
        try:
            bus = smbus2.SMBus(1)
            bus.read_byte_data(CCS811_ADDR, 0x00)  # Check device ID register
        except OSError:
            print(f"CCS811 sensor not found at address 0x{CCS811_ADDR:02X} on I2C bus 1.")
            return

        init_ccs811(bus)

        for i in range(5):
            if not _running:
                print("\nShutdown requested. Exiting loop.")
                break
            try:
                co2_concentration = read_co2_concentration(bus)
                print(f"CO2 Concentration: {co2_concentration} ppm")
            except (OSError, IOError) as e:
                print(f"Error reading CO2 concentration: {e}")
                break
            if i < 4:
                time.sleep(2)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print("Program finished.")

if __name__ == "__main__":
    main()

