import signal
import sys
from datetime import datetime
from smbus2 import SMBus, i2c_msg

# DS1338 constants
DS1338_I2C_ADDRESS = 0x68
I2C_BUS_NUMBER = 1

# Register addresses
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06

# Bit masks
HOUR_12_24_MASK = 0x40  # 12/24 hr format bit (bit 6)
HOUR_12_MASK = 0x10     # 12 hr mode bit (bit 4)
HOUR_24_MASK = 0x00     # 24 hr mode bit (bit 4 cleared)

# Global bus handle for signal handler cleanup
_bus_handle = None


def _bcd_to_int(bcd):
    """Convert a BCD byte to an integer."""
    return (bcd >> 4) * 10 + (bcd & 0x0F)


def _int_to_bcd(n):
    """Convert an integer (0-99) to BCD."""
    return ((n // 10) << 4) | (n % 10)


class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) chip using smbus2."""

    def __init__(self, i2c_bus_number=I2C_BUS_NUMBER, address=DS1338_I2C_ADDRESS):
        """Initialize the DS1338 and verify device presence."""
        global _bus_handle
        try:
            _bus_handle = SMBus(i2c_bus_number)
        except OSError as e:
            raise OSError(f"Failed to open I2C bus {i2c_bus_number}: {e}") from e

        # Probe the device address to confirm it is present
        try:
            _bus_handle.read_byte_data(address, REG_SECONDS)
        except OSError as e:
            _bus_handle.close()
            _bus_handle = None
            raise OSError(
                f"No DS1338 found at address 0x{address:02X} on bus {i2c_bus_number}: {e}"
            ) from e

        self.address = address

    def _write_register(self, register, value):
        """Write a single byte to a DS1338 register."""
        try:
            _bus_handle.write_byte_data(self.address, register, value)
        except OSError as e:
            raise OSError(f"I2C write to register 0x{register:02X} failed: {e}") from e

    def _read_register(self, register):
        """Read a single byte from a DS1338 register."""
        try:
            return _bus_handle.read_byte_data(self.address, register)
        except OSError as e:
            raise OSError(f"I2C read from register 0x{register:02X} failed: {e}") from e

    def _bcd_to_int(self, value):
        """Convert a BCD byte to an integer."""
        return (value >> 4) * 10 + (value & 0x0F)

    def _int_to_bcd(self, value):
        """Convert an integer (0-99) to BCD."""
        return ((value // 10) << 4) | (value % 10)

    def read_seconds(self):
        """Read the seconds register (0x00)."""
        seconds = self._read_register(REG_SECONDS)
        return self._bcd_to_int(seconds & 0x7F)  # mask CH bit (bit 7)

    def read_minutes(self):
        """Read the minutes register (0x01)."""
        minutes = self._read_register(REG_MINUTES)
        return self._bcd_to_int(minutes & 0x7F)

    def read_hours(self):
        """Read the hours register (0x02)."""
        hours = self._read_register(REG_HOURS)
        if hours & HOUR_12_24_MASK:
            # 12-hour mode
            return self._bcd_to_int(hours & 0x1F)  # mask 12/24 bit and AM/PM bit
        else:
            # 24-hour mode
            return self._bcd_to_int(hours & 0x3F)

    def read_date(self):
        """Read the date register (0x04)."""
        date = self._read_register(REG_DATE)
        return self._bcd_to_int(date & 0x3F)

    def read_month(self):
        """Read the month register (0x05)."""
        month = self._read_register(REG_MONTH)
        return self._bcd_to_int(month & 0x1F)

    def read_year(self, century=21):
        """Read the year register (0x06) and combine with century."""
        year_raw = self._read_register(REG_YEAR)
        year = self._bcd_to_int(year_raw & 0x3F)
        return century * 100 + year

    def read_datetime(self, century=21):
        """Read the entire datetime tuple (year, month, date, hours, minutes, seconds)."""
        year = self.read_year(century)
        month = self.read_month()
        date = self.read_date()
        hours = self.read_hours()
        minutes = self.read_minutes()
        seconds = self.read_seconds()
        return year, month, date, hours, minutes, seconds

    def write_seconds(self, seconds):
        """Write seconds register (0x00)."""
        self._write_register(REG_SECONDS, self._int_to_bcd(seconds & 0x7F))

    def write_minutes(self, minutes):
        """Write minutes register (0x01)."""
        self._write_register(REG_MINUTES, self._int_to_bcd(minutes & 0x7F))

    def write_hours(self, hours):
        """Write hours register (0x02)."""
        if hours > 23:
            raise ValueError(f"Invalid hours value {hours}; must be 0-23.")
        hours_bcd = self._int_to_bcd(hours)
        if hours_bcd & HOUR_12_24_MASK:
            # 12-hour mode
            self._write_register(REG_HOURS, hours_bcd & 0x1F)
        else:
            # 24-hour mode
            self._write_register(REG_HOURS, hours_bcd & 0x3F)

    def write_date(self, date):
        """Write date register (0x04)."""
        if date < 1 or date > 31:
            raise ValueError(f"Invalid date value {date}; must be 1-31.")
        self._write_register(REG_DATE, self._int_to_bcd(date & 0x3F))

    def write_month(self, month):
        """Write month register (0x05)."""
        if month < 1 or month > 12:
            raise ValueError(f"Invalid month value {month}; must be 1-12.")
        self._write_register(REG_MONTH, self._int_to_bcd(month & 0x1F))

    def write_year(self, year, century=21):
        """Write year register (0x06) with century prefix."""
        if year < 0 or year > 99:
            raise ValueError(f"Invalid year value {year}; must be 0-99.")
        year_bcd = self._int_to_bcd(year)
        self._write_register(REG_YEAR, year_bcd)

    def write_all(self, year=None, month=None, date=None, hours=None, minutes=None, seconds=None):
        """Write all datetime fields. Only specified fields are written."""
        if year is not None:
            self.write_year(year)
        if month is not None:
            self.write_month(month)
        if date is not None:
            self.write_date(date)
        if hours is not None:
            self.write_hours(hours)
        if minutes is not None:
            self.write_minutes(minutes)
        if seconds is not None:
            self.write_seconds(seconds)

    def close(self):
        """Release the I2C bus handle."""
        global _bus_handle
        if _bus_handle is not None:
            try:
                _bus_handle.close()
            except OSError:
                pass
            _bus_handle = None

    def __del__(self):
        self.close()


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}, exiting.")
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        rtc = DS1338()
        print("DS1338 initialized successfully.")

        # Read and print current time
        now = rtc.read_datetime()
        print(f"Current RTC time: {now[0]}-{now[1]:02d}-{now[2]:02d} {now[3]:02d}:{now[4]:02d}:{now[5]:02d}")

        # Set time to current system time
        now_sys = datetime.now()
        rtc.write_all(
            year=now_sys.year,
            month=now_sys.month,
            date=now_sys.day,
            hours=now_sys.hour,
            minutes=now_sys.minute,
            seconds=now_sys.second,
        )
        print("RTC time updated to system time.")

        # Verify by reading back
        verified = rtc.read_datetime()
        print(f"Verified RTC time: {verified[0]}-{verified[1]:02d}-{verified[2]:02d} {verified[3]:02d}:{verified[4]:02d}:{verified[5]:02d}")

    except OSError as e:
        print(f"I2C error: {e}")
    except ValueError as e:
        print(f"Value error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if _bus_handle is not None:
            _bus_handle.close()
            _bus_handle = None


if __name__ == "__main__":
    main()

