        self._write_register(REG_MONTH, self._int_to_bcd(month & 0x1F))

    def write_year(self, year, century=21):
        """Write year register (0x06) with century prefix."""
        if year < 0 or year > 99:
            raise ValueError(f"Invalid year value {year}; must be 0-99.")
        year_bcd = self._int_to_bcd(year)
        self._write_register(REG_YEAR, year_bcd)

    def write_all(self, year=None, month=None, date=None, hours=None, minutes=None, seconds=None):
        """Write all datetime fields. Only specified fields are written."""
        if year is not None:
            self.write_year(year)
        if month is not None:
            self.write_month(month)
        if date is not None:
            self.write_date(date)
        if hours is not None:
            self.write_hours(hours)
        if minutes is not None:
            self.write_minutes(minutes)
        if seconds is not None:
            self.write_seconds(seconds)

    def close(self):
        """Release the I2C bus handle."""
        global _bus_handle
        if _bus_handle is not None:
            try:
                _bus_handle.close()
            except OSError:
                pass
            _bus_handle = None

    def __del__(self):
        self.close()


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}, exiting.")
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        rtc = DS1338()
        print("DS1338 initialized successfully.")

        # Read and print current time
        now = rtc.read_datetime()
        print(f"Current RTC time: {now[0]}-{now[1]:02d}-{now[2]:02d} {now[3]:02d}:{now[4]:02d}:{now[5]:02d}")

        # Set time to current system time
        now_sys = datetime.now()
        rtc.write_all(
            year=now_sys.year,
            month=now_sys.month,
            date=now_sys.day,
            hours=now_sys.hour,
            minutes=now_sys.minute,
            seconds=now_sys.second,
        )
        print("RTC time updated to system time.")

        # Verify by reading back
        verified = rtc.read_datetime()
        print(f"Verified RTC time: {verified[0]}-{verified[1]:02d}-{verified[2]:02d} {verified[3]:02d}:{verified[4]:02d}:{verified[5]:02d}")

    except OSError as e:
        print(f"I2C error: {e}")
    except ValueError as e:
        print(f"Value error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if _bus_handle is not None:
            _bus_handle.close()
            _bus_handle = None


if __name__ == "__main__":
    main()

