import serial
import time
import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
LOOP_DELAY = 1

running = True
serial_port = None
alarm = None


def handle_signal(signum, frame):
    global running
    running = False


def cleanup():
    global serial_port, alarm
    if serial_port is not None and serial_port.is_open:
        try:
            serial_port.close()
        except Exception:
            pass
    if alarm is not None:
        try:
            alarm.off()
            alarm.close()
        except Exception:
            pass


def main():
    global serial_port, alarm

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        serial_port = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as e:
        print(f"Error: could not open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as e:
        print(f"Error: could not initialize GPIO {ALARM_PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    alarm_state = False

    try:
        while running:
            try:
                raw = serial_port.readline()
            except serial.SerialException as e:
                print(f"Serial I/O error: {e}", file=sys.stderr)
                time.sleep(LOOP_DELAY)
                continue

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                radiation_level = float(line)
            except ValueError:
                print(f"Warning: non-numeric data received: {line!r}", file=sys.stderr)
                continue

            print(f"Radiation Level: {radiation_level:.2f} µSv/h")

            if radiation_level > RADIATION_THRESHOLD:
                if not alarm_state:
                    alarm.on()
                    alarm_state = True
                    print("Alarm activated!")
            else:
                if alarm_state:
                    alarm.off()
                    alarm_state = False
                    print("Alarm deactivated.")

            time.sleep(LOOP_DELAY)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == '__main__':
    main()

