import signal
import sys
import time
from dataclasses import dataclass
from typing import Optional

import serial

# Serial port configuration
SERIAL_PORT = "/dev/serial0"  # Raspberry Pi primary UART
BAUDRATE = 9600
TIMEOUT = 1  # seconds


@dataclass
class GPS_readings:
    """Represents GPS readings parsed from a GPGGA sentence."""

    latitude: float
    longitude: float
    altitude: float
    num_satellites: int


class GPSReader:
    """Reads and parses GPS data from a serial port."""

    def __init__(self, port: str = SERIAL_PORT, baudrate: int = BAUDRATE, timeout: int = TIMEOUT):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._running = True

    def connect(self) -> bool:
        """Open the serial port. Returns True on success, False on failure."""
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            print(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            print(f"Error opening serial port {self.port}: {e}", file=sys.stderr)
            self.serial_port = None
            return False
        except OSError as e:
            print(f"OS error opening {self.port}: {e}", file=sys.stderr)
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        """Close the serial port if open. Idempotent."""
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    print("Serial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}", file=sys.stderr)
            finally:
                self.serial_port = None

    def _nmea_to_decimal(self, coordinate: str, direction: str) -> float:
        """Convert NMEA ddmm.mmmm to decimal degrees."""
        if not coordinate or not direction:
            raise ValueError("Coordinate or direction is empty")
        try:
            dot = coordinate.index(".")
            degrees = float(coordinate[: dot - 2])
            minutes = float(coordinate[dot - 2 :])
            decimal = degrees + minutes / 60.0
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError) as e:
            raise ValueError(f"Invalid coordinate format: {coordinate!r} ({direction!r})") from e

    def _validate_checksum(self, sentence: str) -> bool:
        """Validate NMEA sentence checksum (XOR of chars A-F, 0-9, $)."""
        if "*" not in sentence:
            return False
        body, _, csum = sentence.partition("*")
        if not body.startswith("$"):
            return False
        expected = 0
        for ch in body[1:]:
            expected ^= ord(ch)
        try:
            return expected == int(csum.strip(), 16)
        except ValueError:
            return False

    def _parse_gpgga(self, sentence: str) -> Optional[GPS_readings]:
        """Parse a GPGGA sentence into GPS_readings. Returns None on failure."""
        if not sentence.startswith("$GPGGA"):
            return None

        if not self._validate_checksum(sentence):
            print(f"Checksum mismatch: {sentence!r}", file=sys.stderr)
            return None

        fields = sentence.split(",")
        if len(fields) != 15:
            print(f"Unexpected field count: {len(fields)} (expected 15)", file=sys.stderr)
            return None

        try:
            talker_id = fields[0]
            fix_quality = int(fields[6])
            num_satellites = int(fields[7])
            if fix_quality == 0:
                print("No GPS fix yet.", file=sys.stderr)
                return None

            latitude = self._nmea_to_decimal(fields[2], fields[3])
            longitude = self._nmea_to_decimal(fields[4], fields[5])

            # Altitude is optional; empty string means no fix
            if fields[9]:
                altitude = float(fields[9])
            else:
                altitude = 0.0

            return GPS_readings(latitude, longitude, altitude, num_satellites)
        except (ValueError, IndexError) as e:
            print(f"Error parsing GPGGA sentence: {e}", file=sys.stderr)
            return None

    def read_data(self) -> Optional[GPS_readings]:
        """Read one line from the serial port and parse it."""
        if self.serial_port is None or not self.serial_port.is_open:
            print("Serial port not open.", file=sys.stderr)
            return None

        try:
            raw = self.serial_port.readline()
        except serial.SerialException as e:
            print(f"Serial read error: {e}", file=sys.stderr)
            return None
        except OSError as e:
            print(f"OS read error: {e}", file=sys.stderr)
            return None

        if not raw:
            # Timeout with no data
            return None

        try:
            line = raw.decode("ascii", errors="replace").strip()
        except Exception as e:
            print(f"Decode error: {e}", file=sys.stderr)
            return None

        if not line:
            return None

        return self._parse_gpgga(line)

    def stop(self) -> None:
        """Signal the main loop to stop."""
        self._running = False


def main() -> None:
    reader = GPSReader()

    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        reader.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not reader.connect():
        sys.exit(1)

    try:
        while reader._running:
            readings = reader.read_data()
            if readings is not None:
                print(
                    f"Lat: {readings.latitude:.6f}, "
                    f"Lon: {readings.longitude:.6f}, "
                    f"Alt: {readings.altitude:.2f} m, "
                    f"Sats: {readings.num_satellites}"
                )
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        reader.disconnect()


if __name__ == "__main__":
    main()

