import serial
import time
import signal
import sys

class ESP8266:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=5):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port = None
        self._running = True
        try:
            self.serial_port = serial.Serial(
                port=port,
                baudrate=baudrate,
                timeout=timeout,
                write_timeout=timeout,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE
            )
            print(f"Serial port {port} opened successfully.")
        except serial.SerialException as e:
            print(f"Error opening serial port {port}: {e}")
            self.serial_port = None

    def _send_command(self, command, delay=1, max_retries=3):
        if not self.serial_port or not self.serial_port.is_open:
            print("Serial port not available.")
            return None
        retries = 0
        while retries < max_retries:
            try:
                self.serial_port.reset_input_buffer()
                self.serial_port.write(command.encode('utf-8'))
                time.sleep(delay)
                response = self._read_response()
                if response:
                    return response
                retries += 1
                print(f"Command '{command.strip()}' failed. Retrying ({retries}/{max_retries})...")
            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                retries += 1
        print(f"Command '{command.strip()}' failed after {max_retries} retries.")
        return None

    def _read_response(self):
        if not self.serial_port or not self.serial_port.is_open:
            return None
        response = b""
        start_time = time.time()
        while time.time() - start_time < self.timeout:
            if self.serial_port.in_waiting > 0:
                chunk = self.serial_port.read(self.serial_port.in_waiting)
                if chunk:
                    response += chunk
                    decoded = response.decode('utf-8', errors='ignore')
                    if 'OK' in decoded or 'ERROR' in decoded or 'FAIL' in decoded:
                        return decoded
            else:
                time.sleep(0.1)
        return None

    def test_connection(self):
        return self._send_command('AT\r\n')

    def restart(self):
        return self._send_command('AT+RST\r\n', delay=2)

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP_CUR="{ssid}","{password}"\r\n'
        response = self._send_command(command, delay=5)
        if response:
            return 'WIFI GOT IP' in response
        return False

    def disconnect_wifi(self):
        return self._send_command('AT+CWQAP\r\n')

    def close(self):
        if self.serial_port and self.serial_port.is_open:
            self.serial_port.close()
            print("Serial port closed.")

    def _signal_handler(self, signum, frame):
        print(f"Signal {signum} received, shutting down...")
        self._running = False
        self.close()
        sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, ESP8266._signal_handler)
    signal.signal(signal.SIGTERM, ESP8266._signal_handler)

    esp = ESP8266()
    if esp.serial_port:
        print("Testing connection...")
        if esp.test_connection():
            print("Connection OK.")
            print("Restarting...")
            esp.restart()
            time.sleep(2)
            print("Connecting to WiFi...")
            if esp.connect_wifi('YourSSID', 'YourPassword'):
                print("Connected to WiFi.")
            else:
                print("Failed to connect to WiFi.")
            esp.disconnect_wifi()
        else:
            print("Connection failed.")
        esp.close()
    else:
        print("Failed to initialize ESP8266.")

