import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
LOG_FILE = 'health_readings_log.txt'
READ_TIMEOUT = 1
LOOP_DELAY = 0.1

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_data(log_file, timestamp, data):
    try:
        with open(log_file, 'a') as f:
            f.write(f"{timestamp}, {data}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue

                data = raw.decode('ascii', errors='replace').strip()
                if not data:
                    continue

                timestamp = datetime.now().isoformat(timespec='seconds')
                print(f"{timestamp} - Heart Rate: {data}")
                log_data(LOG_FILE, timestamp, data)

            except ValueError as e:
                print(f"Data parse error: {e}", file=sys.stderr)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
            except IOError as e:
                print(f"I/O error: {e}", file=sys.stderr)

            time.sleep(LOOP_DELAY)

    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

