import serial
import logging
import re
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_connection = None
        self._running = True

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, shutting down...")
        self._running = False

    def connect(self):
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Serial error connecting to GPS: {e}")
            self.serial_connection = None
            return False
        except OSError as e:
            logging.error(f"OS error opening serial port {self.port}: {e}")
            self.serial_connection = None
            return False

    def read_data(self):
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.warning("Serial connection is not open.")
            return None

        try:
            available_bytes = self.serial_connection.in_waiting
            if available_bytes > 0:
                data = self.serial_connection.read(available_bytes).decode('utf-8', errors='ignore').strip()
                return data if data else None
            else:
                return None
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None
        except OSError as e:
            logging.error(f"OS error during serial read: {e}")
            return None

    def parse_gga(self, nmea_sentence):
        if not nmea_sentence:
            return None

        try:
            if not (nmea_sentence.startswith('$GPGGA') or nmea_sentence.startswith('$GNGGA')):
                return None

            parts = nmea_sentence.split(',')
            if len(parts) < 15:
                logging.warning(f"Malformed GGA sentence (too few fields): {nmea_sentence}")
                return None

            utc_time = parts[1] if parts[1] else None
