import serial
import logging
import re
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_connection = None
        self._running = True

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, shutting down...")
        self._running = False

    def connect(self):
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Serial error connecting to GPS: {e}")
            self.serial_connection = None
            return False
        except OSError as e:
            logging.error(f"OS error opening serial port {self.port}: {e}")
            self.serial_connection = None
            return False

    def read_data(self):
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.warning("Serial connection is not open.")
            return None

        try:
            available_bytes = self.serial_connection.in_waiting
            if available_bytes > 0:
                data = self.serial_connection.read(available_bytes).decode('utf-8', errors='ignore').strip()
                return data if data else None
            else:
                return None
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None
        except OSError as e:
            logging.error(f"OS error during serial read: {e}")
            return None

    def parse_gga(self, nmea_sentence):
        if not nmea_sentence:
            return None

        try:
            if not (nmea_sentence.startswith('$GPGGA') or nmea_sentence.startswith('$GNGGA')):
                return None

            parts = nmea_sentence.split(',')
            if len(parts) < 15:
                logging.warning(f"Malformed GGA sentence (too few fields): {nmea_sentence}")
                return None

            utc_time = parts[1] if parts[1] else None
            latitude_raw = parts[2] if parts[2] else None
            latitude_dir = parts[3] if parts[3] else None
            longitude_raw = parts[4] if parts[4] else None
            longitude_dir = parts[5] if parts[5] else None
            fix_quality = parts[6] if parts[6] else None
            num_satellites = parts[7] if parts[7] else None

            if not latitude_raw or not longitude_raw:
                logging.warning("Latitude or longitude missing in GGA sentence.")
                return None

            latitude = self._convert_to_decimal(latitude_raw, latitude_dir)
            longitude = self._convert_to_decimal(longitude_raw, longitude_dir)

            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.warning(f"Error parsing GGA sentence: {e}")
            return None

    def _convert_to_decimal(self, raw, direction):
        if not raw or not direction:
            return None
        try:
            degrees = int(raw[:2])
            minutes = float(raw[2:])
            decimal = degrees + (minutes / 60.0)
            if direction == 'S' or direction == 'W':
                decimal = -decimal
            return decimal
        except (ValueError, IndexError) as e:
            logging.warning(f"Error converting coordinate: {e}")
            return None

