import serial

app = Flask(__name__)

# Global flag for graceful shutdown
_shutdown_requested = threading.Event()


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM by requesting shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    _shutdown_requested.set()


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


class SerialCommunicator:
    """Context-managed serial port wrapper with robust error handling."""

    def __init__(self, port: str, baudrate: int, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self._lock = threading.Lock()
        self._serial: Optional[serial.Serial] = None

    def __enter__(self) -> "SerialCommunicator":
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    def open(self) -> None:
        """Open the serial port; raise serial.SerialException on failure."""
        with self._lock:
            if self._serial is not None and self._serial.is_open:
                return
            try:
                self._serial = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=self.timeout,
                )
                print(f"Serial port {self.port} opened at {self.baudrate} baud.")
            except serial.SerialException as exc:
                self._serial = None
                raise serial.SerialException(
                    f"Failed to open serial port {self.port}: {exc}"
                ) from exc

    def close(self) -> None:
        """Close the serial port if open; idempotent and thread-safe."""
        with self._lock:
            if self._serial is not None:
                try:
                    if self._serial.is_open:
                        self._serial.close()
                        print(f"Serial port {self.port} closed.")
                except serial.SerialException as exc:
                    print(f"Error closing serial port: {exc}")
                finally:
                    self._serial = None

    def send(self, command: str) -> int:
        """Send a command string; return bytes written or -1 on error."""
        with self._lock:
            if self._serial is None or not self._serial.is_open:
                raise serial.SerialException("Serial port is not open.")
            try:
                payload = command.encode("ascii")
                written = self._serial.write(payload)
                self._serial.flush()
                return written
            except serial.SerialException as exc:
                print(f"Serial write error: {exc}")
                return -1

    def receive_line(self) -> Optional[str]:
        """Read one line from the serial port; return None on timeout/error."""
        with self._lock:
            if self._serial is None or not self._serial.is_open:
                return None
            try:
                raw = self._serial.readline()
                if not raw:
                    return None
                return raw.decode("ascii", errors="replace").strip()
            except serial.SerialException as exc:
                print(f"Serial read error: {exc}")
                return None


class DataManager:
    """Thread-safe in-memory data store."""

    def __init__(self, initial_data: List[dict] = None):
        self._data: List[dict] = initial_data if initial_data else []
        self._lock = threading.Lock()

    def get_all(self) -> List[dict]:
        with self._lock:
            return list(self._data)

    def get_by_id(self, item_id: int) -> Optional[dict]:
        with self._lock:
            return next((item for item in self._data if item["id"] == item_id), None)

    def create(self, name: str, done: bool) -> dict:
        if not name or not isinstance(name, str):
            raise ValueError("Name must be a non-empty string.")
        if not isinstance(done, bool):
            raise ValueError("Done must be a boolean.")
        with self._lock:
            new_id = (self._data[-1]["id"] + 1) if self._data else 1
            item = {"id": new_id, "name": name, "done": done}
            self._data.append(item)
            return item


