import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_access(tag_id):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(log_entry)
    except IOError as e:
        print(f'Error writing to log file: {e}')
    print(f'Access granted for RFID Tag: {tag_id}')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f'Connected to RFID reader on {SERIAL_PORT} at {BAUD_RATE} baud.')
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                tag_id = raw.decode('ascii', errors='replace').strip()
                if tag_id:
                    log_access(tag_id)
            except serial.SerialException as e:
                print(f'Serial communication error: {e}')
                break
            except Exception as e:
                print(f'Unexpected error during read: {e}')
    except serial.SerialException as e:
        print(f'Failed to open serial port {SERIAL_PORT}: {e}')
    except Exception as e:
        print(f'Initialization error: {e}')
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

