from flask import Flask, request, jsonify, Response
import serial
import time
import re
import signal
import sys

app = Flask(__name__)

# In-memory data store
data_store = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": True},
]

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1.0

# Global serial handle for cleanup
serial_port = None


def open_serial_port():
    """Open the serial port with error handling."""
    global serial_port
    try:
        serial_port = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
        return True
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        serial_port = None
        return False


def close_serial_port():
    """Close the serial port if open."""
    global serial_port
    if serial_port is not None:
        try:
            if serial_port.is_open:
                serial_port.close()
        except Exception as e:
            print(f"Error closing serial port: {e}", file=sys.stderr)
        finally:
            serial_port = None


def send_scpi_query(query):
    """Send an SCPI query and return the response as text, or None on error."""
    if serial_port is None or not serial_port.is_open:
        return None
    try:
        serial_port.reset_input_buffer()
        serial_port.write(query.encode('ascii'))
        time.sleep(0.1)
        response = serial_port.read(4096)
        if not response:
            return None
        return response.decode('ascii', errors='replace')
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None


@app.route('/version', methods=['GET'])
def get_version():
    """Return the SCPI identification string from the serial instrument."""
    if not open_serial_port():
        return Response(
            "Serial port not available. Check /dev/ttyUSB0 and permissions.\n",
            status=503,
            mimetype='text/plain',
        )
    try:
        response = send_scpi_query('*IDN?\n')
        if response is None:
            return Response(
                "No response from instrument.\n",
                status=503,
                mimetype='text/plain',
            )
        return Response(
            response.replace('\n', '<br>'),
            mimetype='text/html',
        )
    finally:
        close_serial_port()


@app.route('/getdata', methods=['GET'])
def get_all_data():
    """Return the full in-memory data store as JSON."""
    return jsonify(data_store)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_item(item_id):
    """Return a single item by id as JSON, or 404 if not found."""
    item = next((i for i in data_store if i['id'] == item_id), None)
    if item is None:
        return Response("Item not found", status=404, mimetype='text/plain')
    return jsonify(item)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def add_item(item_id, name):
    """Append a new item with given id and name, ignoring existing id."""
    new_item = {
        "id": item_id,
        "name": name,
        "done": False,
    }
    data_store.append(new_item)
    return jsonify(data_store)


@app.route('/postjson', methods=['POST'])
def post_json():
    """Accept JSON or form data, create a new item with auto-incremented id."""
    try:
        if request.is_json:
            data = request.get_json(silent=True)
        else:
            data = request.form.to_dict()

        if not data:
            return jsonify({"error": "No data provided"}), 400

        name = data.get('name', '')
        done_str = data.get('done', 'false')
        done = done_str.lower() in ('true', '1', 'yes')

        new_item = {
            "id": len(data_store) + 1,
            "name": name,
            "done": done,
        }
        data_store.append(new_item)
        return jsonify(data_store)
    except Exception as e:
        print(f"Error processing POST: {e}", file=sys.stderr)
        return jsonify({"error": "Invalid input"}), 400


@app.route('/postjson', methods=['GET'])
def get_json():
    """Return the current in-memory data store as JSON."""
    return jsonify(data_store)


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print("\nShutting down...", file=sys.stderr)
    close_serial_port()
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    app.run(host='0.0.0.0', port=5000)

