import serial
import time
import sys

# Constants for Bluetooth device and serial settings
BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400


def initialize_bluetooth_connection(device, baud_rate):
    """Initializes the serial connection to the Bluetooth device."""
    try:
        bluetooth_connection = serial.Serial(device, baud_rate, timeout=1)
        return bluetooth_connection
    except serial.SerialException as e:
        raise RuntimeError(f"Error initializing Bluetooth connection: {e}")


def send_command(bluetooth_connection, command):
    """Sends a command to the Bluetooth device."""
    try:
        formatted_command = f"X{command}\n"
        bluetooth_connection.write(formatted_command.encode())
        bluetooth_connection.flush()
        print(f"Sent command: {command}")
        time.sleep(0.1)
    except serial.SerialException as e:
        raise RuntimeError(f"Error sending command: {e}")


def main():
    """Main function to handle user input and send commands."""
    bluetooth_connection = None
    try:
        bluetooth_connection = initialize_bluetooth_connection(BLUETOOTH_DEVICE, BLUETOOTH_BAUD_RATE)
        print("Connected to Bluetooth device. Type 'exit' to quit.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
                break

            send_command(bluetooth_connection, user_command)

    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        if bluetooth_connection is not None and bluetooth_connection.is_open:
            bluetooth_connection.close()
            print("Bluetooth connection closed.")


if __name__ == "__main__":
    main()

